    /// Fix round 2 (4): while engaged a messages wait spans the window whatever its timeout, so a
    /// window of chatter costs one slot.
    #[test]
    fn engage_wait_spans_the_window_regardless_of_its_timeout() {
        for request in [json!({"key":HF94_KEY}), json!({"key":HF94_KEY,"timeoutMs":500})] {
            let (_root, context, config, headers) = hf94_wait_fixture(json!({"minMs":100,"defaultMs":2000,"minQuietAfterNewMs":0}));
            let turn = engage_turn(&context);
            let mut arrivals = [3000].into_iter().peekable();
            let (incoming, cfg2) = (context.clone(), config.clone());
            test_clock::install(HF94_T0, move |now| {
                while arrivals.peek().is_some_and(|at| now >= HF94_T0 + at) {
                    let at = arrivals.next().unwrap();
                    engage_arrival(&incoming, &cfg2, &format!("chatter-{at}"), json!({}));
                }
            });
            let _clock = Hf94Clock;
            engage_send(&context, &config, "hi");
            let out = handle_wait_post(&context, &config, &headers, &request.to_string()).unwrap();
            assert_eq!(now_ms(), HF94_T0 + 10000, "{request}: the wait spans the window: {out}");
            assert_eq!(out["newMessages"].as_array().map(Vec::len), Some(1), "{request}: {out}");
            assert_eq!(out["waitCallsUsed"], 1, "{request}: one slot for the window: {out}");
            assert_eq!(out["engagementEnded"], true, "{request}: {out}");
            assert!(turn_budget_ended(&context, HF94_KEY, &turn.id), "{request}: {out}");
        }
    }

    /// Urgent receipts the hub reads for this turn (an urgent seq in it is never re-woken).
    fn engage_urgent_delivered(context: &RuntimeContext, config: &Value, turn: &str) -> Value {
        super::agent::wake_snapshot(context, config,
            &json!({"key":HF94_KEY,"token":"hf94-agent","turnId":turn,"readOnly":true}).to_string())
            .unwrap()["urgentDeliveredSeqs"].clone()
    }

    /// Fix round 3 (1): an urgent message (the owner, not for her) already waiting with under
    /// 1000 ms of window left is handed over in a live turn, never together with end_turn.
    #[test]
    fn engage_window_end_hands_over_a_waiting_urgent_message_in_a_live_turn() {
        let (_root, context, config, headers) = hf94_wait_fixture(json!({"minMs":100,"minQuietAfterNewMs":0}));
        let turn = engage_turn(&context);
        test_clock::install(HF94_T0, |_| {});
        let _clock = Hf94Clock;
        engage_send(&context, &config, "hi");
        test_clock::set(HF94_T0 + 5000);
        engage_arrival(&context, &config, "owner-5000", json!({"userId":"8808","isOwner":true}));
        test_clock::set(HF94_T0 + 9500);
        let request = json!({"key":HF94_KEY,"timeoutMs":300000}).to_string();
        let waiting = handle_wait_post(&context, &config, &headers, &request).unwrap();
        let messages = waiting["newMessages"].as_array().cloned().unwrap_or_default();
        assert_eq!(messages.len(), 1, "the waiting owner message is handed over: {waiting}");
        assert_eq!(messages[0]["text"], "owner-5000", "{waiting}");
        assert_eq!(messages[0]["forYou"], false, "urgent without being for her: {waiting}");
        assert_ne!(waiting["nextAction"], "end_turn", "an urgent message never comes with end_turn: {waiting}");
        assert!(waiting["engagementEnded"].is_null(), "{waiting}");
        assert!(!turn_budget_ended(&context, HF94_KEY, &turn.id), "the turn stays alive to answer it: {waiting}");
        assert_eq!(engage_urgent_delivered(&context, &config, &turn.id), json!([messages[0]["seq"]]),
            "delivered in a live turn, so the hub does not re-wake for it");
        let end = handle_wait_post(&context, &config, &headers, &request).unwrap();
        assert_eq!(end["engagementEnded"], true, "the following wait ends the turn: {end}");
        assert_eq!(end["nextAction"], "end_turn", "{end}");
        assert_eq!(end["newMessages"], json!([]), "{end}");
        assert!(turn_budget_ended(&context, HF94_KEY, &turn.id), "{end}");
    }

