    /// Fix round 6 (1): the same hand-over of a message for her at the window end, with the refund
    /// bound spent (`socialV2.send.maxPerTurn` refunds, default 20) on the last admitted slot. The
    /// refund is refused, so the slot stays consumed and `waitLimitReached` is true, yet the result
    /// gets exactly the urgent treatment: one response step, no `end_turn`, no `turnBudgetEnded`.
    /// The next wait is refused by admission and ends the turn.
    #[test]
    fn engage_fix6_for_her_at_the_window_end_with_refunds_spent_keeps_the_turn_alive() {
        let (_root, context, config, headers) = hf94_wait_fixture(json!({"minMs":100,"minQuietAfterNewMs":0}));
        let turn = engage_turn(&context);
        let mut arrivals = [(2000, json!({})), (10500, json!({"quoteTargetIsSelf":true}))].into_iter().peekable();
        let (incoming, cfg2) = (context.clone(), config.clone());
        test_clock::install(HF94_T0, move |now| {
            while arrivals.peek().is_some_and(|(at, _)| now >= HF94_T0 + at) {
                let (at, extra) = arrivals.next().unwrap();
                engage_arrival(&incoming, &cfg2, &format!("m-{at}"), extra);
            }
        });
        let _clock = Hf94Clock;
        // One admitted wait establishes the turn's real budget scope; the counters are then carried
        // to three spent slots and the refund bound reached (send.maxPerTurn refunds, default 20).
        let warm = handle_wait_post(&context, &config, &headers, &json!({"key":HF94_KEY,"timeoutMs":500}).to_string()).unwrap();
        assert_eq!(warm["waitCallsUsed"], 1, "{warm}");
        let scope = load_social_state_for(&context).unwrap()["conversations"][HF94_KEY]["waitBudget"]["scope"].as_str().unwrap().to_string();
        mutate_social_state_for(&context, |state| {
            state["conversations"][HF94_KEY]["waitBudget"] = json!({"scope":scope.clone(),"used":3,"refunds":20});
            Ok(())
        }).unwrap();
        engage_send(&context, &config, "hi");
        let request = json!({"key":HF94_KEY,"timeoutMs":300000}).to_string();
        let last = handle_wait_post(&context, &config, &headers, &request).unwrap();
        assert_eq!(now_ms(), HF94_T0 + 10500, "the message for her lands with the window end, after the last poll: {last}");
        assert_eq!(last["preSleepObservationForced"], true, "this is the last admitted slot: {last}");
        let texts: Vec<_> = last["newMessages"].as_array().unwrap().iter().map(|m| m["text"].clone()).collect();
        assert_eq!(texts, vec![json!("m-2000"), json!("m-10500")], "the chatter before it comes back with it: {last}");
        assert_eq!(last["newMessages"][1]["forYou"], true, "a quote reply to her is for her: {last}");
        assert_eq!(last["waitLimitReached"], true, "the last admitted slot is spent: {last}");
        assert_eq!(last["waitCallsUsed"], 4, "the consumed slot stays consumed: {last}");
        assert_eq!(last["waitCallsRemaining"], 0, "no extra slot is granted: {last}");
        let budget = load_social_state_for(&context).unwrap()["conversations"][HF94_KEY]["waitBudget"].clone();
        assert_eq!(budget["scope"].as_str(), Some(scope.as_str()), "{budget}");
        assert_eq!(budget["used"], 4, "the exhausted refund bound grants no slot back: {budget}");
        assert_eq!(budget["refunds"], 20, "the exhausted refund bound grants no refund: {budget}");
        assert!(last["engagementEnded"].is_null(), "a message for her at the window end never ends the window: {last}");
        assert!(last["turnBudgetExhausted"].is_null(), "{last}");
        assert_ne!(last["nextAction"], "end_turn", "the handed-over message keeps the turn alive: {last}");
        assert_ne!(last["reason"], END_TURN, "{last}");
        assert!(!turn_budget_ended(&context, HF94_KEY, &turn.id), "the turn stays alive to answer it: {last}");
        let end = handle_wait_post(&context, &config, &headers, &request).unwrap();
        assert_eq!(end["waitLimitReached"], true, "the next wait is refused: {end}");
        assert_eq!(end["nextAction"], "end_turn", "the following wait ends the turn: {end}");
        assert!(turn_budget_ended(&context, HF94_KEY, &turn.id), "{end}");
    }

    /// Fix round 6 (2): her last send puts the engagement window's end exactly on the captured
    /// turn-budget closing point (scaled shape of capMs 515000, ceiling 1800000, window 300000 and
    /// her last send at 1480000: window end 1780000 = 1800000 - the 20000 ms close margin). With
    /// slots and refunds available, a message for her that lands after the last poll is handed over
    /// in a live turn: no `end_turn`, no `turnBudgetExhausted`, no `turnBudgetEnded`. The next wait
    /// ends the turn at that closing point.
    #[test]
    fn engage_fix6_for_her_at_the_turn_budget_close_keeps_the_turn_alive() {
        let (_root, context, config, headers) = hf94_wait_fixture(json!({"minMs":100,"minQuietAfterNewMs":0}));
        let epoch = crate::send_outbox::token_epoch("hf94-agent");
        let turn = crate::turn_ledger::Recorder::begin(&context, HF94_KEY, "dsh", "engage", &epoch, &[], None).unwrap();
        crate::turn_ledger::append_record(&context, &json!({"k":"budget","turn":turn.id,"t":HF94_T0,
            "deadline":HF94_T0+51500,"capMs":51500,"ceiling":HF94_T0+180000})).unwrap();
        // Every window: chatter at its middle, a quote reply to her at its very end (after the last
        // poll). The fifteenth reply at 150000 puts the window end on the closing point 160000.
        let mut arrivals = (0..16).flat_map(|window| [(window * 10000 + 5000, json!({})),
                (window * 10000 + 10000, json!({"quoteTargetIsSelf":true}))]).peekable();
        let (incoming, cfg2) = (context.clone(), config.clone());
        test_clock::install(HF94_T0, move |now| {
            while arrivals.peek().is_some_and(|(at, _)| now >= HF94_T0 + at) {
                let (at, extra) = arrivals.next().unwrap();
                engage_arrival(&incoming, &cfg2, &format!("m-{at}"), extra);
            }
        });
        let _clock = Hf94Clock;
        let request = json!({"key":HF94_KEY,"timeoutMs":300000}).to_string();
        // Fake model: she answers each message for her, so the engaged cap keeps running from her
        // send and the fifteenth window (150000..160000) closes at the ceiling's closing margin.
        for reply in 0..16i64 {
            engage_send(&context, &config, &format!("reply {reply}"));
            let out = handle_wait_post(&context, &config, &headers, &request).unwrap();
            assert_eq!(now_ms(), HF94_T0 + (reply + 1) * 10000, "the engaged wait spans the window: {out}");
            let texts: Vec<_> = out["newMessages"].as_array().unwrap().iter().map(|m| m["text"].clone()).collect();
            assert_eq!(texts, vec![json!(format!("m-{}", reply * 10000 + 5000)), json!(format!("m-{}", reply * 10000 + 10000))],
                "the chatter comes back with the message for her: {out}");
            assert_eq!(out["newMessages"][1]["forYou"], true, "{out}");
            assert_eq!(out["waitCallsUsed"], 0, "the message for her refunds its slot: {out}");
            assert!(out["engagementEnded"].is_null(), "{out}");
            assert!(out["turnBudgetExhausted"].is_null(), "reply {reply}: a hand-over never ends the turn: {out}");
            assert_ne!(out["nextAction"], "end_turn", "reply {reply}: {out}");
            assert!(!turn_budget_ended(&context, HF94_KEY, &turn.id), "reply {reply}: {out}");
        }
        let budget = load_social_state_for(&context).unwrap()["conversations"][HF94_KEY]["waitBudget"].clone();
        assert_eq!(budget["refunds"], 16, "every hand-over refunded inside the send cap: {budget}");
        let end = handle_wait_post(&context, &config, &headers, &request).unwrap();
        assert_eq!(end["turnBudgetExhausted"], true, "the next wait ends the turn at the closing point: {end}");
        assert_eq!(end["nextAction"], "end_turn", "{end}");
        assert!(turn_budget_ended(&context, HF94_KEY, &turn.id), "{end}");
    }

