    /// Fix round 3 (5): an extended engaged wait is re-clipped to the turn budget's closing point.
    #[test]
    fn engage_extended_wait_is_reclipped_by_the_turn_budget() {
        let (_root, context, config, headers) = hf94_wait_fixture(json!({"minMs":100,"minQuietAfterNewMs":0}));
        let epoch = crate::send_outbox::token_epoch("hf94-agent");
        let turn = crate::turn_ledger::Recorder::begin(&context, HF94_KEY, "dsh", "engage", &epoch, &[], None).unwrap();
        // The cap runs out 25 s after her send: the turn closes (20 s margin) before the window ends.
        crate::turn_ledger::append_record(&context, &json!({"k":"budget","turn":turn.id,"t":HF94_T0,
            "deadline":HF94_T0+25000,"capMs":25000,"ceiling":HF94_T0+1_800_000})).unwrap();
        test_clock::install(HF94_T0, |_| {});
        let _clock = Hf94Clock;
        engage_send(&context, &config, "hi");
        let out = handle_wait_post(&context, &config, &headers, &json!({"key":HF94_KEY,"timeoutMs":500}).to_string()).unwrap();
        assert_eq!(now_ms(), HF94_T0 + 5000, "extended past 500 ms, then clipped to the turn's closing point: {out}");
        assert_eq!(out["turnBudgetExhausted"], true, "{out}");
        assert_eq!(out["nextAction"], "end_turn", "{out}");
        assert!(out["engagementEnded"].is_null(), "the turn budget ended it, not the window: {out}");
        assert!(turn_budget_ended(&context, HF94_KEY, &turn.id), "{out}");
    }

    /// Review fix 2: the window-end return first hands over a message for her already waiting.
