    /// Review fix 6: refunds for messages for her stop at the turn's send cap.
    #[test]
    fn engage_for_her_refunds_stop_at_the_turn_send_cap() {
        let (_root, context, mut config, headers) = hf94_wait_fixture(json!({"minMs":100,"minQuietAfterNewMs":0}));
        config["socialV2"]["send"] = json!({"maxPerTurn":2});
        let _turn = engage_turn(&context);
        let mut arrivals = [1000, 2000, 3000].into_iter().peekable();
        let (incoming, cfg2) = (context.clone(), config.clone());
        test_clock::install(HF94_T0, move |now| {
            while arrivals.peek().is_some_and(|at| now >= HF94_T0 + at) {
                let at = arrivals.next().unwrap();
                engage_arrival(&incoming, &cfg2, &format!("q-{at}"), json!({"quoteTargetIsSelf":true}));
            }
        });
        let _clock = Hf94Clock;
        engage_send(&context, &config, "hi");
        let request = json!({"key":HF94_KEY,"timeoutMs":300000}).to_string();
        let mut used = Vec::new();
        for _ in 0..3 {
            let out = handle_wait_post(&context, &config, &headers, &request).unwrap();
            assert_eq!(out["newMessages"][0]["forYou"], true, "{out}");
            used.push(out["waitCallsUsed"].as_u64().unwrap());
        }
        assert_eq!(used, vec![0, 0, 1], "two refunds at send.maxPerTurn=2, then a return for her spends a slot");
    }

