    #[test]
    fn engage_message_for_her_returns_at_once_without_spending_a_wait_slot() {
        let (_root, context, config, headers) = hf94_wait_fixture(json!({"minMs":100,"minQuietAfterNewMs":0}));
        let _turn = engage_turn(&context);
        let mut arrivals = [(2000, json!({"quoteTargetIsSelf":true})), (4000, json!({})),
            (6000, json!({"forYou":true,"forYouReason":"stored ingress reason"}))].into_iter().peekable();
        let (incoming, cfg2) = (context.clone(), config.clone());
        test_clock::install(HF94_T0, move |now| {
            while arrivals.peek().is_some_and(|(at, _)| now >= HF94_T0 + at) {
                let (at, extra) = arrivals.next().unwrap();
                engage_arrival(&incoming, &cfg2, &format!("m-{at}"), extra);
            }
        });
        let _clock = Hf94Clock;
        engage_send(&context, &config, "hi");
        let request = json!({"key":HF94_KEY,"timeoutMs":300000}).to_string();
        let quote = handle_wait_post(&context, &config, &headers, &request).unwrap();
        assert!(now_ms() - HF94_T0 < 2100, "a message for her is not batched: {quote}");
        assert_eq!(quote["newMessages"][0]["forYou"], true, "{quote}");
        let quote_reason = quote["newMessages"][0]["forYouReason"].as_str().unwrap().to_string();
        assert_eq!(quote["waitCallsUsed"], 0, "a wait that hands her a message for her keeps its slot: {quote}");
        assert_eq!(quote["waitCallsRemaining"], 4);
        // Chatter at 4000 does not end the wait; the stored message for her at 6000 does, and both return.
        let stored = handle_wait_post(&context, &config, &headers, &request).unwrap();
        let returned = now_ms() - HF94_T0;
        assert!((6000..6100).contains(&returned), "chatter is collected until a message for her: at {returned}: {stored}");
        assert_eq!(stored["newMessages"].as_array().map(Vec::len), Some(2), "{stored}");
        assert_eq!(stored["newMessages"][0]["forYou"], false, "{stored}");
        assert_ne!(stored["newMessages"][0]["forYouReason"].as_str().unwrap(), quote_reason);
        assert_eq!(stored["newMessages"][1]["forYou"], true, "{stored}");
        assert_eq!(stored["newMessages"][1]["forYouReason"], "stored ingress reason", "ingress classification is kept");
        assert_eq!(stored["waitCallsUsed"], 0, "{stored}");
    }

