    #[test]
    fn engage_long_back_and_forth_outlives_the_start_cap_until_the_ceiling() {
        use std::{cell::{Cell, RefCell}, rc::Rc};
        let (_root, context, mut config, headers) = hf94_wait_fixture(json!({"minMs":100,"minQuietAfterNewMs":0}));
        config["socialV2"]["wake"]["preSleepWaitMs"] = json!(300000);
        let turn = engage_turn(&context);
        let conv = load_social_state_for(&context).unwrap()["conversations"][HF94_KEY].clone();
        let mut driver = crate::session::Driver::new(
            crate::session::scheduler_from_state(crate::wake_cfg_of(&config), &conv), 1);
        driver.sched.cfg.proactive_enabled = false;
        assert_eq!(driver.sched.cfg.turn_hard_cap_ms, 515000);
        driver.apply(crate::session::Input::TurnStart { at_ms: HF94_T0 });
        driver.sched.prompt_running = true;
        let driver = Rc::new(RefCell::new(driver));
        let caps: Rc<RefCell<Vec<i64>>> = Rc::new(RefCell::new(Vec::new()));
        let next_question: Rc<Cell<Option<i64>>> = Rc::new(Cell::new(None));
        let refreshed = Rc::new(Cell::new(0i64));
        let (incoming, cfg2, tick, seen, question, last) =
            (context.clone(), config.clone(), driver.clone(), caps.clone(), next_question.clone(), refreshed.clone());
        test_clock::install(HF94_T0, move |now| {
            if question.get().is_some_and(|at| now >= at) {
                question.set(None);
                engage_arrival(&incoming, &cfg2, &format!("q-{now}"), json!({"quoteTargetIsSelf":true}));
            }
            if now - last.get() >= 1000 {
                last.set(now);
                let state = load_social_state_for(&incoming).unwrap();
                tick.borrow_mut().refresh_observed_state(&state["conversations"][HF94_KEY], now);
            }
            seen.borrow_mut().extend(tick.borrow_mut().apply(crate::session::Input::Tick { at_ms: now })
                .into_iter().filter(|e| e.reason == "turnTimeout").map(|e| e.at_ms));
        });
        let _clock = Hf94Clock;
        let request = json!({"key":HF94_KEY,"timeoutMs":300000}).to_string();
        let mut replies = 0;
        let end = loop {
            // Fake model: answers each message for her; every gap since her send stays under the window.
            engage_send(&context, &config, &format!("reply {replies}"));
            replies += 1;
            next_question.set(Some(now_ms() + 200000));
            let out = handle_wait_post(&context, &config, &headers, &request).unwrap();
            if out["nextAction"] == "end_turn" { break out; }
            assert_eq!(out["newMessages"][0]["forYou"], true, "{out}");
            assert_eq!(out["waitCallsUsed"], 0, "{out}");
            assert!(replies < 20, "the ceiling never ended the turn: {out}");
        };
        assert!(caps.borrow().is_empty(), "the hard cap is measured from her last send: {:?}", caps.borrow());
        assert!(replies >= 8, "the back-and-forth continued well past 515 s: {replies} replies");
        assert_eq!(now_ms(), HF94_T0 + 1_780_000, "the 30-minute ceiling leaves the closing margin: {end}");
        assert_eq!(end["turnBudgetExhausted"], true, "{end}");
        assert!(turn_budget_ended(&context, HF94_KEY, &turn.id), "the ceiling inside a wait is a clean sleep");
        test_clock::set(HF94_T0 + 1_799_999);
        assert!(driver.borrow_mut().apply(crate::session::Input::Tick { at_ms: HF94_T0 + 1_799_999 })
            .iter().all(|e| e.reason != "turnTimeout"));
        let at_ceiling = driver.borrow_mut().apply(crate::session::Input::Tick { at_ms: HF94_T0 + 1_800_000 });
        assert!(at_ceiling.iter().any(|e| e.reason == "turnTimeout" && e.at_ms == HF94_T0 + 1_800_000),
            "the absolute ceiling bounds an engaged turn: {at_ceiling:?}");
    }

    struct Hf94Clock;
    impl Drop for Hf94Clock {
        fn drop(&mut self) { test_clock::uninstall(); }
    }

    fn hf94_wait_fixture(wait: Value) -> (FixtureRoot, RuntimeContext, Value, HashMap<String, String>) {
        hf94_wait_fixture_for_key(HF94_KEY, wait)
    }

    // Wait leases are process-wide by conversation, so parallel wait tests need distinct keys.
    fn hf94_wait_fixture_for_key(key: &str, wait: Value) -> (FixtureRoot, RuntimeContext, Value, HashMap<String, String>) {
        let group: u64 = key.strip_prefix("group:").unwrap().parse().unwrap();
        let root = std::env::temp_dir().join(crate::turn_ledger::mint_id("hf94-wait-"));
        for dir in ["config", "data", "resources"] { std::fs::create_dir_all(root.join(dir)).unwrap(); }
        let config = json!({"consoleToken":"hf94-console", "ownerQQ":8808,
            "allow":{"groups":[group],"private":[8808]},
            "socialV2":{"enabled":true,"wait":wait,"wake":{"preSleepWaitMs":10000}}});
        std::fs::write(root.join("config/config.json"), config.to_string()).unwrap();
        std::fs::write(root.join("dependencies.json"),
            json!({"dsh":"http://127.0.0.1:1","model":"http://127.0.0.1:1","onebot":"http://127.0.0.1:1"}).to_string()).unwrap();
        std::fs::write(root.join("data/mode.json"), r#"{"mode":"reserved2"}"#).unwrap();
        std::fs::write(root.join("data/social-v2.json"), json!({"conversations":{(key):{
            "agentToken":"hf94-agent", "lastIncomingAt":HF94_T0,"lastUnreadSeq":0,"lastReadThroughSeq":0,
            "unread":[],"recentMessages":[],"wakeConfig":{"mode":"diving","infinite":true,"triggers":{"atMention":true}}}}}).to_string()).unwrap();
        let context = RuntimeContext::from_root(&root).unwrap();
        (FixtureRoot(root), context, config, HashMap::from([("x-agent-token".into(),"hf94-agent".into())]))
    }

    #[test]
    fn an_inbound_message_from_a_member_with_an_impression_is_an_observed_interaction() {
        const KEY: &str = "group:148001";
        let (_root, context, config, _headers) = hf94_wait_fixture_for_key(KEY, json!({}));
        let mut state = load_social_state_for(&context).unwrap();
        let entry = |count: i64| json!({"traits":["话少"],"interactionCount":count,"lastSeenAt":1});
        state["conversations"][KEY]["memberImpressions"] = json!({"alice": entry(0), "10002": entry(0), "bob": entry(7)});
        context.write_atomic(RuntimeArea::Data, "social-v2.json", state.to_string().as_bytes()).unwrap();
        let message = |sender: &str, user: &str, time: i64, is_self: bool| json!({"sender":sender,"userId":user,"time":time,"text":"hi","isSelf":is_self});
        record_reserved2_incoming(&context, &config, KEY, "e1", message("alice", "10001", 5_000, false)).unwrap();
        record_reserved2_incoming(&context, &config, KEY, "e2", message("路人", "10002", 6_000, false)).unwrap();
        record_reserved2_incoming(&context, &config, KEY, "e1", message("alice", "10001", 7_000, false)).unwrap();
        record_reserved2_incoming(&context, &config, KEY, "e3", message("bob", "10003", 8_000, true)).unwrap();
        let impressions = load_social_state_for(&context).unwrap()["conversations"][KEY]["memberImpressions"].clone();
        assert_eq!((impressions["alice"]["interactionCount"].clone(), impressions["alice"]["lastSeenAt"].clone()), (json!(1), json!(5_000)),
            "matched by display name, and a journal replay is not a second interaction: {impressions}");
        assert_eq!(impressions["10002"]["interactionCount"], 1, "matched by QQ id: {impressions}");
        assert_eq!(impressions["bob"], entry(7), "the bot's own message is not an interaction");
    }

    #[test]
    fn message_detail_returns_the_stored_full_text_of_a_long_message_and_reports_a_cut() {
        const KEY: &str = "group:148002";
        let (_root, context, config, headers) = hf94_wait_fixture_for_key(KEY, json!({}));
        let long: String = (0..900).map(|i| char::from(b'a' + (i % 26) as u8)).collect();
        let preview: String = long.chars().take(200).collect();
        let mut state = load_social_state_for(&context).unwrap();
        state["conversations"][KEY]["recentMessages"] = json!([
            {"seq":1,"messageId":"7001","sender":"甲","userId":"1001","text":preview,"plain":preview,"time":1,
             "fullText":long,"textChars":900,"textTruncated":true},
            {"seq":2,"messageId":"7002","sender":"乙","userId":"1002","text":preview,"plain":preview,"time":2,
             "fullText":long,"textChars":5000,"textTruncated":true},
            {"seq":3,"messageId":"7003","sender":"丙","userId":"1003","text":"短","plain":"短","time":3},
        ]);
        context.write_atomic(RuntimeArea::Data, "social-v2.json", state.to_string().as_bytes()).unwrap();
        let detail = |id: &str| {
            let query = HashMap::from([("key".to_string(), KEY.to_string()), ("messageId".to_string(), id.to_string())]);
            let (status, body) = agent::message_detail(&context, &config, &headers, &query);
            assert_eq!(status, 200, "{body}");
            body["info"].clone()
        };
        let full = detail("7001");
        assert_eq!(full["text"], json!(long), "the whole message, not its 200-unit preview");
        assert_eq!((full["textTruncated"].clone(), full["textChars"].clone()), (json!(false), json!(900)));
        let by_seq = detail("1");
        assert_eq!(by_seq["text"], json!(long), "a local seq reads the same text");
        let cut = detail("7002");
        assert_eq!((cut["textTruncated"].clone(), cut["textChars"].clone()), (json!(true), json!(5000)), "a message beyond the cap says so");
        let short = detail("3");
        assert_eq!((short["text"].clone(), short["textTruncated"].clone()), (json!("短"), json!(false)));
    }

