    #[test]
    fn hf94_owner_and_bot_mentions_interrupt_messages_and_reply_waits() {
        const HF94_KEY: &str = "group:94102";
        for purpose in ["messages", "reply"] {
            for urgent in ["atSelf", "isOwner"] {
                let (_root, context, config, headers) = hf94_wait_fixture_for_key(HF94_KEY, json!({"minMs":100,"minQuietAfterNewMs":0}));
                let (fake_qq, incoming_config) = (context.clone(), config.clone());
                let mut sent = false;
                test_clock::install(HF94_T0, move |now| {
                    if !sent {
                        sent = true;
                        record_reserved2_incoming(&fake_qq, &incoming_config, HF94_KEY, "urgent-94",
                            json!({"text":"urgent","time":now,"isSelf":false,(urgent):true})).unwrap();
                    }
                });
                let _clock = Hf94Clock;
                let result = handle_wait_post(&context, &config, &headers,
                    &json!({"key":HF94_KEY,"purpose":purpose,"timeoutMs":30000,"quietMs":10000,"minNewMessages":5}).to_string()).unwrap();
                assert_eq!(result["newMessages"].as_array().unwrap().len(), 1, "{purpose} {urgent}: {result}");
                assert!(result["waitedMs"].as_i64().unwrap() <= 100, "urgent arrival must bypass batching and message threshold: {result}");
                if purpose == "reply" {
                    assert_eq!(result["preSleepWaitObserved"], false, "reply quiet never earns observation");
                    assert_eq!(result["preSleepWaitSatisfied"], false);
                }
            }
        }
    }

    #[test]
    fn hf94_turn_cap_reserves_observation_then_requires_end_turn_and_resets_next_turn() {
        const HF94_KEY: &str = "group:94103";
        let (root, context, config, headers) = hf94_wait_fixture_for_key(HF94_KEY, json!({"minMs":100,"minQuietAfterNewMs":0}));
        test_clock::install(HF94_T0, |_| {});
        let _clock = Hf94Clock;
        let epoch = crate::send_outbox::token_epoch("hf94-agent");
        let turn = crate::turn_ledger::Recorder::begin(&context, HF94_KEY, "dsh", "hf94", &epoch, &[], None).unwrap();
        let request = json!({"key":HF94_KEY,"purpose":"reply","timeoutMs":100,"quietMs":0}).to_string();
        for used in 1..=3 {
            let result = handle_wait_post(&context, &config, &headers, &request).unwrap();
            assert_eq!(result["waitCallsUsed"], used, "both purposes share a per-turn budget: {result}");
            assert_eq!(result["waitCallsRemaining"], 4-used);
            assert_eq!(result["preSleepWaitObserved"], false);
        }
        let closing = json!({"key":HF94_KEY,"throughSeq":0,"config":{"mode":"diving","infinite":true}}).to_string();
        let before_observation = agent::wake_config(&context, &config, &headers, &closing);
        assert_eq!(before_observation.0, 400, "short reply waits cannot authorize sleep: {before_observation:?}");
        assert!(before_observation.1.to_string().contains("沉睡前观察"), "{before_observation:?}");
        let final_wait = handle_wait_post(&context, &config, &headers, &request).unwrap();
        assert_eq!(final_wait["purpose"], "messages", "the last slot must perform observation even after a short/reply request");
        assert_eq!(final_wait["waitedMs"], 10000);
        assert_eq!(final_wait["preSleepWaitSatisfied"], true);
        assert_eq!(final_wait["waitCallsUsed"], 4);
        assert_eq!(final_wait["waitCallsRemaining"], 0);
        assert_eq!(final_wait["waitLimitReached"], true);
        assert_eq!(final_wait["nextAction"], "end_turn");
        assert_eq!(final_wait["reason"], END_TURN);
        // Reopen the runtime like a new console reader; reservations are stored in selected state.
        let reopened = RuntimeContext::from_root(&root.0).unwrap();
        let at_cap = now_ms();
        let refused = handle_wait_post(&reopened, &config, &headers, &request).unwrap();
        assert_eq!(now_ms(), at_cap, "an exhausted turn never waits again");
        assert_eq!(refused["waitCallsUsed"], 4);
        assert_eq!(refused["waitLimitReached"], true);
        assert_eq!(refused["preSleepWaitSatisfied"], false, "refusal grants no observation");
        let after_observation = agent::wake_config(&context, &config, &headers, &closing);
        assert_eq!(after_observation.0, 200, "the reserved observation permits closing: {after_observation:?}");
        record_reserved2_incoming(&context, &config, HF94_KEY, "late-after-cap",
            json!({"text":"new question","time":now_ms(),"isSelf":false})).unwrap();
        let (status, blocked) = agent::wake_config(&context, &config, &headers, &closing);
        assert_eq!(status, 200, "exhausted closure must have a bounded re-wake escape: {blocked}");
        assert_eq!(blocked["wakeConfig"]["infinite"], false);
        assert_eq!(blocked["wakeConfig"]["sleepUntil"], crate::sticker::iso_at(now_ms()+30_000));
        assert_eq!(blocked["nextAction"], "end_turn");
        assert!(!blocked.to_string().contains("qq_wait_for_messages(timeoutMs="), "exhausted turns must not be instructed to wait again: {blocked}");
        turn.end("completed", "hf94").unwrap();
        let _next = crate::turn_ledger::Recorder::begin(&context, HF94_KEY, "dsh", "hf94-next", &epoch, &[], None).unwrap();
        let next = handle_wait_post(&context, &config, &headers, &request).unwrap();
        assert_eq!(next["waitCallsUsed"], 1, "a new ledger turn gets a fresh budget with the same token");
        assert_eq!(next["waitedMs"], 0);
        let tools = crate::mcp::tool_list(&config);
        let wait_tool = tools["tools"].as_array().unwrap().iter().find(|t|t["name"]=="qq_wait_for_messages").unwrap();
        assert!(wait_tool["description"].as_str().unwrap().contains("waitLimitReached"), "tool guidance must explain the cap");
    }

