    #[test]
    fn hf94_no_ledger_wait_budget_changes_only_at_the_next_actual_turn() {
        const HF94_KEY: &str = "group:94105";
        let (root, context, config, headers) = hf94_wait_fixture_for_key(HF94_KEY, json!({"minMs":100,"minQuietAfterNewMs":0}));
        test_clock::install(HF94_T0, |_| {});
        let _clock = Hf94Clock;
        // No ledger records: the synthetic root naturally exercises legacy wait scoping.
        assert!(crate::turn_ledger::read_records(&context).unwrap().is_empty());
        mutate_social_state_for(&context, |state| {
            let conv = &mut state["conversations"][HF94_KEY];
            conv["wakeConfig"]["lastWakeAt"] = json!(HF94_T0);
            conv["wakeConfig"]["wakeCount"] = json!(7);
            conv["wakeTimes"] = json!([HF94_T0]);
            Ok(())
        }).unwrap();
        // Older records keep their existing fallback budget until an actual turn begins.
        let request = json!({"key":HF94_KEY,"purpose":"reply","timeoutMs":100,"quietMs":0}).to_string();
        for used in 1..=4 {
            let result = handle_wait_post(&context, &config, &headers, &request).unwrap();
            assert_eq!(result["waitCallsUsed"], used);
            assert_eq!(result["preSleepWaitSatisfied"], used == 4);
            assert_eq!(result["preSleepWaitObserved"], false, "no arrivals: the final slot completes the quiet window");
        }
        let reopened = RuntimeContext::from_root(&root.0).unwrap();
        let boundary_time = now_ms();
        let refused = handle_wait_post(&reopened, &config, &headers, &request).unwrap();
        assert_eq!(refused["waitCallsUsed"], 4);
        assert_eq!(refused["preSleepWaitObserved"], false);
        assert_eq!(now_ms(), boundary_time);
        let closing = json!({"key":HF94_KEY,"throughSeq":0,"config":{"mode":"diving","infinite":true}}).to_string();
        assert_eq!(agent::wake_config(&reopened, &config, &headers, &closing).0, 200);
        assert_eq!(handle_wait_post(&reopened, &config, &headers, &request).unwrap()["waitCallsUsed"], 4,
            "closeout must not replenish the exhausted fallback budget");
        let before = load_social_state_for(&reopened).unwrap();
        begin_legacy_wait_turn(&reopened, HF94_KEY).unwrap();
        let mut after = load_social_state_for(&reopened).unwrap();
        assert!(!after["conversations"][HF94_KEY]["waitTurnId"].as_str().unwrap().is_empty());
        after["conversations"][HF94_KEY].as_object_mut().unwrap().remove("waitTurnId");
        assert_eq!(after, before, "beginning B changes no token, wake bookkeeping, saved budget or observation");
        assert_eq!(now_ms(), boundary_time, "turn identity cannot depend on elapsed time");
        let next = handle_wait_post(&reopened, &config, &headers, &request).unwrap();
        assert_eq!(next["waitCallsUsed"], 1, "actual turn B gets a fresh allowance with unchanged token/time/lastWakeAt");
        assert_eq!(next["preSleepWaitObserved"], false);
        assert!(crate::turn_ledger::read_records(&reopened).unwrap().is_empty());
    }

