    #[test]
    fn wait_token_rotation_retires_lone_wait_in_each_poll_phase() {
        use std::time::{Duration, Instant};
        for (purpose, quiet) in [("reply", false), ("messages", false), ("messages", true)] {
            let (_root, context) = fixture_runtime("wait epoch", "fixture-console-token");
            let key = "group:28004";
            let mut config = cfg();
            config["allow"]["groups"] = json!([28004]);
            config["socialV2"] = json!({"wait":{"minMs":100,"maxMs":10000,"minQuietAfterNewMs":0}});
            context.write_atomic(RuntimeArea::Config, "config.json", config.to_string().as_bytes()).unwrap();
            context.write_atomic(RuntimeArea::Data, "mode.json", br#"{"mode":"reserved2"}"#).unwrap();
            let state = json!({"conversations":{(key):{"agentToken":"old-wait-token",
                "lastIncomingAt":now_ms(), "lastUnreadSeq":if quiet {1} else {0},
                "unread":if quiet {json!([{"seq":1}])} else {json!([])}}}});
            context.write_atomic(RuntimeArea::Data, "social-v2.json", state.to_string().as_bytes()).unwrap();
            let headers = HashMap::from([("x-agent-token".into(), "old-wait-token".into())]);
            std::thread::scope(|scope| {
                let (tx, rx) = std::sync::mpsc::channel();
                let context_ref = &context;
                let config_ref = &config;
                let worker = scope.spawn(move || {
                    tx.send(handle_wait_post(context_ref, config_ref, &headers,
                        &json!({"key":key,"purpose":purpose,"timeoutMs":3000,"quietMs":2500}).to_string())).unwrap();
                });
                let deadline = Instant::now() + Duration::from_secs(2);
                while !wait_leases().lock().unwrap().contains_key(key) {
                    assert!(Instant::now() < deadline);
                    std::thread::sleep(Duration::from_millis(5));
                }
                if quiet { std::thread::sleep(Duration::from_millis(300)); }
                ensure_or_rotate_agent_token(&context, key, true).unwrap();
                let after_rotation = context.read_file(RuntimeArea::Data, "social-v2.json").unwrap();
                let result = rx.recv_timeout(Duration::from_millis(700))
                    .expect("rotated caller must release a lone wait within one poll interval");
                assert_eq!(result.unwrap_err().0, 403);
                worker.join().unwrap();
                assert!(!wait_leases().lock().unwrap().contains_key(key));
                assert_eq!(context.read_file(RuntimeArea::Data, "social-v2.json").unwrap(), after_rotation);
            });
        }
    }

    fn wait_takeover_preserves_new_observation(purpose: &str, quiet_phase: bool) {
        use std::time::{Duration, Instant};
        let (_root, context) = fixture_runtime("wait takeover", "fixture-console-token");
        let key = match (purpose, quiet_phase) {
            ("reply", _) => "group:28001",
            (_, true) => "group:28002",
            _ => "group:28003",
        };
        let mut config = cfg();
        config["allow"]["groups"] = json!([key.trim_start_matches("group:")]);
        config["socialV2"] = json!({
            "enabled": true,
            "wait": {"minMs": 100, "maxMs": 10000, "minQuietAfterNewMs": 0},
            "wake": {"preSleepWaitEnabled": true, "preSleepWaitMs": 10000}
        });
        context.write_atomic(RuntimeArea::Config, "config.json", config.to_string().as_bytes()).unwrap();
        context.write_atomic(RuntimeArea::Data, "mode.json", br#"{"mode":"reserved2"}"#).unwrap();
        let message = json!({"seq":1, "text":"fixture question", "isSelf":false});
        let messages = if quiet_phase { json!([message.clone()]) } else { json!([]) };
        let state = json!({"conversations":{(key):{
            "agentToken":"fixture-wait-agent-token",
            "lastIncomingAt":now_ms(), "lastUnreadSeq":if quiet_phase {1} else {0},
            "lastReadThroughSeq":0, "unread":messages, "recentMessages":messages,
            "wakeConfig":{"mode":"diving", "infinite":true, "triggers":{"atMention":true}}
        }}});
        context.write_atomic(RuntimeArea::Data, "social-v2.json", state.to_string().as_bytes()).unwrap();
        let headers = HashMap::from([("x-agent-token".to_string(), "fixture-wait-agent-token".to_string())]);
        let closing = json!({"key":key, "throughSeq":0, "config":{"mode":"diving", "infinite":true}}).to_string();
        assert_eq!(agent::mark_read(&context, &config, &headers, &closing).0, 400, "mark-read must require an observation initially");
        assert_eq!(agent::wake_config(&context, &config, &headers, &closing).0, 400, "wake-config must require an observation initially");

        std::thread::scope(|scope| {
            let (tx, rx) = std::sync::mpsc::channel();
            let old_context = context.clone();
            let old_config = config.clone();
            let old_headers = headers.clone();
            let old_body = json!({"key":key, "purpose":purpose, "timeoutMs":3000,
                "quietMs":2500, "minNewMessages":if quiet_phase {1} else {2}}).to_string();
            let old = scope.spawn(move || {
                let result = handle_wait_post(&old_context, &old_config, &old_headers, &old_body);
                let _ = tx.send(result);
            });
            let deadline = Instant::now() + Duration::from_secs(2);
            while !wait_leases().lock().unwrap().contains_key(key) {
                assert!(Instant::now() < deadline, "old wait never acquired its lease");
                std::thread::sleep(Duration::from_millis(5));
            }
            if quiet_phase {
                // The initial message takes the ordinary wait into its 200 ms quiet poll.
                std::thread::sleep(Duration::from_millis(300));
            } else {
                mutate_social_state_for(&context, |state| {
                    let conv = &mut state["conversations"][key];
                    conv["lastIncomingAt"] = json!(now_ms());
                    conv["lastUnreadSeq"] = json!(1);
                    conv["unread"] = json!([message.clone()]);
                    conv["recentMessages"] = json!([message.clone()]);
                    Ok(())
                }).unwrap();
            }
            let newer = handle_wait_post(&context, &config, &headers,
                &json!({"key":key, "timeoutMs":10000, "quietMs":0}).to_string()).unwrap();
            assert_eq!(newer["arrived"], true);
            assert_eq!(newer["preSleepWaitObserved"], true);
            assert_eq!(newer["readThroughSeq"], 1);
            let after_newer = context.read_file(RuntimeArea::Data, "social-v2.json").unwrap();
            let superseded = rx.recv_timeout(Duration::from_secs(1))
                .expect("superseded wait must finish within one poll, not its timeout").unwrap();
            old.join().unwrap();
            assert_eq!(superseded["superseded"], true);
            assert_eq!(superseded["arrived"], false);
            assert_eq!(superseded["timeout"], false);
            assert_eq!(superseded["newMessages"], json!([]));
            assert_eq!(context.read_file(RuntimeArea::Data, "social-v2.json").unwrap(), after_newer,
                "superseded handler must not rewrite the newer observation");
        });

        let closing = json!({"key":key, "throughSeq":1, "config":{"mode":"diving", "infinite":true}}).to_string();
        let (status, marked) = agent::mark_read(&context, &config, &headers, &closing);
        assert_eq!(status, 200, "new wait observation must permit mark-read: {marked}");
        assert_eq!(marked["markedCount"], 1);
        let (status, wake) = agent::wake_config(&context, &config, &headers, &closing);
        assert_eq!(status, 200, "new wait observation must permit wake-config: {wake}");
        assert_eq!(wake["wakeConfig"]["confirmedBy"], "set_wake_config");
    }

    /// Review 9: a console wait (no agent token) never supersedes an agent's wait. It is refused
    /// while the agent waits, and the agent's wait finishes with its own observation.
    #[test]
    fn a_non_agent_wait_never_supersedes_an_agent_wait() {
        use std::time::{Duration, Instant};
        for purpose in ["reply", "messages"] {
            let (_root, context) = fixture_runtime("wait agent precedence", "fixture-console-token");
            let key = "group:28006";
            let mut config = cfg();
            config["allow"]["groups"] = json!([28006]);
            config["socialV2"] = json!({"wait":{"minMs":100,"maxMs":10000,"minQuietAfterNewMs":0,
                "batchWindowMs":100,"batchMaxMs":1000}});
            context.write_atomic(RuntimeArea::Config, "config.json", config.to_string().as_bytes()).unwrap();
            context.write_atomic(RuntimeArea::Data, "mode.json", br#"{"mode":"reserved2"}"#).unwrap();
            let state = json!({"conversations":{(key):{"agentToken":"precedence-agent-token",
                "lastIncomingAt":now_ms(), "lastUnreadSeq":0, "lastReadThroughSeq":0,
                "unread":[], "recentMessages":[]}}});
            context.write_atomic(RuntimeArea::Data, "social-v2.json", state.to_string().as_bytes()).unwrap();
            let agent_headers = HashMap::from([("x-agent-token".to_string(), "precedence-agent-token".to_string())]);
            std::thread::scope(|scope| {
                let (tx, rx) = std::sync::mpsc::channel();
                let (context_ref, config_ref) = (&context, &config);
                let agent_body = json!({"key":key, "purpose":purpose, "timeoutMs":5000,
                    "quietMs":if purpose == "reply" {1500} else {0}}).to_string();
                scope.spawn(move || {
                    tx.send(handle_wait_post(context_ref, config_ref, &agent_headers, &agent_body)).unwrap();
                });
                let deadline = Instant::now() + Duration::from_secs(2);
                while !wait_leases().lock().unwrap().contains_key(key) {
                    assert!(Instant::now() < deadline, "agent wait never acquired its lease");
                    std::thread::sleep(Duration::from_millis(5));
                }
                let console = handle_wait_post(&context, &config, &HashMap::new(),
                    &json!({"key":key, "purpose":purpose, "timeoutMs":300, "quietMs":0}).to_string());
                assert_eq!(console.as_ref().map_err(|e| e.0).err(), Some(429),
                    "purpose={purpose}: a console wait must be refused while an agent waits: {console:?}");
                // The agent's wait is still the current one: it sees the next message itself.
                let message = json!({"seq":1, "text":"after the console wait", "isSelf":false});
                mutate_social_state_for(&context, |state| {
                    let conv = &mut state["conversations"][key];
                    conv["lastIncomingAt"] = json!(now_ms());
                    conv["lastUnreadSeq"] = json!(1);
                    conv["unread"] = json!([message.clone()]);
                    conv["recentMessages"] = json!([message.clone()]);
                    Ok(())
                }).unwrap();
                let result = rx.recv_timeout(Duration::from_secs(6)).expect("agent wait must finish").unwrap();
                assert_ne!(result.get("superseded").and_then(Value::as_bool), Some(true), "purpose={purpose}: {result}");
                assert_eq!(result["arrived"], true, "purpose={purpose}: {result}");
                assert_eq!(result["newMessages"][0]["seq"], 1, "purpose={purpose}: {result}");
            });
            assert!(!wait_leases().lock().unwrap().contains_key(key));
        }
        // An agent wait still takes over a console wait, and console waits still supersede each other.
        let key = "group:wait-lease-agent-precedence";
        let console = WaitLease::try_acquire(key, false).expect("free lease");
        let console_again = WaitLease::try_acquire(key, false).expect("a console wait supersedes a console wait");
        assert!(!console.still_current());
        let agent_wait = WaitLease::try_acquire(key, true).expect("an agent wait supersedes a console wait");
        assert!(!console_again.still_current());
        assert!(WaitLease::try_acquire(key, false).is_none(), "a console wait must not supersede an agent wait");
        assert!(agent_wait.still_current());
        drop(agent_wait);
        assert!(!wait_leases().lock().unwrap().contains_key(key));
    }

