    /// Review 1: a failed social-state read (torn replace, parse error) skips that poll; it is
    /// never mistaken for a reset conversation.
    #[test]
    fn wait_skips_a_poll_whose_social_state_read_fails() {
        use std::time::{Duration, Instant};
        for purpose in ["reply", "messages"] {
            let (_root, context) = fixture_runtime("wait read failure", "fixture-console-token");
            let key = "group:28005";
            let mut config = cfg();
            config["allow"]["groups"] = json!([28005]);
            config["socialV2"] = json!({"wait":{"minMs":100,"maxMs":10000,"minQuietAfterNewMs":0,
                "batchWindowMs":100,"batchMaxMs":1000}});
            context.write_atomic(RuntimeArea::Config, "config.json", config.to_string().as_bytes()).unwrap();
            context.write_atomic(RuntimeArea::Data, "mode.json", br#"{"mode":"reserved2"}"#).unwrap();
            let conversation = |messages: Value, seq: i64| json!({"agentToken":"read-failure-token",
                "lastIncomingAt":now_ms(), "lastUnreadSeq":seq, "lastReadThroughSeq":0,
                "unread":messages.clone(), "recentMessages":messages});
            let state = json!({"conversations":{(key):conversation(json!([]), 0)}});
            context.write_atomic(RuntimeArea::Data, "social-v2.json", state.to_string().as_bytes()).unwrap();
            let headers = HashMap::from([("x-agent-token".into(), "read-failure-token".into())]);
            std::thread::scope(|scope| {
                let (tx, rx) = std::sync::mpsc::channel();
                let (context_ref, config_ref) = (&context, &config);
                scope.spawn(move || {
                    tx.send(handle_wait_post(context_ref, config_ref, &headers,
                        &json!({"key":key,"purpose":purpose,"timeoutMs":5000,"quietMs":if purpose == "reply" {1500} else {0}}).to_string())).unwrap();
                });
                let deadline = Instant::now() + Duration::from_secs(2);
                while !wait_leases().lock().unwrap().contains_key(key) {
                    assert!(Instant::now() < deadline);
                    std::thread::sleep(Duration::from_millis(5));
                }
                // Several polls read an unparsable file before the state comes back with a message.
                context.write_atomic(RuntimeArea::Data, "social-v2.json", b"{\"conversations\":").unwrap();
                std::thread::sleep(Duration::from_millis(400));
                let message = json!([{"seq":1, "text":"after the torn read", "isSelf":false}]);
                let state = json!({"conversations":{(key):conversation(message, 1)}});
                context.write_atomic(RuntimeArea::Data, "social-v2.json", state.to_string().as_bytes()).unwrap();
                let result = rx.recv_timeout(Duration::from_secs(5)).expect("wait must finish");
                let result = result.unwrap_or_else(|e| panic!("purpose={purpose}: a failed read ended the wait: {e:?}"));
                assert_eq!(result["arrived"], true, "purpose={purpose}: {result}");
                assert_eq!(result["newMessages"][0]["seq"], 1, "purpose={purpose}: {result}");
            });
        }
    }

    /// Review 2: an invalid turn cap override is refused when it is saved.
    #[test]
    fn social_config_post_refuses_an_invalid_turn_cap_override() {
        let (root, context) = fixture_runtime("turn cap save", "fixture-turn-cap-save-abcdefghij");
        let path = root.0.join("config/config.json");
        let before = std::fs::read(&path).unwrap();
        // Default observation 300000 + quiet extension 125000 + 30000 is the smallest override.
        for invalid in [json!(454999), json!(500000.5), json!("515000"), json!(null), json!(i64::MAX)] {
            let body = json!({"wake":{"turnHardCapMs":invalid}}).to_string();
            let refused = handle_social_config_post(&context, &body);
            assert_eq!(refused.as_ref().map_err(|e| e.0).err(), Some(400), "accepted turnHardCapMs={invalid}: {refused:?}");
            assert_eq!(std::fs::read(&path).unwrap(), before, "a refused save must not touch the file");
        }
        handle_social_config_post(&context, &json!({"wake":{"turnHardCapMs":455000}}).to_string()).unwrap();
        assert_eq!(crate::wake_cfg_of(&context.load_config().unwrap()).turn_hard_cap_ms, 455000);
    }

    /// Review fix 8: the per-turn ceiling is bounded at two hours and validated when it is saved.
    #[test]
    fn engage_turn_ceiling_is_bounded_and_validated_when_saved() {
        let (root, context) = fixture_runtime("turn ceiling save", "fixture-turn-ceiling-save-0123456789");
        let path = root.0.join("config/config.json");
        let before = std::fs::read(&path).unwrap();
        for invalid in [json!(7_200_001), json!(0), json!(-1), json!(1_800_000.5), json!("1800000"), json!(null), json!(i64::MAX)] {
            let body = json!({"wake":{"turnCeilingMs":invalid}}).to_string();
            let refused = handle_social_config_post(&context, &body);
            assert_eq!(refused.as_ref().map_err(|e| e.0).err(), Some(400), "accepted turnCeilingMs={invalid}: {refused:?}");
            assert_eq!(std::fs::read(&path).unwrap(), before, "a refused save must not touch the file");
        }
        // A running bot never fails on a file that has one anyway: it uses the default ceiling.
        for invalid in [json!(7_200_001), json!(i64::MAX)] {
            assert_eq!(crate::wake::turn_ceiling_ms(&json!({"socialV2":{"wake":{"turnCeilingMs":invalid}}})),
                crate::wake::TURN_CEILING_DEFAULT_MS, "turnCeilingMs={invalid}");
        }
        assert_eq!(crate::wake::turn_ceiling_ms(&json!({"socialV2":{"wake":{"turnCeilingMs":7_200_000}}})), 7_200_000);
        handle_social_config_post(&context, &json!({"wake":{"turnCeilingMs":3_600_000}}).to_string()).unwrap();
        assert_eq!(crate::wake_cfg_of(&context.load_config().unwrap()).turn_ceiling_ms, 3_600_000);
    }

    /// An observation in a chatty group returns at the hard batch bound and can close without
    /// cancellation. Its arrival evidence still authorizes the existing no-participation closeout.
    /// The wait handler, the closing calls and the scheduler run on one virtual clock.
    #[test]
    fn a_bounded_observation_with_continuous_arrivals_then_closing_is_not_cancelled() {
        use std::cell::{Cell, RefCell};
        use std::rc::Rc;
        let (_root, context) = fixture_runtime("budget observation", "fixture-console-token");
        let key = "group:29001";
        let mut config = cfg();
        config["allow"]["groups"] = json!([29001]);
        config["socialV2"] = json!({"enabled": true});
        context.write_atomic(RuntimeArea::Config, "config.json", config.to_string().as_bytes()).unwrap();
        context.write_atomic(RuntimeArea::Data, "mode.json", br#"{"mode":"reserved2"}"#).unwrap();
        const T0: i64 = 1_790_000_000_000;
        let conversation = json!({"agentToken":"budget-agent-token", "lastIncomingAt":T0 - 1000,
            "lastUnreadSeq":0, "lastReadThroughSeq":0, "unread":[], "recentMessages":[],
            "wakeConfig":{"mode":"diving", "infinite":true, "triggers":{"atMention":true}}});
        context.write_atomic(RuntimeArea::Data, "social-v2.json",
            json!({"conversations":{(key):conversation.clone()}}).to_string().as_bytes()).unwrap();
        let loaded = context.load_config().unwrap();
        // Dispatch: the scheduler's cap comes from the loaded config, the turn starts at T0.
        let mut driver = crate::session::Driver::new(
            crate::session::scheduler_from_state(crate::wake_cfg_of(&loaded), &conversation), 1);
        driver.sched.cfg.proactive_enabled = false;
        driver.apply(crate::session::Input::TurnStart { at_ms: T0 });
        driver.sched.prompt_running = true;
        let driver = Rc::new(RefCell::new(driver));
        let events = Rc::new(RefCell::new(Vec::<(i64, String)>::new()));
        let arrivals_on = Rc::new(Cell::new(true));
        let last_seq = Rc::new(Cell::new(0i64));
        let next_arrival = Rc::new(Cell::new(T0 + 40_000));
        {
            let (driver, events, arrivals_on, last_seq, next_arrival, context) =
                (driver.clone(), events.clone(), arrivals_on.clone(), last_seq.clone(), next_arrival.clone(), context.clone());
            test_clock::install(T0, move |now| {
                if arrivals_on.get() && now >= next_arrival.get() {
                    // Someone keeps talking every 5 s, faster than any quiet window.
                    let seq = last_seq.get() + 1;
                    last_seq.set(seq);
                    next_arrival.set(now + 5_000);
                    mutate_social_state_for(&context, |state| {
                        let conv = &mut state["conversations"][key];
                        let message = json!({"seq":seq, "text":format!("chatter {seq}"), "isSelf":false, "time":now});
                        conv["unread"].as_array_mut().unwrap().push(message.clone());
                        conv["recentMessages"].as_array_mut().unwrap().push(message);
                        conv["lastUnreadSeq"] = json!(seq);
                        conv["lastIncomingAt"] = json!(now);
                        Ok(())
                    }).unwrap();
                    for e in driver.borrow_mut().apply(crate::session::Input::Message { reason: "question".into(), seq, at_ms: now }) {
                        events.borrow_mut().push((now, e.reason));
                    }
                }
                for e in driver.borrow_mut().apply(crate::session::Input::Tick { at_ms: now }) {
                    events.borrow_mut().push((now, e.reason));
                }
            });
        }
        let headers = HashMap::from([("x-agent-token".to_string(), "budget-agent-token".to_string())]);
        // The agent reads the prompt and replies first, then starts the observation it was told to run.
        test_clock::set(T0 + 40_000);
        let observation = crate::wake::pre_sleep_wait_ms(&loaded);
        let started = now_ms();
        let waited = handle_wait_post(&context, &config, &headers,
            &json!({"key":key, "timeoutMs":observation}).to_string());
        arrivals_on.set(false);
        let waited = waited.unwrap();
        let wait_ended = now_ms();
        // The first arrival is within one poll, then collection is bounded to the default 30 s.
        assert!((30_000..=30_100).contains(&(wait_ended - started)), "wait ended after {} ms: {waited}", wait_ended - started);
        assert_eq!(waited["arrived"], true, "{waited}");
        assert_eq!(waited["preSleepWaitObserved"], true, "{waited}");
        // Closing: mark read, then set the wake configuration, then the DSH turn ends.
        let step = |at: i64| {
            test_clock::set(at);
            for e in driver.borrow_mut().apply(crate::session::Input::Tick { at_ms: at }) {
                events.borrow_mut().push((at, e.reason));
            }
        };
        step(wait_ended + 20_000);
        let closing = json!({"key":key, "throughSeq":last_seq.get(), "config":{"mode":"diving", "infinite":true}}).to_string();
        let (status, marked) = agent::mark_read(&context, &config, &headers, &closing);
        assert_eq!(status, 200, "{marked}");
        step(wait_ended + 30_000);
        let (status, wake) = agent::wake_config(&context, &config, &headers, &closing);
        assert_eq!(status, 200, "{wake}");
        let turn_end = wait_ended + 40_000;
        test_clock::uninstall();
        for e in driver.borrow_mut().apply(crate::session::Input::TurnEnd { at_ms: turn_end }) {
            events.borrow_mut().push((turn_end, e.reason));
        }
        let cancelled: Vec<i64> = events.borrow().iter().filter(|(_, r)| r == "turnTimeout").map(|(at, _)| at - T0).collect();
        assert!(cancelled.is_empty(), "turn cancelled at {cancelled:?} ms after dispatch; turn ended at {} ms", turn_end - T0);
    }

    fn fixture_runtime_with_dsh(
        label: &str,
        token: &str,
        dsh_url: &str,
    ) -> (FixtureRoot, RuntimeContext) {
        static NEXT: std::sync::atomic::AtomicU64 =
            std::sync::atomic::AtomicU64::new(0);
        let sequence = NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let parent = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("..")
            .join(".test-fixtures")
            .join("ticket03-http-fixtures");
        let stamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = parent.join(format!(
            "{label} {} {sequence} {stamp}",
            std::process::id()
        ));
        let root = crate::install_root::development_root(root);
        std::fs::create_dir_all(root.join("config")).unwrap();
        std::fs::create_dir_all(root.join("data")).unwrap();
        std::fs::create_dir_all(root.join("resources").join("roles")).unwrap();
        let config = json!({
            "consoleToken": token,
            "ownerQQ": 7001,
            "allow": { "groups": [], "private": ["7001"] },
            "dsh": {
                "baseUrl": "http://127.0.0.1:1",
                "provider": "fixture",
                "model": "fixture-model",
                "reasoningEffort": "high"
            }
        });
        std::fs::write(
            root.join("config/config.json"),
            serde_json::to_vec_pretty(&config).unwrap(),
        )
        .unwrap();
        std::fs::write(root.join("data/social-v2.json"), b"{}").unwrap();
        std::fs::write(
            root.join("dependencies.json"),
            serde_json::to_vec(&json!({
                "dsh": dsh_url,
                "model": "http://127.0.0.1:49102",
                "onebot": "http://127.0.0.1:49103"
            }))
            .unwrap(),
        )
        .unwrap();
        let context = RuntimeContext::from_root(&root).expect("fixture runtime must validate");
        (FixtureRoot(root), context)
    }

