    #[test]
    fn isolated_sticker_send_outcome_sync_failure_is_not_acknowledged() {
        sticker_durability_case(Some("confirmed"), false);
    }

    #[test]
    fn sticker_authority_gate_spans_write_but_not_response() {
        use std::time::Duration;
        for action in ["send_private_msg", "add_custom_face", "modify_custom_face"] {
            let (url, request_rx, release_response, server) = start_blocking_fake_onebot();
            let (root, context) = fixture_runtime("sticker authority transmission", "fixture-console");
            context.write_atomic(RuntimeArea::Data, "social-v2.json", br#"{"paused":false}"#).unwrap();
            let worker_context = context.clone();
            let action = action.to_string();
            let expected_action = action.clone();
            let (guarded_tx, guarded_rx) = std::sync::mpsc::channel();
            let (proceed_tx, proceed_rx) = std::sync::mpsc::channel();
            let worker = std::thread::spawn(move || {
                STICKER_SUBMISSION_TEST_HOOK.with(|slot| *slot.borrow_mut() = Some(Box::new(move |stage, _| {
                    if stage == "after_guard" {
                        guarded_tx.send(()).unwrap();
                        proceed_rx.recv_timeout(Duration::from_secs(5)).unwrap();
                    }
                })));
                let ob = crate::onebot::OneBot::try_new_url(&url, "fixture".to_string()).unwrap();
                let pending = guarded_sticker_submission(&worker_context, &ob, &action, &json!({}), || Ok(())).unwrap().unwrap();
                pending.outcome()
            });
            guarded_rx.recv_timeout(Duration::from_secs(5)).unwrap();
            assert_eq!(context.open_locked_file(RuntimeArea::Data, "locks/authority.lock").unwrap_err(), "runtime file is already locked");
            let writer_context = context.clone();
            let (done_tx, done_rx) = std::sync::mpsc::channel();
            let (attempt_tx, attempt_rx) = std::sync::mpsc::channel();
            let writer = std::thread::spawn(move || {
                crate::runtime::AUTHORITY_WRITE_TEST_HOOK.with(|slot| *slot.borrow_mut() = Some(Box::new(move || {
                    attempt_tx.send(()).unwrap();
                })));
                let result = handle_activity_post(&writer_context, r#"{"paused":true}"#);
                done_tx.send(result).unwrap();
            });
            attempt_rx.recv_timeout(Duration::from_secs(5)).unwrap();
            assert!(matches!(done_rx.try_recv(), Err(std::sync::mpsc::TryRecvError::Empty)));
            proceed_tx.send(()).unwrap();
            let request = request_rx.recv_timeout(Duration::from_secs(5)).unwrap();
            assert_eq!(request.path, format!("/{expected_action}"));
            assert!(done_rx.recv_timeout(Duration::from_secs(5)).unwrap().is_ok(), "revocation must finish before the held response");
            release_response.send(()).unwrap();
            assert!(worker.join().unwrap().is_ok());
            writer.join().unwrap();
            assert!(server.join().unwrap().is_ok());
            drop(root);
        }
    }

    #[test]
    fn sticker_authority_gate_serializes_cross_process_writes() {
        use std::time::{Duration, Instant};
        const WORKER: &str = "HER_STICKER_AUTHORITY_WORKER_ROOT";
        if let Some(root) = std::env::var_os(WORKER) {
            let root = std::path::PathBuf::from(root);
            let context = RuntimeContext::from_root(&root).unwrap();
            let ready = root.join("data/locks/authority-writer-ready");
            crate::runtime::AUTHORITY_WRITE_TEST_HOOK.with(|slot| *slot.borrow_mut() = Some(Box::new(move || {
                std::fs::write(&ready, b"ready").unwrap();
            })));
            handle_activity_post(&context, r#"{"paused":true}"#).unwrap();
            return;
        }
        let (root, context) = fixture_runtime("sticker cross process authority", "fixture-console");
        context.write_atomic(RuntimeArea::Data, "social-v2.json", br#"{"paused":false}"#).unwrap();
        let gate = context.authority_gate().unwrap();
        let mut child = crate::subprocess::command_without_console(std::env::current_exe().unwrap())
            .args(["--exact", "console::tests::sticker_authority_gate_serializes_cross_process_writes", "--test-threads=1"])
            .env(WORKER, &root.0)
            .stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null())
            .spawn().unwrap();
        let ready = root.0.join("data/locks/authority-writer-ready");
        let deadline = Instant::now() + Duration::from_secs(10);
        while !ready.is_file() && Instant::now() < deadline {
            assert!(child.try_wait().unwrap().is_none(), "writer exited before reaching authority gate");
            std::thread::sleep(Duration::from_millis(5));
        }
        if !ready.is_file() {
            let _ = child.kill(); let _ = child.wait();
            panic!("writer did not reach authority gate");
        }
        assert_eq!(load_social_state_for(&context).unwrap()["paused"], false);
        drop(gate);
        let deadline = Instant::now() + Duration::from_secs(10);
        let status = loop {
            if let Some(status) = child.try_wait().unwrap() { break status; }
            if Instant::now() >= deadline { let _ = child.kill(); let _ = child.wait(); panic!("writer did not finish"); }
            std::thread::sleep(Duration::from_millis(5));
        };
        assert!(status.success());
        assert_eq!(load_social_state_for(&context).unwrap()["paused"], true);
    }

    #[test]
    fn reset_preserves_identified_sticker_liabilities_and_revokes_submission() {
        let (_root, context) = fixture_runtime("reset sticker liabilities", "fixture-console");
        let key = "private:123";
        let now = now_ms();
        let previous = json!({"agentToken":"old", "sendTimes":[now],
            "stickerCollectTimes":[now], "stickerSendProtected":[{"id":"settled", "time":now}],
            "stickerSendPending":[{"id":"send", "time":now}],
            "stickerCollectPending":[{"id":"collect", "time":now}, {"id":"other", "time":now}]});
        let mut replacement = new_conversation(&context);
        preserve_reset_sticker_liabilities(&previous, &mut replacement);
        context.write_atomic(RuntimeArea::Data, "social-v2.json", serde_json::to_vec(&json!({"conversations":{(key):replacement}})).unwrap().as_slice()).unwrap();
        assert!(require_sticker_reservation(&context, key, "stickerSendPending", "send").is_err());
        assert!(require_sticker_reservation(&context, key, "stickerCollectPending", "collect").is_err());
        settle_sticker_quota(&context, key, "stickerCollectTimes", "stickerCollectPending", "collect", now, true).unwrap();
        settle_sticker_quota(&context, key, "sendTimes", "stickerSendPending", "send", now, true).unwrap();
        let state = load_social_state_for(&context).unwrap();
        let conv = &state["conversations"][key];
        // Only pending liabilities survive a reset (JS deletes the whole social state): the
        // settled history copied from `previous` is gone, leaving exactly the two settled slots.
        assert_eq!(conv["sendTimes"], json!([now]));
        assert_eq!(conv["stickerCollectTimes"], json!([now]));
        assert_eq!(conv["stickerCollectPending"][0]["id"], "other");
        assert_eq!(conv["stickerSendProtected"].as_array().unwrap().len(), 2);
    }

