        assert_eq!(resume_send_batch(&context, &cfg, &ob, key, "private", "7001", token, batch).unwrap_err().0, 409);
        assert_eq!(crate::send_outbox::read_records(&context).unwrap(), records);
        assert_no_pending_tcp_connection(&decoy);
