    #[test]
    fn isolated_collect_rollback_does_not_remove_replacement_reservation() {
        let decoy = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        decoy.set_nonblocking(true).unwrap();
        let url = format!("http://127.0.0.1:{}", decoy.local_addr().unwrap().port());
        let key = "private:7001";
        let token = "collect-replacement-fixture";
        let (root, _) = fixture_runtime("collect replacement", "collect-replacement-console");
        let context = prepare_sticker_runtime(&root, &url, &url, "selected-token", &json!({
            "conversations": { (key): { "agentToken": token, "stickerCollectTimes": [],
                "recentMessages": [{ "messageId": "source-1", "isSelf": false,
                    "media": [{ "kind": "image", "url": "https://fixture.invalid/image.png" }] }] } }
        }));
        let headers = HashMap::from([("x-agent-token".to_string(), token.to_string())]);
        let mut replacement = Value::Null;
        let result = handle_collect_sticker_with_fetch(&context, &headers,
            &json!({"key":key,"messageId":"source-1"}).to_string(), &context.load_config().unwrap(),
            |_, _| {
                update_selected_social_state(&context, |state| {
                    replacement = state["conversations"][key]["stickerCollectPending"][0]["time"].clone();
                    let times = &mut state["conversations"][key]["stickerCollectTimes"];
                    // A reset replaces the old reservation with an indistinguishable timestamp.
                    *times = json!([replacement.clone()]);
                    state["conversations"][key]["agentToken"] = json!("replacement-token");
                    Ok(())
                }).unwrap();
                Err("fixture download failure".to_string())
            });
        assert!(result.is_err());
        let state: Value = serde_json::from_slice(&std::fs::read(root.0.join("data/social-v2.json")).unwrap()).unwrap();
        assert_eq!(state["conversations"][key]["agentToken"], "replacement-token");
        assert_eq!(state["conversations"][key]["stickerCollectTimes"], json!([replacement]));
        assert_no_pending_tcp_connection(&decoy);
    }

    #[test]
    fn isolated_collect_missing_emoji_id_keeps_quota_reservation() {
        let (url, request_rx, release_tx, server) = start_blocking_fake_onebot();
        let decoy = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        decoy.set_nonblocking(true).unwrap();
        let decoy_url = format!("http://127.0.0.1:{}", decoy.local_addr().unwrap().port());
        let key = "private:7001";
        let token = "collect-uncertain-fixture";
        let (root, _) = fixture_runtime("collect uncertain", "collect-uncertain-console");
        let context = prepare_sticker_runtime(&root, &url, &decoy_url, "selected-token", &json!({
            "conversations": { (key): { "agentToken": token, "stickerCollectTimes": [],
                "recentMessages": [{ "messageId":"source-1", "isSelf":false,
                    "media":[{"kind":"image", "url":"https://fixture.invalid/image.png"}] }] } }
        }));
        let headers = HashMap::from([("x-agent-token".to_string(), token.to_string())]);
        let mut cfg = context.load_config().unwrap();
        cfg["socialV2"]["sticker"]["collect"]["maxPerMinute"] = json!(1);
        std::thread::scope(|scope| {
            let worker = scope.spawn(|| handle_collect_sticker_with_fetch(&context, &headers,
                &json!({"key":key,"messageId":"source-1"}).to_string(), &cfg,
                |_, _| Ok(b"synthetic image".to_vec())));
            let request = request_rx.recv_timeout(std::time::Duration::from_secs(3)).unwrap();
            assert_eq!(request.path, "/add_custom_face");
            // This fake acknowledges the mutation without an emoji_id.
            release_tx.send(()).unwrap();
            assert!(worker.join().unwrap().is_err());
        });
        server.join().unwrap().unwrap();
        let state: Value = serde_json::from_slice(&std::fs::read(root.0.join("data/social-v2.json")).unwrap()).unwrap();
        assert_eq!(state["conversations"][key]["stickerCollectTimes"].as_array().unwrap().len(), 1);
        let second = handle_collect_sticker_with_fetch(&context, &headers,
            &json!({"key":key,"messageId":"source-1"}).to_string(), &cfg,
            |_, _| Ok(b"second image".to_vec()));
        assert_eq!(second.unwrap_err().0, 429);
        assert_no_pending_tcp_connection(&decoy);
    }

    #[test]
    fn isolated_collect_failure_preserves_selected_state_and_uses_selected_onebot() {
        check_collect_failure(1403);
    }

    #[test]
    fn isolated_collect_unknown_retains_quota_and_other_state() {
        check_collect_failure(100);
    }

    fn check_collect_failure(retcode: i64) {
        let (selected_url, selected_server) = start_fake_onebot_with_retcode(1, Some(retcode), Vec::new());
        let decoy_listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        decoy_listener.set_nonblocking(true).unwrap();
        let decoy_url = format!("http://127.0.0.1:{}", decoy_listener.local_addr().unwrap().port());
        let agent_token = "fixture-collect-agent-a";
        let key = "private:7001";
        let (root_a, _) = fixture_runtime("票据 03 collect failure A", "fixture-console-collect-a");
        let (root_b, _) = fixture_runtime("票据 03 collect failure B", "fixture-console-collect-b");
        let context_a = prepare_sticker_runtime(
            &root_a,
            &selected_url,
            &decoy_url,
            "selected-onebot-token-collect-a",
            &json!({
                "conversations": {
                    (key): {
                        "agentToken": agent_token,
                        "stickerCollectTimes": [],
                        "recentMessages": [{
                            "messageId": "source-1",
                            "seq": 1,
                            "isSelf": false,
                            "media": [{ "kind": "image", "url": "https://fixture.invalid/image.png" }]
                        }],
                        "custom": "must-survive"
                    }
                }
            }),
        );
        let _context_b = prepare_sticker_runtime(
            &root_b,
            &decoy_url,
            "http://127.0.0.1:49103",
            "selected-onebot-token-collect-b",
            &json!({ "conversations": { (key): { "agentToken": "fixture-collect-agent-b", "custom": "b" } } }),
        );
        std::fs::write(
            root_a.0.join("data/stickers.json"),
            serde_json::to_vec_pretty(&json!([{
                "id": "existing-a",
                "source": "fixture",
                "localNote": "preserve"
            }]))
            .unwrap(),
        )
        .unwrap();
        std::fs::write(
            root_b.0.join("data/stickers.json"),
            serde_json::to_vec_pretty(&json!([{ "id": "existing-b", "source": "fixture" }])).unwrap(),
        )
        .unwrap();
        let state_a_before = std::fs::read(root_a.0.join("data/social-v2.json")).unwrap();
        let stickers_a_before = std::fs::read(root_a.0.join("data/stickers.json")).unwrap();
        let state_b_before = std::fs::read(root_b.0.join("data/social-v2.json")).unwrap();
        let stickers_b_before = std::fs::read(root_b.0.join("data/stickers.json")).unwrap();
        let mut headers = HashMap::new();
        headers.insert("x-agent-token".to_string(), agent_token.to_string());

        let mut cfg = context_a.load_config().unwrap();
        cfg["socialV2"]["sticker"]["collect"]["maxPerMinute"] = json!(1);
        let error = handle_collect_sticker_with_fetch(
            &context_a,
            &headers,
            &json!({ "key": key, "messageId": "source-1" }).to_string(),
            &cfg,
            |url, max_bytes| {
                assert_eq!(url, "https://fixture.invalid/image.png");
                assert_eq!(max_bytes, 4096);
                Ok(b"PNG fixture bytes".to_vec())
            },
        )
        .expect_err("fake OneBot rejected collection must be reported");
        assert_eq!(error.0, 500);
        assert!(error.1.contains(&format!("retcode={retcode}")), "{error:?}");
        let requests = selected_server.join().expect("bounded fake OneBot server should finish");
        assert_eq!(requests.len(), 1);
        assert_eq!(requests[0].path, "/add_custom_face");
        assert_eq!(requests[0].authorization, "Bearer selected-onebot-token-collect-a");
        assert!(requests[0].body["file"].as_str().unwrap().starts_with("base64://"));
        assert_no_pending_tcp_connection(&decoy_listener);
        let state_a_after = std::fs::read(root_a.0.join("data/social-v2.json")).unwrap();
        if retcode == 1403 {
            assert_eq!(state_a_after, state_a_before);
        } else {
            let mut expected: Value = serde_json::from_slice(&state_a_before).unwrap();
            let actual: Value = serde_json::from_slice(&state_a_after).unwrap();
            let times = actual["conversations"][key]["stickerCollectTimes"].as_array().unwrap();
            assert_eq!(times.len(), 1);
            assert!(times[0].as_i64().is_some());
            expected["conversations"][key]["stickerCollectTimes"] = json!(times);
            assert_eq!(actual, expected);
            let second = handle_collect_sticker_with_fetch(&context_a, &headers,
                &json!({"key": key, "messageId": "source-1"}).to_string(), &cfg,
                |_, _| panic!("quota must reject before image fetch"));
            assert_eq!(second.unwrap_err().0, 429);
            assert_no_pending_tcp_connection(&decoy_listener);
        }
        assert_eq!(std::fs::read(root_a.0.join("data/stickers.json")).unwrap(), stickers_a_before);
        assert_eq!(std::fs::read(root_b.0.join("data/social-v2.json")).unwrap(), state_b_before);
        assert_eq!(std::fs::read(root_b.0.join("data/stickers.json")).unwrap(), stickers_b_before);
        drop((root_a, root_b));
    }

    #[test]
    #[ignore = "self-image route stays guarded in isolated mode until ticket 20 opens it"]
    fn isolated_http_self_image_and_agent_token_use_selected_runtime() {
        use base64::Engine as _;

        let console_a = "fixture-image-console-token-aaaaaaaa";
        let console_b = "fixture-image-console-token-bbbbbbbb";
        let agent_a = "fixture-image-agent-token-a";
        let agent_b = "fixture-image-agent-token-b";
        let (root_a, context_a) = fixture_runtime("票据 03 self image A", console_a);
        let (root_b, context_b) = fixture_runtime("票据 03 self image B", console_b);
        let image_a = b"\x89PNG\r\nfixture-image-a";
        let image_b = b"\x89PNG\r\nfixture-image-b";
        for (root, token, image) in [
            (&root_a.0, agent_a, image_a.as_slice()),
            (&root_b.0, agent_b, image_b.as_slice()),
        ] {
            std::fs::create_dir_all(root.join("resources/assets")).unwrap();
            std::fs::write(root.join("resources/assets/deepseek娘.png"), image).unwrap();
            let state = json!({
                "conversations": {
                    "private:7001": { "agentToken": token }
                }
            });
            std::fs::write(
                root.join("data/social-v2.json"),
                serde_json::to_vec(&state).unwrap(),
            )
            .unwrap();
        }
        let (port_a, server_a) = start_http_fixture(context_a, 2);
        let (port_b, server_b) = start_http_fixture(context_b, 1);
        let path = "/api/socialV2/self-image?key=private%3A7001";

        let (status_a, response_a) = http_json_with_agent(
            port_a,
            "GET",
            path,
            console_a,
            Some(agent_a),
            None,
        );
        assert_eq!(status_a, 200, "selected A image read failed: {response_a}");
        assert_eq!(response_a["image"]["mimeType"], "image/png");
        let decoded_a = base64::engine::general_purpose::STANDARD
            .decode(response_a["image"]["data"].as_str().unwrap())
            .unwrap();
        assert_eq!(decoded_a, image_a);

        let (wrong_token_status, wrong_token) = http_json_with_agent(
            port_a,
            "GET",
            path,
            console_a,
            Some(agent_b),
            None,
        );
        assert_eq!(wrong_token_status, 403, "B's agent token must not authorize A: {wrong_token}");

        let (status_b, response_b) = http_json_with_agent(
            port_b,
            "GET",
            path,
            console_b,
            Some(agent_b),
            None,
        );
        assert_eq!(status_b, 200, "selected B image read failed: {response_b}");
        let decoded_b = base64::engine::general_purpose::STANDARD
            .decode(response_b["image"]["data"].as_str().unwrap())
            .unwrap();
        assert_eq!(decoded_b, image_b);
        assert_ne!(decoded_a, decoded_b);

        server_a.join().unwrap();
        server_b.join().unwrap();
        drop((root_a, root_b));
    }

    #[test]
    fn isolated_self_image_uses_selected_js_session_policy_and_global_agent_gates() {
        use base64::Engine as _;

        let console_a = "fixture-self-image-policy-console-a";
        let console_b = "fixture-self-image-policy-console-b";
        let agent_a = "fixture-self-image-policy-agent-a";
        let agent_b = "fixture-self-image-policy-agent-b";
        let (root_a, context_a) = fixture_runtime("票据 03 self image policy A", console_a);
        let (root_b, context_b) = fixture_runtime("票据 03 self image policy B", console_b);
        let key = "group:007001";
        let canonical_key = "group:7001";
        for (root, token, marker) in [
            (&root_a.0, agent_a, crate::media_normalize::fixtures::still(image::ImageFormat::Png, 2, 2, false)),
            (&root_b.0, agent_b, crate::media_normalize::fixtures::still(image::ImageFormat::Png, 3, 2, false)),
        ] {
            std::fs::create_dir_all(root.join("resources/assets")).unwrap();
            std::fs::write(root.join("resources/assets/deepseek娘.png"), marker).unwrap();
            std::fs::write(
                root.join("data/social-v2.json"),
                serde_json::to_vec(&json!({
                    "paused": false,
                    "conversations": {
                        (canonical_key): { "agentToken": token }
                    }
                }))
                .unwrap(),
            )
            .unwrap();
        }

        let mut cfg_a = context_a.load_config().unwrap();
        cfg_a["allow"]["groups"] = json!([" 7001 "]);
        cfg_a["socialV2"] = json!({"enabled": true, "tools": {"getSelfImage": true}});
        let mut cfg_b = context_b.load_config().unwrap();
        cfg_b["allow"]["groups"] = json!([7001]);
        cfg_b["socialV2"] = json!({"enabled": true, "tools": {"getSelfImage": true}});
        for (root, cfg) in [(&root_a.0, &cfg_a), (&root_b.0, &cfg_b)] {
            std::fs::write(
                root.join("config/config.json"),
                serde_json::to_vec_pretty(cfg).unwrap(),
            )
            .unwrap();
        }
        cfg_a = context_a.load_config().unwrap();
        cfg_b = context_b.load_config().unwrap();
        let config_a_before = std::fs::read(root_a.0.join("config/config.json")).unwrap();
        let config_b_before = std::fs::read(root_b.0.join("config/config.json")).unwrap();
        let params: HashMap<String, String> =
            [("key".to_string(), key.to_string())].into_iter().collect();
        let headers_a: HashMap<String, String> =
            [("x-agent-token".to_string(), agent_a.to_string())]
                .into_iter()
                .collect();
        let headers_b: HashMap<String, String> =
            [("x-agent-token".to_string(), agent_b.to_string())]
                .into_iter()
                .collect();

        let request = Request {
            method: "GET".to_string(),
            path: "/api/socialV2/self-image".to_string(),
            query: HashMap::new(),
            headers: headers_a.clone(),
            body: String::new(),
            body_too_large: false,
        };
        assert!(social_agent_policy_route(&request));
        for (method, path) in [
            ("POST", "/api/socialV2/self-image"),
            ("GET", "/api/socialV2/self-image/extra"),
        ] {
            assert!(!social_agent_policy_route(&Request {
                method: method.to_string(),
                path: path.to_string(),
                query: HashMap::new(),
                headers: headers_a.clone(),
                body: String::new(),
                body_too_large: false,
            }));
        }
        assert_eq!(social_agent_policy_denial(&request, &cfg_a, &context_a), None);

        let image_a_before = std::fs::read(root_a.0.join("resources/assets/deepseek娘.png"))
            .unwrap();
        let state_a_before = std::fs::read(root_a.0.join("data/social-v2.json")).unwrap();
        let selected_a = handle_self_image(&context_a, &params, &headers_a, &cfg_a)
            .expect("JS-trimmed group allow entry should authorize the selected A image");
        let decoded_a = base64::engine::general_purpose::STANDARD
            .decode(selected_a["image"]["data"].as_str().unwrap())
            .unwrap();
        assert_eq!(decoded_a, image_a_before);
        assert_eq!(selected_a["key"], key, "preserve the caller's raw key");
        assert_eq!(selected_a["image"]["mimeType"], "image/png");

        let image_b_before = std::fs::read(root_b.0.join("resources/assets/deepseek娘.png"))
            .unwrap();
        let state_b_before = std::fs::read(root_b.0.join("data/social-v2.json")).unwrap();
        let selected_b = handle_self_image(&context_b, &params, &headers_b, &cfg_b)
            .expect("selected B should read its own image with its own token");
        let decoded_b = base64::engine::general_purpose::STANDARD
            .decode(selected_b["image"]["data"].as_str().unwrap())
            .unwrap();
        assert_eq!(decoded_b, image_b_before);

        let mut denied_cfg_b = cfg_b.clone();
        denied_cfg_b["deny"] = json!({"groups": ["7001"]});
        std::fs::write(
            root_b.0.join("config/config.json"),
            serde_json::to_vec_pretty(&denied_cfg_b).unwrap(),
        )
        .unwrap();
        denied_cfg_b = context_b.load_config().unwrap();
        let config_b_after_setup = std::fs::read(root_b.0.join("config/config.json")).unwrap();
        assert_eq!(
            handle_self_image(&context_b, &params, &headers_b, &denied_cfg_b).unwrap_err(),
            (403, "目标不在当前模式允许范围内".to_string()),
            "a selected deny-list match must take precedence over allow"
        );

        let paused = br#"{"paused":true,"conversations":{"group:7001":{"agentToken":"fixture-self-image-policy-agent-a"}}}"#;
        std::fs::write(root_a.0.join("data/social-v2.json"), paused).unwrap();
        assert_eq!(
            social_agent_policy_denial(&request, &cfg_a, &context_a),
            Some((403, "AI 已暂停，当前不允许执行 v2 工具".to_string()))
        );
        std::fs::write(&root_a.0.join("data/social-v2.json"), &state_a_before).unwrap();

        let mut disabled_cfg = cfg_a.clone();
        disabled_cfg["socialV2"]["enabled"] = json!(false);
        assert_eq!(
            social_agent_policy_denial(&request, &disabled_cfg, &context_a),
            Some((403, "二代模式已关闭，当前不允许执行 v2 工具".to_string()))
        );
        std::fs::write(root_a.0.join("data/mode.json"), br#"{"mode":"chat"}"#).unwrap();
        assert_eq!(
            social_agent_policy_denial(&request, &cfg_a, &context_a),
            Some((403, "该接口仅 reserved2 模式可用".to_string()))
        );
        std::fs::remove_file(root_a.0.join("data/mode.json")).unwrap();

        assert_eq!(
            std::fs::read(root_a.0.join("resources/assets/deepseek娘.png")).unwrap(),
            image_a_before
        );
        assert_eq!(
            std::fs::read(root_a.0.join("data/social-v2.json")).unwrap(),
            state_a_before
        );
        assert_eq!(
            std::fs::read(root_b.0.join("resources/assets/deepseek娘.png")).unwrap(),
            image_b_before
        );
        assert_eq!(
            std::fs::read(root_b.0.join("data/social-v2.json")).unwrap(),
            state_b_before
        );
        assert_eq!(
            std::fs::read(root_a.0.join("config/config.json")).unwrap(),
            config_a_before
        );
        assert_eq!(
            std::fs::read(root_b.0.join("config/config.json")).unwrap(),
            config_b_after_setup
        );
        drop((root_a, root_b));
    }

