    #[test]
    fn isolated_memory_settings_use_owner_agent_and_selected_config() {
        let token_a = "fixture-settings-console-a-abcdefghij";
        let token_b = "fixture-settings-console-b-abcdefghij";
        let agent_a = "fixture-settings-owner-agent-a";
        let agent_b = "fixture-settings-owner-agent-b";
        let (root_a, context_a) = fixture_runtime("票据 03 settings A", token_a);
        let (root_b, context_b) = fixture_runtime("票据 03 settings B", token_b);

        for (root, agent, burst_enabled, marker) in [
            (&root_a.0, agent_a, false, "settings-a"),
            (&root_b.0, agent_b, true, "settings-b"),
        ] {
            std::fs::write(
                root.join("data/social-v2.json"),
                serde_json::to_vec(&json!({
                    "conversations": {
                        "private:7001": { "agentToken": agent }
                    }
                }))
                .unwrap(),
            )
            .unwrap();
            let mut config: Value = serde_json::from_slice(
                &std::fs::read(root.join("config/config.json")).unwrap(),
            )
            .unwrap();
            config["configMarker"] = json!(marker);
            config["socialV2"] = json!({ "send": { "burstEnabled": burst_enabled } });
            std::fs::write(
                root.join("config/config.json"),
                serde_json::to_vec_pretty(&config).unwrap(),
            )
            .unwrap();
        }

        let config_a_before = std::fs::read(root_a.0.join("config/config.json")).unwrap();
        let config_b_before = std::fs::read(root_b.0.join("config/config.json")).unwrap();
        let config_a = context_a.load_config().unwrap();
        let config_b = context_b.load_config().unwrap();
        let query = HashMap::new();
        let owner_key = "private:7001";
        let headers_a = HashMap::from([("x-agent-token".to_string(), agent_a.to_string())]);
        let headers_b = HashMap::from([("x-agent-token".to_string(), agent_b.to_string())]);

        let all_a = handle_memory_action(
            "settings-get",
            &headers_a,
            &query,
            &json!({ "key": owner_key }).to_string(),
            &config_a,
            &context_a,
        )
        .unwrap();
        let writable = all_a["writable"].as_array().unwrap();
        assert!(writable.contains(&json!("socialV2.send.burstEnabled")));
        assert!(!writable.contains(&json!("socialV2.send.mergeMultiIntoOne")));

        let setting_a = json!({
            "key": owner_key,
            "settingKey": "socialV2.send.burstEnabled",
            "value": true
        })
        .to_string();
        let updated_a = handle_memory_action(
            "settings-set",
            &headers_a,
            &query,
            &setting_a,
            &config_a,
            &context_a,
        )
        .unwrap();
        assert_eq!(updated_a["hot"], true);
        assert_eq!(updated_a["value"], true);

        let denied_extra_path = json!({
            "key": owner_key,
            "settingKey": "socialV2.send.mergeMultiIntoOne",
            "value": true
        })
        .to_string();
        assert_eq!(
            handle_memory_action(
                "settings-set",
                &headers_a,
                &query,
                &denied_extra_path,
                &config_a,
                &context_a,
            )
            .unwrap_err(),
            (
                403,
                "该项不可通过对话修改：socialV2.send.mergeMultiIntoOne（白名单/令牌/路径类必须本地改）"
                    .to_string()
            )
        );

        let console_only = HashMap::from([("x-console-token".to_string(), token_a.to_string())]);
        assert_eq!(
            handle_memory_action(
                "settings-set",
                &console_only,
                &query,
                &setting_a,
                &config_a,
                &context_a,
            )
            .unwrap_err()
            .0,
            403,
            "settings-set requires the selected owner agent token"
        );
        let foreign_agent = HashMap::from([("x-agent-token".to_string(), agent_b.to_string())]);
        assert_eq!(
            handle_memory_action(
                "settings-set",
                &foreign_agent,
                &query,
                &setting_a,
                &config_a,
                &context_a,
            )
            .unwrap_err()
            .0,
            403,
            "root B's agent token cannot modify root A's config"
        );

        let updated_a_config: Value = serde_json::from_slice(
            &std::fs::read(root_a.0.join("config/config.json")).unwrap(),
        )
        .unwrap();
        let unchanged_b_config: Value = serde_json::from_slice(
            &std::fs::read(root_b.0.join("config/config.json")).unwrap(),
        )
        .unwrap();
        assert_eq!(updated_a_config["socialV2"]["send"]["burstEnabled"], true);
        assert_eq!(updated_a_config["configMarker"], "settings-a");
        assert_eq!(unchanged_b_config["socialV2"]["send"]["burstEnabled"], true);
        assert_eq!(unchanged_b_config["configMarker"], "settings-b");
        assert_eq!(
            std::fs::read(root_b.0.join("config/config.json")).unwrap(),
            config_b_before
        );
        assert_ne!(
            std::fs::read(root_a.0.join("config/config.json")).unwrap(),
            config_a_before
        );

        let reloaded_b = handle_memory_action(
            "settings-get",
            &headers_b,
            &query,
            &json!({
                "key": owner_key,
                "settingKey": "socialV2.send.burstEnabled"
            })
            .to_string(),
            &config_b,
            &context_b,
        )
        .unwrap();
        assert_eq!(reloaded_b["value"], true);
    }

    #[test]
    fn isolated_settings_set_rejects_non_object_config_without_touching_either_root() {
        let token_a = "fixture-settings-shape-console-a-abcdefghij";
        let token_b = "fixture-settings-shape-console-b-abcdefghij";
        let agent_a = "fixture-settings-shape-owner-agent-a";
        let agent_b = "fixture-settings-shape-owner-agent-b";
        let (root_a, context_a) = fixture_runtime("票据 03 settings shape A", token_a);
        let (root_b, context_b) = fixture_runtime("票据 03 settings shape B", token_b);
        for (root, agent) in [(&root_a.0, agent_a), (&root_b.0, agent_b)] {
            std::fs::write(
                root.join("data/social-v2.json"),
                serde_json::to_vec(&json!({
                    "conversations": {
                        "private:7001": { "agentToken": agent }
                    }
                }))
                .unwrap(),
            )
            .unwrap();
        }

        let config_a = context_a.load_config().unwrap();
        let config_b = context_b.load_config().unwrap();
        let config_a_path = root_a.0.join("config/config.json");
        let config_b_path = root_b.0.join("config/config.json");
        let config_b_before = std::fs::read(&config_b_path).unwrap();
        let settings_a =
            HashMap::from([("x-agent-token".to_string(), agent_a.to_string())]);
        let settings_b =
            HashMap::from([("x-agent-token".to_string(), agent_b.to_string())]);
        let query = HashMap::new();
        let body_a = json!({
            "key": "private:7001",
            "settingKey": "sendDelayMs",
            "value": 37
        })
        .to_string();

        for invalid_config in [
            &b"null"[..],
            &b"[]"[..],
            &b"7"[..],
            &b"\"root must remain untouched\""[..],
        ] {
            std::fs::write(&config_a_path, invalid_config).unwrap();
            let result = handle_memory_action(
                "settings-set",
                &settings_a,
                &query,
                &body_a,
                &config_a,
                &context_a,
            );
            assert_eq!(
                result.unwrap_err(),
                (400, "selected runtime config is invalid".to_string()),
                "a valid setting must not report success against a non-object selected config"
            );
            assert_eq!(
                std::fs::read(&config_a_path).unwrap(),
                invalid_config.to_vec(),
                "a rejected setting must preserve the exact selected config bytes"
            );
            assert_eq!(
                std::fs::read(&config_b_path).unwrap(),
                config_b_before,
                "root A's invalid config must not affect root B"
            );
        }

        let body_b = json!({
            "key": "private:7001",
            "settingKey": "sendDelayMs",
            "value": 41
        })
        .to_string();
        let updated_b = handle_memory_action(
            "settings-set",
            &settings_b,
            &query,
            &body_b,
            &config_b,
            &context_b,
        )
        .unwrap();
        assert_eq!(updated_b["value"], 41);
        let persisted_b: Value = serde_json::from_slice(&std::fs::read(&config_b_path).unwrap())
            .unwrap();
        assert_eq!(persisted_b["sendDelayMs"], 41);
        assert_eq!(
            std::fs::read(&config_a_path).unwrap(),
            b"\"root must remain untouched\"".to_vec()
        );
    }

    #[test]
    fn isolated_memory_acl_uses_selected_database_and_admin_identity() {
        let token_a = "fixture-acl-console-a-abcdefghij";
        let token_b = "fixture-acl-console-b-abcdefghij";
        let agent_a = "fixture-acl-owner-agent-a";
        let agent_b = "fixture-acl-owner-agent-b";
        let (root_a, context_a) = fixture_runtime("票据 03 ACL A", token_a);
        let (root_b, context_b) = fixture_runtime("票据 03 ACL B", token_b);
        for (root, agent) in [(&root_a.0, agent_a), (&root_b.0, agent_b)] {
            std::fs::write(
                root.join("data/social-v2.json"),
                serde_json::to_vec(&json!({
                    "conversations": {
                        "private:7001": { "agentToken": agent }
                    }
                }))
                .unwrap(),
            )
            .unwrap();
        }
        let conn_a = initialize_fixture_memory_database(&context_a);
        let conn_b = initialize_fixture_memory_database(&context_b);
        drop((conn_a, conn_b));

        let config_a = context_a.load_config().unwrap();
        let config_b = context_b.load_config().unwrap();
        let query = HashMap::new();
        let owner_key = "private:7001";
        let console_a = HashMap::from([("x-console-token".to_string(), token_a.to_string())]);
        let console_b = HashMap::from([("x-console-token".to_string(), token_b.to_string())]);
        let owner_agent_a = HashMap::from([("x-agent-token".to_string(), agent_a.to_string())]);
        let owner_agent_b = HashMap::from([("x-agent-token".to_string(), agent_b.to_string())]);
        let foreign_agent = HashMap::from([("x-agent-token".to_string(), agent_b.to_string())]);

        let grant_a = json!({
            "action": "grant",
            "readerType": "session",
            "readerId": "fixture-reader-a",
            "readType": "session",
            "readId": "fixture-target-a",
            "level": "read"
        })
        .to_string();
        let grant_b = json!({
            "key": owner_key,
            "action": "grant",
            "readerType": "session",
            "readerId": "fixture-reader-b",
            "readType": "session",
            "readId": "fixture-target-b",
            "level": "read"
        })
        .to_string();
        assert!(handle_memory_action(
            "acl",
            &console_a,
            &query,
            &grant_a,
            &config_a,
            &context_a,
        )
        .unwrap()["id"]
        .is_number());
        assert!(handle_memory_action(
            "acl",
            &owner_agent_a,
            &query,
            &grant_b,
            &config_b,
            &context_b,
        )
        .unwrap_err()
        .0 == 403, "root A's agent token cannot modify root B's database");

        assert!(handle_memory_action(
            "acl",
            &owner_agent_b,
            &query,
            &grant_b,
            &config_b,
            &context_b,
        )
        .unwrap()["id"]
        .is_number());

        let list_a = handle_memory_action("acl", &console_a, &query, "{}", &config_a, &context_a)
            .unwrap();
        let list_b = handle_memory_action("acl", &console_b, &query, "{}", &config_b, &context_b)
            .unwrap();
        assert!(list_a.to_string().contains("fixture-target-a"));
        assert!(!list_a.to_string().contains("fixture-target-b"));
        assert!(list_b.to_string().contains("fixture-target-b"));
        assert!(!list_b.to_string().contains("fixture-target-a"));

        let denied = handle_memory_action(
            "acl",
            &foreign_agent,
            &query,
            &json!({
                "key": owner_key,
                "action": "grant",
                "readerType": "session",
                "readerId": "fixture-reader-a",
                "readType": "session",
                "readId": "fixture-forbidden"
            })
            .to_string(),
            &config_a,
            &context_a,
        )
        .unwrap_err();
        assert_eq!(denied.0, 403);
        let after_denied_a = handle_memory_action(
            "acl",
            &console_a,
            &query,
            "{}",
            &config_a,
            &context_a,
        )
        .unwrap();
        assert!(!after_denied_a.to_string().contains("fixture-forbidden"));

        let revoke_a = json!({
            "action": "revoke",
            "readerType": "session",
            "readerId": "fixture-reader-a",
            "readType": "session",
            "readId": "fixture-target-a"
        })
        .to_string();
        let revoked = handle_memory_action(
            "acl",
            &console_a,
            &query,
            &revoke_a,
            &config_a,
            &context_a,
        )
        .unwrap();
        assert_eq!(revoked["removed"], true);
        let final_b = handle_memory_action(
            "acl",
            &console_b,
            &query,
            "{}",
            &config_b,
            &context_b,
        )
        .unwrap();
        assert!(final_b.to_string().contains("fixture-target-b"));
        drop((root_a, root_b));
    }

    #[test]
    fn isolated_memory_admin_actions_reject_invalid_bodies_before_io_or_auth() {
        let token = "fixture-memory-admin-body-token-abcdefghij";
        let (root, context) = fixture_runtime("票据 03 memory admin body", token);
        let config = context.load_config().unwrap();
        let query = HashMap::new();
        let console = HashMap::from([("x-console-token".to_string(), token.to_string())]);
        let owner_agent = HashMap::from([(
            "x-agent-token".to_string(),
            "fixture-memory-admin-body-agent".to_string(),
        )]);
        std::fs::write(
            root.0.join("data/social-v2.json"),
            serde_json::to_vec(&json!({
                "conversations": {
                    "private:7001": {
                        "agentToken": "fixture-memory-admin-body-agent"
                    }
                }
            }))
            .unwrap(),
        )
        .unwrap();
        let database = crate::memory::db_path_for_runtime(&context).unwrap();
        assert!(!database.exists());
        let config_path = root.0.join("config/config.json");
        let config_before = std::fs::read(&config_path).unwrap();

        for (body, expected_error) in [
            ("{", "请求体必须是合法 JSON"),
            ("null", "请求体必须是 JSON 对象"),
            ("[]", "请求体必须是 JSON 对象"),
            ("7", "请求体必须是 JSON 对象"),
        ] {
            let error = handle_memory_action(
                "acl",
                &console,
                &query,
                body,
                &config,
                &context,
            )
            .unwrap_err();
            assert_eq!(error, (400, expected_error.to_string()));
            assert!(!database.exists(), "invalid ACL body must not open the selected DB");

            let error = handle_memory_action(
                "settings-set",
                &owner_agent,
                &query,
                body,
                &config,
                &context,
            )
            .unwrap_err();
            assert_eq!(error, (400, expected_error.to_string()));
            assert_eq!(
                std::fs::read(&config_path).unwrap(),
                config_before,
                "invalid settings body must not write selected config"
            );
        }
        drop(root);
    }

    #[test]
    fn empty_memory_query_token_overrides_console_header_before_memory_handler() {
        let token = "fixture-memory-query-token-abcdefghij";
        let (root, context) = fixture_runtime("ticket 03 memory query auth", token);
        let config = context.load_config().unwrap();
        let config_path = root.0.join("config/config.json");
        let state_path = root.0.join("data/social-v2.json");
        let database = crate::memory::db_path_for_runtime(&context).unwrap();
        let config_before = std::fs::read(&config_path).unwrap();
        let state_before = std::fs::read(&state_path).unwrap();
        assert!(!database.exists());

        let mut request = req("GET", "/api/memory/search", Some(token));
        request.query.insert("token".to_string(), String::new());
        request
            .query
            .insert("key".to_string(), "private:7001".to_string());

        let (status, _, body) = route_with_context(&request, &config, &context);
        assert_eq!(
            status, 401,
            "invalid query auth must reject before the memory handler's agent-token denial: {body}"
        );
        assert_eq!(
            serde_json::from_str::<Value>(&body).unwrap()["error"],
            "未授权：请提供控制台访问令牌"
        );
        assert!(!database.exists(), "denied memory request must not open or create the DB");
        assert_eq!(std::fs::read(&config_path).unwrap(), config_before);
        assert_eq!(std::fs::read(&state_path).unwrap(), state_before);
        drop(root);
    }

