    #[test]
    fn memory_agent_denial_is_independent_of_console_allowlist_preflight() {
        let token = "fixture-memory-allowlist-console-012345";
        let (root, context) = fixture_runtime("ticket 03 memory agent allowlist", token);
        let config = context.load_config().unwrap();
        let state_path = root.0.join("data/social-v2.json");
        let selected_state = serde_json::to_vec(&json!({
            "conversations": {
                "private:7001": { "agentToken": "fixture-live-memory-agent" }
            }
        }))
        .unwrap();
        std::fs::write(&state_path, &selected_state).unwrap();
        let database = crate::memory::db_path_for_runtime(&context).unwrap();
        assert!(!database.exists());

        let mut bodies = Vec::new();
        for key in ["private:7001", "group:999999"] {
            let mut request = req("GET", "/api/memory/search", None);
            request.query.insert("key".to_string(), key.to_string());
            request.headers.insert(
                "x-agent-token".to_string(),
                "fixture-invalid-memory-agent".to_string(),
            );
            assert!(!request.headers.contains_key("x-console-token"));

            let (status, _, body) = route_with_context(&request, &config, &context);
            assert_eq!(status, 403, "memory agent denial for {key}");
            assert_eq!(
                serde_json::from_str::<Value>(&body).unwrap()["error"],
                "agent token 无效（必须是该会话自己的令牌）",
                "memory handler should decide the denial for {key}"
            );
            bodies.push(body);
            assert!(!database.exists(), "invalid memory agent must fail before DB access");
            assert_eq!(std::fs::read(&state_path).unwrap(), selected_state);
        }
        assert_eq!(bodies[0], bodies[1]);
        drop(root);
    }

