    #[test]
    fn isolated_http_memory_acl_and_settings_manage_selected_db_and_config() {
        let token_a = "fixture-memory-admin-token-aaaaaaaa";
        let token_b = "fixture-memory-admin-token-bbbbbbbb";
        let agent_a = "fixture-memory-admin-agent-a";
        let agent_b = "fixture-memory-admin-agent-b";
        let (root_a, context_a) = fixture_runtime("票据 03 memory ACL A", token_a);
        let (root_b, context_b) = fixture_runtime("票据 03 memory ACL B", token_b);
        for (root, agent) in [(&root_a.0, agent_a), (&root_b.0, agent_b)] {
            std::fs::write(
                root.join("data/social-v2.json"),
                serde_json::to_vec(&json!({
                    "conversations": {
                        "private:7001": { "agentToken": agent }
                    }
                }))
                .unwrap(),
            )
            .unwrap();
        }
        let conn_a = initialize_fixture_memory_database(&context_a);
        let conn_b = initialize_fixture_memory_database(&context_b);
        drop((conn_a, conn_b));
        let (port_a, server_a) = start_http_fixture(context_a, 5);
        let (port_b, server_b) = start_http_fixture(context_b, 5);

        let grant_a = json!({
            "action": "grant", "readerType": "session", "readerId": "fixture-reader-a",
            "readType": "session", "readId": "fixture-target-a", "level": "read"
        })
        .to_string();
        let grant_b = json!({
            "action": "grant", "readerType": "session", "readerId": "fixture-reader-b",
            "readType": "session", "readId": "fixture-target-b", "level": "read"
        })
        .to_string();
        let (grant_a_status, grant_a_body) =
            http_json(port_a, "POST", "/api/memory/acl", token_a, Some(&grant_a));
        let (grant_b_status, grant_b_body) =
            http_json(port_b, "POST", "/api/memory/acl", token_b, Some(&grant_b));
        assert_eq!(grant_a_status, 200, "A ACL grant should use A DB: {grant_a_body}");
        assert_eq!(grant_b_status, 200, "B ACL grant should use B DB: {grant_b_body}");
        let list_a = http_json(port_a, "GET", "/api/memory/acl", token_a, None).1;
        let list_b = http_json(port_b, "GET", "/api/memory/acl", token_b, None).1;
        assert!(list_a.to_string().contains("fixture-target-a"));
        assert!(!list_a.to_string().contains("fixture-target-b"));
        assert!(list_b.to_string().contains("fixture-target-b"));
        assert!(!list_b.to_string().contains("fixture-target-a"));

        let revoke_a = json!({
            "action": "revoke", "readerType": "session", "readerId": "fixture-reader-a",
            "readType": "session", "readId": "fixture-target-a"
        })
        .to_string();
        let revoke_b = json!({
            "action": "revoke", "readerType": "session", "readerId": "fixture-reader-b",
            "readType": "session", "readId": "fixture-target-b"
        })
        .to_string();
        assert_eq!(http_json(port_a, "POST", "/api/memory/acl", token_a, Some(&revoke_a)).0, 200);
        assert_eq!(http_json(port_b, "POST", "/api/memory/acl", token_b, Some(&revoke_b)).0, 200);

        let setting_a = json!({
            "key": "private:7001", "settingKey": "socialV2.send.burstEnabled", "value": true
        })
        .to_string();
        let setting_b = json!({
            "key": "private:7001", "settingKey": "socialV2.send.burstEnabled", "value": false
        })
        .to_string();
        let (set_a_status, set_a_body) = http_json_with_agent(
            port_a, "POST", "/api/memory/settings-set", token_a, Some(agent_a), Some(&setting_a),
        );
        let (set_b_status, set_b_body) = http_json_with_agent(
            port_b, "POST", "/api/memory/settings-set", token_b, Some(agent_b), Some(&setting_b),
        );
        assert_eq!(set_a_status, 200, "A selected config should accept the setting: {set_a_body}");
        assert_eq!(set_b_status, 200, "B selected config should accept the setting: {set_b_body}");
        let setting_path = "/api/memory/settings-get?key=private%3A7001&settingKey=socialV2.send.burstEnabled";
        let setting_a_read = http_json_with_agent(
            port_a, "GET", setting_path, token_a, Some(agent_a), None,
        );
        let setting_b_read = http_json_with_agent(
            port_b, "GET", setting_path, token_b, Some(agent_b), None,
        );
        assert_eq!(setting_a_read.0, 200, "A setting read failed: {}", setting_a_read.1);
        assert_eq!(setting_b_read.0, 200, "B setting read failed: {}", setting_b_read.1);
        assert_eq!(setting_a_read.1["value"], true);
        assert_eq!(setting_b_read.1["value"], false);
        let config_a: Value = serde_json::from_slice(
            &std::fs::read(root_a.0.join("config/config.json")).unwrap(),
        )
        .unwrap();
        let config_b: Value = serde_json::from_slice(
            &std::fs::read(root_b.0.join("config/config.json")).unwrap(),
        )
        .unwrap();
        assert_eq!(config_a["socialV2"]["send"]["burstEnabled"], true);
        assert_eq!(config_b["socialV2"]["send"]["burstEnabled"], false);
        let acl_a = crate::memory::open_for_runtime(&RuntimeContext::from_root(&root_a.0).unwrap())
            .unwrap();
        let acl_b = crate::memory::open_for_runtime(&RuntimeContext::from_root(&root_b.0).unwrap())
            .unwrap();
        assert!(crate::memory::list_acl_json(&acl_a).unwrap().is_empty());
        assert!(crate::memory::list_acl_json(&acl_b).unwrap().is_empty());
        // Close the databases before the fixture roots are removed (Windows keeps them locked).
        drop((acl_a, acl_b));
        server_a.join().unwrap();
        server_b.join().unwrap();
        drop((root_a, root_b));
    }

    #[test]
    fn isolated_http_preset_read_write_backup_and_restore_stay_with_each_runtime() {
        let token_a = "fixture-preset-token-aaaaaaaa";
        let token_b = "fixture-preset-token-bbbbbbbb";
        let original_a = fixture_preset_content("preset-owner-A");
        let original_b = fixture_preset_content("preset-owner-B");
        let updated_a = fixture_preset_content("preset-updated-A");
        let updated_b = fixture_preset_content("preset-updated-B");
        let (root_a, context_a) = fixture_runtime("票据 03 预设 A", token_a);
        let (root_b, context_b) = fixture_runtime("票据 03 预设 B", token_b);
        install_fixture_preset(&root_a.0, &original_a);
        install_fixture_preset(&root_b.0, &original_b);
        let (port_a, server_a) = start_http_fixture(context_a, 5);
        let (port_b, server_b) = start_http_fixture(context_b, 5);

        let path = "/api/preset/sim-prompt?preset=qq-chat-v2";
        let (read_a_status, read_a) = http_json(port_a, "GET", path, token_a, None);
        let (read_b_status, read_b) = http_json(port_b, "GET", path, token_b, None);
        assert_eq!(read_a_status, 200, "A selected preset should be readable: {read_a}");
        assert_eq!(read_b_status, 200, "B selected preset should be readable: {read_b}");
        assert_eq!(read_a["content"], original_a);
        assert_eq!(read_b["content"], original_b);
        assert_eq!(read_a["status"]["installed"], true);
        assert_eq!(read_b["status"]["installed"], true);

        let update_a = json!({ "preset": "qq-chat-v2", "content": updated_a }).to_string();
        let update_b = json!({ "preset": "qq-chat-v2", "content": updated_b }).to_string();
        let (write_a_status, write_a) = http_json(port_a, "POST", "/api/preset/sim-prompt", token_a, Some(&update_a));
        let (write_b_status, write_b) = http_json(port_b, "POST", "/api/preset/sim-prompt", token_b, Some(&update_b));
        assert_eq!(write_a_status, 200, "A preset write should succeed: {write_a}");
        assert_eq!(write_b_status, 200, "B preset write should succeed: {write_b}");
        assert_eq!(write_a["synced"], true);
        assert_eq!(write_b["synced"], true);

        let (backups_a_status, backups_a) = http_json(
            port_a, "GET", "/api/preset/sim-prompt/backups?preset=qq-chat-v2", token_a, None,
        );
        let (backups_b_status, backups_b) = http_json(
            port_b, "GET", "/api/preset/sim-prompt/backups?preset=qq-chat-v2", token_b, None,
        );
        assert_eq!(backups_a_status, 200, "A selected backups should list: {backups_a}");
        assert_eq!(backups_b_status, 200, "B selected backups should list: {backups_b}");
        assert_eq!(backups_a["backups"].as_array().unwrap().len(), 1);
        assert_eq!(backups_b["backups"].as_array().unwrap().len(), 1);
        let backup_a = backups_a["backups"][0]["file"].as_str().unwrap();
        let backup_b = backups_b["backups"][0]["file"].as_str().unwrap();
        let restore_a = json!({ "preset": "qq-chat-v2", "file": backup_a }).to_string();
        let restore_b = json!({ "preset": "qq-chat-v2", "file": backup_b }).to_string();
        let (restore_a_status, restore_a_body) = http_json(
            port_a, "POST", "/api/preset/sim-prompt/restore", token_a, Some(&restore_a),
        );
        let (restore_b_status, restore_b_body) = http_json(
            port_b, "POST", "/api/preset/sim-prompt/restore", token_b, Some(&restore_b),
        );
        assert_eq!(restore_a_status, 200, "A selected backup should restore: {restore_a_body}");
        assert_eq!(restore_b_status, 200, "B selected backup should restore: {restore_b_body}");
        let (final_a_status, final_a) = http_json(port_a, "GET", path, token_a, None);
        let (final_b_status, final_b) = http_json(port_b, "GET", path, token_b, None);
        assert_eq!(final_a_status, 200);
        assert_eq!(final_b_status, 200);
        assert_eq!(final_a["content"], original_a);
        assert_eq!(final_b["content"], original_b);

        for (root, expected) in [(&root_a.0, original_a), (&root_b.0, original_b)] {
            let source = root.join("resources/dsh/agent-presets/qq-chat-v2/agent.cordis.yml");
            let installed = root.join("user/dsh/.agent-presets/qq-chat-v2/agent.cordis.yml");
            let source_content = std::fs::read_to_string(source).unwrap();
            let installed_content = std::fs::read_to_string(installed).unwrap();
            assert_eq!(crate::preset_prompt::extract_prefix(&source_content).unwrap(), expected);
            assert_eq!(source_content, installed_content);
            assert!(root.join("data/preset-backups").is_dir());
        }
        server_a.join().unwrap();
        server_b.join().unwrap();
        drop((root_a, root_b));
    }

    #[test]
    fn isolated_http_presets_uses_selected_dsh_dependency_and_credentials_fixture() {
        use base64::Engine as _;

        let secret_a = vec![0x2a; 32];
        let secret_b = vec![0x6b; 32];
        let (base_a, seen_a, dsh_server_a) = start_fake_dsh(secret_a.clone(), "fixture-a".into());
        let (base_b, seen_b, dsh_server_b) = start_fake_dsh(secret_b.clone(), "fixture-b".into());
        let (root_a, context_a) = fixture_runtime_with_dsh("票据 03 DSH A", "fixture-dsh-token-a", &base_a);
        let (root_b, context_b) = fixture_runtime_with_dsh("票据 03 DSH B", "fixture-dsh-token-b", &base_b);
        for (root, secret) in [(&root_a.0, secret_a.as_slice()), (&root_b.0, secret_b.as_slice())] {
            let home = root.join("user/dsh");
            std::fs::create_dir_all(&home).unwrap();
            let encoded = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(secret);
            std::fs::write(home.join(".credentials.yaml"), format!("secret: {encoded}\n")).unwrap();
        }
        let (port_a, console_server_a) = start_http_fixture(context_a, 1);
        let (port_b, console_server_b) = start_http_fixture(context_b, 1);

        let (status_a, body_a) = http_json(port_a, "GET", "/api/presets", "fixture-dsh-token-a", None);
        let (status_b, body_b) = http_json(port_b, "GET", "/api/presets", "fixture-dsh-token-b", None);
        assert_eq!(status_a, 200, "A DSH stub should serve presets: {body_a}");
        assert_eq!(status_b, 200, "B DSH stub should serve presets: {body_b}");
        assert_eq!(body_a["presets"][0]["id"], "fixture-a");
        assert_eq!(body_b["presets"][0]["id"], "fixture-b");

        let (request_a, cookie_a, valid_a) = seen_a.recv().unwrap();
        let (request_b, cookie_b, valid_b) = seen_b.recv().unwrap();
        assert!(request_a.starts_with("POST /api/agentPresets/list HTTP/1.1"));
        assert!(request_b.starts_with("POST /api/agentPresets/list HTTP/1.1"));
        assert!(valid_a, "A DSH request must use A's selected fixture credential");
        assert!(valid_b, "B DSH request must use B's selected fixture credential");
        assert_ne!(cookie_a, cookie_b, "different DSH dependencies and fixture secrets must not share cookies");
        console_server_a.join().unwrap();
        console_server_b.join().unwrap();
        dsh_server_a.join().unwrap();
        dsh_server_b.join().unwrap();
        drop((root_a, root_b));
    }

