    #[test]
    fn selected_slang_config_waits_for_settings_gate_and_keeps_concurrent_setting() {
        use std::time::Duration;
        let (root, context) = fixture_runtime("票据18黑话配置并发", "fixture-slang-config-gate");
        let config_path = root.0.join("config/config.json");
        let held_gate = context
            .open_locked_file(RuntimeArea::Data, SOCIAL_STATE_GATE)
            .unwrap();
        let worker_context = context.clone();
        let worker = std::thread::spawn(move || {
            handle_slang_config(&worker_context, &json!({ "injectMax": 5 }).to_string())
        });
        // While another configuration writer holds the shared gate, a settings change lands.
        std::thread::sleep(Duration::from_millis(300));
        let mut file: Value = serde_json::from_slice(&std::fs::read(&config_path).unwrap()).unwrap();
        assert!(
            file.get("slang").is_none(),
            "slang config must not read-modify-write while the gate is held"
        );
        file["sendDelayMs"] = json!(1234);
        std::fs::write(&config_path, serde_json::to_vec_pretty(&file).unwrap()).unwrap();
        drop(held_gate);
        worker.join().unwrap().expect("slang config applies after the gate is released");
        let after: Value = serde_json::from_slice(&std::fs::read(&config_path).unwrap()).unwrap();
        assert_eq!(after["sendDelayMs"], json!(1234), "the acknowledged settings change survives");
        assert_eq!(after["slang"]["injectMax"], json!(5));
        drop(root);
    }

    #[test]
    fn chain_edits_validate_each_item() {
        // 合法：effort 可省略（省略 = 沿用全局默认）
        let ok = parse_chain_edits(&json!({"chain": [
            {"provider": "deepseek-official", "model": "deepseek-flash"},
            {"provider": "opencode-go", "model": "claude-haiku-5-5", "effort": "medium"}
        ]}))
        .expect("合法链不应报错");
        assert_eq!(ok.len(), 2);
        assert_eq!(ok[0].effort, "");
        assert_eq!(ok[1].effort, "medium");

        // 非法档位要指出第几项
        let err = parse_chain_edits(&json!({"chain": [
            {"provider": "a", "model": "b"},
            {"provider": "c", "model": "d", "effort": "ultra"}
        ]}))
        .unwrap_err();
        assert_eq!(err.0, 400);
        assert!(err.1.contains("第 2 项"), "报错要定位到具体项：{}", err.1);

        // 缺 provider / 缺 model / 不是数组
        assert!(parse_chain_edits(&json!({"chain": [{"model": "b"}]})).is_err());
        assert!(parse_chain_edits(&json!({"chain": [{"provider": "a"}]})).is_err());
        assert!(parse_chain_edits(&json!({"chain": {}})).is_err());
        assert!(parse_chain_edits(&json!({"chain": []})).is_err());
    }

    #[test]
    fn social_v1_post_returns_full_effective_config_with_normalized_partial_storage() {
        let (root, context) = fixture_runtime("reserved-social-response15", "synthetic-token15");
        let mut stored = context.load_config().unwrap();
        stored["social"] = json!({"burstIntervalMinMs":0,"burstIntervalMaxMs":0,
            "longGapMinMs":0,"longGapMaxMs":0,"customMarker":"retained"});
        std::fs::write(root.0.join("config/config.json"), stored.to_string()).unwrap();
        let response = handle_social_v1_config(&context, r#"{"longGapProbability":1}"#).unwrap();
        let mut expected = crate::reserved::config(&stored);
        expected["longGapProbability"] = json!(1);
        assert_eq!(response, json!({"ok":true,"config":expected}),
            "frozen JS returns defaults plus normalized stored fields");
        let saved = context.load_config().unwrap();
        assert!(saved["social"].get("enabled").is_none(), "JS persists only merged partial fields");
        assert_eq!(saved["social"]["longGapMinMs"], 0);
        assert_eq!(saved["social"]["longGapMaxMs"], 0);
        assert_eq!(crate::reserved::view(&context, &saved).unwrap()["config"], saved["social"],
            "the next HTTP read reloads the persisted partial social object (bridge.js:1472)");

        let response = handle_social_v1_config(&context,
            r#"{"longGapMinMs":"9","longGapMaxMs":-2,"longGapProbability":8,"burstIntervalMinMs":-1,"burstIntervalMaxMs":0}"#).unwrap();
        assert_eq!(response["config"]["longGapMinMs"], 0, "negative max clamps then swaps with min");
        assert_eq!(response["config"]["longGapMaxMs"], 9);
        assert_eq!(response["config"]["longGapProbability"], 1);
        assert_eq!(response["config"]["burstIntervalMinMs"], 0);
        assert_eq!(response["config"]["burstIntervalMaxMs"], 0);
        let saved = context.load_config().unwrap();
        assert_eq!(response["config"], saved["social"], "later POSTs start from the reloaded partial config");
        assert_eq!(response["config"], crate::reserved::view(&context, &saved).unwrap()["config"]);
        let response = handle_social_v1_config(&context, r#"{"longGapProbability":-1}"#).unwrap();
        assert_eq!(response["config"]["longGapProbability"], 0);
    }

    #[test]
    fn social_v1_normalization_matches_frozen_js_coercions() {
        let prior = json!({
            "keep": "prior-value",
            "burstProbability": 0.8,
            "followUpEnabled": true,
            "activeCheckMinMs": 900,
            "activeCheckMaxMs": 100
        });
        let body = json!({
            "triggerProbability": "2.5",
            "idleRetryWaitMs": null,
            "activeCheckMinMs": "9",
            "activeCheckMaxMs": 2,
            "activeDurationMinMs": "-3",
            "activeDurationMaxMs": "-10",
            "burstIntervalMinMs": "invalid",
            "burstIntervalMaxMs": "-1",
            "contextWindow": 2.5,
            "skipProbability": "invalid",
            "activeDurationEnabled": {},
            "proactiveEnabled": [],
            "burstEnabled": 0,
            "mustReplyKeywords": [null, 2, false, [], {}]
        });
        let normalized = normalize_social_v1_config(&body, Some(&prior));

        assert_eq!(normalized["keep"], "prior-value");
        assert!(normalized.get("burstProbability").is_none());
        assert!(normalized.get("followUpEnabled").is_none());
        assert_eq!(normalized["triggerProbability"], 1.0);
        assert_eq!(normalized["idleRetryWaitMs"], 0);
        assert_eq!(normalized["activeCheckMinMs"], 2);
        assert_eq!(normalized["activeCheckMaxMs"], 9);
        assert_eq!(normalized["activeDurationMinMs"], "-10");
        assert_eq!(normalized["activeDurationMaxMs"], "-3");
        assert_eq!(normalized["burstIntervalMinMs"], 0);
        assert_eq!(normalized["burstIntervalMaxMs"], 0);
        assert_eq!(normalized["contextWindow"], 3);
        assert!(normalized["skipProbability"].is_null());
        assert_eq!(normalized["activeDurationEnabled"], true);
        assert_eq!(normalized["proactiveEnabled"], true);
        assert_eq!(normalized["burstEnabled"], false);
        assert_eq!(
            normalized["mustReplyKeywords"],
            json!(["null", "2", "false", "", "[object Object]"])
        );
    }

    #[test]
    fn dsh_model_response_uses_only_advertised_reasoning_efforts() {
        let cfg = json!({
            "dsh": {
                "provider": "fixture-provider",
                "model": "fixture-model",
                "reasoningEffort": "medium"
            }
        });
        let catalog = json!({
            "groups": [{
                "id": "fixture-provider",
                "models": [{
                    "id": "fixture-model",
                    "reasoning": {
                        "defaultEffort": "max",
                        "efforts": [
                            { "id": "low", "name": "Light" },
                            { "id": "unknown", "name": "Ignore" },
                            { "id": "max" }
                        ]
                    }
                }]
            }]
        });
        let response = dsh_model_response(&cfg, Some(&catalog));
        assert_eq!(response["provider"], "fixture-provider");
        assert_eq!(response["model"], "fixture-model");
        assert_eq!(response["reasoningEffort"], "medium");
        assert_eq!(response["options"], json!(["low", "max"]));
        assert_eq!(
            response["labels"]["low"],
            json!({"name":"Light", "description":""})
        );
        assert_eq!(
            response["labels"]["max"],
            json!({"name":"", "description":""})
        );
        assert_eq!(response["providerDefault"], "max");
        assert_eq!(response["catalogSource"], "dsh");

        let fallback = dsh_model_response(&json!({}), None);
        assert_eq!(fallback["provider"], "deepseek-official");
        assert_eq!(fallback["model"], "deepseek-flash");
        assert_eq!(fallback["reasoningEffort"], "max");
        assert_eq!(fallback["options"], json!(["low", "medium", "high", "max"]));
        assert_eq!(fallback["labels"], json!({}));
        assert_eq!(fallback["providerDefault"], Value::Null);
        assert_eq!(fallback["catalogSource"], "fallback");
    }

    #[test]
    fn isolated_model_and_social_config_handlers_use_only_selected_config() {
        let token_a = "fixture-batch13-token-a-abcdefghij";
        let token_b = "fixture-batch13-token-b-abcdefghij";
        let (root_a, context_a) = fixture_runtime("票据 03 batch13 A", token_a);
        let (root_b, context_b) = fixture_runtime("票据 03 batch13 B", token_b);
        let config_b_before = std::fs::read(root_b.0.join("config/config.json")).unwrap();

        let social = handle_social_v1_config(
            &context_a,
            &json!({
                "customMarker": "selected-a",
                "triggerProbability": "1.5",
                "contextWindow": 4.5,
                "mustReplyKeywords": [null, "hello"]
            })
            .to_string(),
        )
        .expect("selected social config should be written");
        assert_eq!(social["config"]["customMarker"], "selected-a");
        assert_eq!(social["config"]["triggerProbability"], 1.0);
        assert_eq!(social["config"]["contextWindow"], 5);
        assert_eq!(
            social["config"]["mustReplyKeywords"],
            json!(["null", "hello"])
        );

        let effort = handle_dsh_effort(&context_a, r#"{"reasoningEffort":" MAX "}"#)
            .expect("selected DSH effort should be written");
        assert_eq!(effort, json!({"ok": true, "reasoningEffort": "max"}));

        let chain = handle_model_chain_post(
            &context_a,
            r#"{"chain":[{"provider":"fixture-provider","model":"fixture-model","effort":"medium"}]}"#,
        )
        .expect("selected model chain should be written");
        assert_eq!(chain["global"]["provider"], "fixture-provider");
        let selected_config = context_a.load_config().unwrap();
        let selected_chain = handle_model_chain_get(&selected_config, None);
        assert_eq!(selected_chain["global"]["provider"], "fixture-provider");
        assert_eq!(selected_chain["chain"][0]["source"], "global");
        assert_eq!(
            std::fs::read(root_b.0.join("config/config.json")).unwrap(),
            config_b_before,
            "root B config must remain byte-identical"
        );

        let broken = b"{broken selected config";
        std::fs::write(root_a.0.join("config/config.json"), broken).unwrap();
        let social_error = handle_social_v1_config(&context_a, r#"{"triggerProbability":0.2}"#)
            .expect_err("malformed selected config must reject writes");
        let effort_error = handle_dsh_effort(&context_a, r#"{"reasoningEffort":"high"}"#)
            .expect_err("malformed selected config must reject effort changes");
        let chain_error =
            handle_model_chain_post(&context_a, r#"{"chain":[{"provider":"p","model":"m"}]}"#)
        .expect_err("malformed selected config must reject model-chain writes");
        assert_eq!(social_error.0, 503);
        assert_eq!(effort_error.0, 503);
        assert_eq!(chain_error.0, 503);
        assert_eq!(
            std::fs::read(root_a.0.join("config/config.json")).unwrap(),
            broken,
            "failed selected config writes must preserve the malformed bytes"
        );
        assert_eq!(
            std::fs::read(root_b.0.join("config/config.json")).unwrap(),
            config_b_before,
            "no handler may fall back to or mutate the other runtime"
        );

        drop((root_a, root_b, context_b));
    }

    #[test]
    fn isolated_social_mutations_reject_invalid_bodies_before_config_io() {
        let token_a = "fixture-batch13-body-a-abcdefghij";
        let token_b = "fixture-batch13-body-b-abcdefghij";
        let (root_a, context_a) = fixture_runtime("票据 03 body A", token_a);
        let (root_b, context_b) = fixture_runtime("票据 03 body B", token_b);
        let config_a = root_a.0.join("config/config.json");
        let config_b = root_b.0.join("config/config.json");
        let malformed_config = b"{ malformed selected config";
        let config_b_before = std::fs::read(&config_b).unwrap();

        assert_eq!(parse_object_body(" \r\n\t").unwrap(), json!({}));

        // A damaged config proves request-body validation happens first. Every
        // rejected request must leave both selected roots byte-identical.
        std::fs::write(&config_a, malformed_config).unwrap();
        for (body, expected_message) in [
            ("{", "请求体必须是合法 JSON"),
            ("\u{0085}", "请求体必须是合法 JSON"),
            ("null", "请求体必须是 JSON 对象"),
            ("[]", "请求体必须是 JSON 对象"),
            ("7", "请求体必须是 JSON 对象"),
            ("\"scalar\"", "请求体必须是 JSON 对象"),
        ] {
            let social_error = handle_social_v1_config(&context_a, body).unwrap_err();
            let effort_error = handle_dsh_effort(&context_a, body).unwrap_err();
            for error in [social_error, effort_error] {
                assert_eq!(error.0, 400);
                assert_eq!(error.1, expected_message);
            }
            assert_eq!(std::fs::read(&config_a).unwrap(), malformed_config);
            assert_eq!(std::fs::read(&config_b).unwrap(), config_b_before);
        }

        // Empty object keeps the existing business validation and write paths.
        let effort_error = handle_dsh_effort(&context_b, "\r\n").unwrap_err();
        assert_eq!(effort_error.0, 400);
        assert_eq!(effort_error.1, "思考强度只能是 low / medium / high / max");
        assert_eq!(std::fs::read(&config_b).unwrap(), config_b_before);

        drop((root_a, root_b, context_a, context_b));
    }

