    const TOKEN: &str = "abcdefabcdefabcdefabcdefabcdefab";

    fn post_json(path: &str, token: Option<&str>, body: Value) -> Request {
        let mut r = req("POST", path, token);
        r.body = body.to_string();
        r
    }

    fn get_with_query(path: &str, token: Option<&str>, query: &[(&str, &str)]) -> Request {
        let mut r = req("GET", path, token);
        r.query = query
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect();
        r
    }

    #[test]
    fn session_allowed_reads_numeric_and_string_ids_in_both_lists() {
        let cfg = json!({"allow": {"groups": [1, "2"], "private": [3, "4"]}});
        for key in ["group:1", "group:2", "private:3", "private:4"] {
            assert!(session_allowed(&cfg, key), "{key}");
        }
        for key in ["group:3", "private:1", "private:5", "channel:1", "private"] {
            assert!(!session_allowed(&cfg, key), "{key}");
        }
    }

    #[test]
    fn session_key_outside_allowlist_is_forbidden() {
        // TD-2：这 6 类端点原来只认 console token，不看目标会话在不在白名单里。
        let c = cfg();
        let bodies = [
            ("/api/socialV2/memory-append", json!({"key": "group:999999"})),
            ("/api/socialV2/memory-clear", json!({"key": "private:999999"})),
            ("/api/socialV2/mark-read", json!({"key": "group:999999"})),
            ("/api/socialV2/wake-config", json!({"key": "group:999999"})),
            (
                "/api/socialV2/initial-prompt",
                json!({"key": "group:999999", "text": "x"}),
            ),
            ("/api/session/reset", json!({"key": "group:999999"})),
            ("/api/socialV2/wait", json!({"key": "group:999999"})),
        ];
        for (path, body) in bodies {
            let (status, _, text) = route(&post_json(path, Some(TOKEN), body), &c);
            assert_eq!(status, 403, "{path} 带非法 key 必须 403：{text}");
            assert!(
                text.contains("不在允许范围内"),
                "{path} 的报错要能看出原因：{text}"
            );
        }

        // query 里的 key 一样要拦（GET initial-prompt，以及 memory 前缀分发）。
        for path in ["/api/socialV2/initial-prompt", "/api/memory/search"] {
            let r = get_with_query(path, Some(TOKEN), &[("key", "group:999999")]);
            assert_eq!(route(&r, &c).0, 403, "{path} 的 query key 也要校验");
        }

        // `/api/memory/*` 走的是自己那套 agent token 鉴权，但同一道检查必须罩住它。
        let mut r = get_with_query("/api/memory/search", None, &[("key", "group:999999")]);
        r.headers
            .insert("x-agent-token".to_string(), "whatever".to_string());
        assert_eq!(route(&r, &c).0, 403);
    }

    #[test]
    fn allowed_or_absent_key_behaves_as_before() {
        let c = cfg();
        // 合法 key：进到 handler 自己的校验（这里缺 category/content → 400；
        // 会话不存在则 404。两种都不是 403，且都不会写状态）。
        let r = post_json(
            "/api/socialV2/memory-append",
            Some(TOKEN),
            json!({"key": "group:7002"}),
        );
        let (status, _, text) = route(&r, &c);
        assert_ne!(status, 403, "白名单里的 key 不该被拦：{text}");
        assert!(
            status == 400 || status == 404,
            "应落到 handler 自己的校验：{status} {text}"
        );

        // 不带 key 的请求行为不变（列表类端点）。
        let r = get_with_query("/api/socialV2/initial-prompt", Some(TOKEN), &[]);
        assert_eq!(route(&r, &c).0, 200, "不带 key 的列表请求不受影响");
    }

    #[test]
    fn key_in_allowlist_handles_number_and_string_ids() {
        // 线上 allow.groups 是数字、allow.private 是字符串，两种都得认。
        let c = json!({
            "allow": { "groups": [7002, "7003"], "private": ["7001"] }
        });
        assert!(key_in_allowlist(&c, "group:7002"));
        assert!(key_in_allowlist(&c, "group:7003"));
        assert!(key_in_allowlist(&c, " private:7001 "));
        assert!(!key_in_allowlist(&c, "group:999999"));
        assert!(!key_in_allowlist(&c, "private:7002"));
        assert!(!key_in_allowlist(&c, "group:"));
        assert!(!key_in_allowlist(&c, "nickname:1"));
        assert!(!key_in_allowlist(&json!({}), "group:7002"));
    }

    #[test]
    fn social_v2_session_policy_matches_js_normalization_table() {
        // Frozen bridge.js loadConfig/allowed contract: normalize each list by
        // String(value).trim(), retain only decimal IDs, and use the documented
        // alias precedence before applying deny/allowAllWhenEmpty.
        let cases = [
            (
                "group prefers groups over group when both aliases exist",
                json!({"allow":{"groups":["222"],"group":["111"]}}),
                "group:222",
                true,
            ),
            (
                "group does not fall through to group alias when groups is present",
                json!({"allow":{"groups":["222"],"group":["111"]}}),
                "group:111",
                false,
            ),
            (
                "private prefers private over privates when both aliases exist",
                json!({"allow":{"private":["333"],"privates":["444"]}}),
                "private:333",
                true,
            ),
            (
                "private does not fall through to privates when private is present",
                json!({"allow":{"private":["333"],"privates":["444"]}}),
                "private:444",
                false,
            ),
            (
                "trim surrounding whitespace from string IDs",
                json!({"allow":{"groups":[" 123 "]}}),
                "group:123",
                true,
            ),
            (
                "String(number) normalizes integral JSON floats to decimal IDs",
                json!({"allow":{"groups":[123.0]}}),
                "group:123",
                true,
            ),
            (
                "JavaScript trim does not remove U+0085",
                json!({"allow":{"groups":["\u{0085}123\u{0085}"]},"allowAllWhenEmpty":true}),
                "group:987",
                true,
            ),
            (
                "String(-0) is a nonempty decimal ID and suppresses allowAllWhenEmpty",
                json!({"allow":{"groups":[-0.0]},"allowAllWhenEmpty":true}),
                "group:987",
                false,
            ),
            (
                "JavaScript exponent notation filters numbers at 1e21",
                json!({"allow":{"groups":[1e21]},"allowAllWhenEmpty":true}),
                "group:987",
                true,
            ),
            (
                "filter invalid allow entries before allowAllWhenEmpty",
                json!({"allow":{"groups":["not-an-id",123.5,true,null]},"allowAllWhenEmpty":true}),
                "group:987",
                true,
            ),
            (
                "invalid deny entries normalize away",
                json!({"deny":{"groups":["not-an-id",false]},"allowAllWhenEmpty":true}),
                "group:987",
                true,
            ),
            (
                "deny takes precedence over allowAllWhenEmpty",
                json!({"deny":{"groups":[" 123 "]},"allowAllWhenEmpty":true}),
                "group:123",
                false,
            ),
            (
                "nonempty normalized allow list disables allowAllWhenEmpty fallback",
                json!({"allow":{"groups":[" 123 "]},"allowAllWhenEmpty":true}),
                "group:987",
                false,
            ),
        ];

        for (name, cfg, key, expected) in cases {
            assert_eq!(
                social_v2_session_allowed(&cfg, key),
                expected,
                "case: {name}"
            );
        }
    }

