    #[test]
    fn concurrent_json_writes_stay_parseable_and_leave_no_tmp() {
        let stamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0);
        let dir = crate::install_root::development_root(std::env::temp_dir().join(format!("her-atomic-{}-{stamp}", std::process::id())));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("state.json").to_string_lossy().to_string();
        let mut handles = Vec::new();
        for i in 0..16 {
            let p = path.clone();
            handles.push(std::thread::spawn(move || {
                for j in 0..20 {
                    write_json_atomic(&p, &json!({ "writer": i, "round": j })).unwrap();
                }
            }));
        }
        for h in handles {
            h.join().unwrap();
        }
        let v = read_json(&path).expect("并发写完之后必须是完整 JSON");
        assert!(v.get("writer").is_some());
        let leftovers: Vec<String> = std::fs::read_dir(&dir)
            .unwrap()
            .filter_map(|e| e.ok())
            .map(|e| e.file_name().to_string_lossy().to_string())
            .filter(|n| n.ends_with(".tmp"))
            .collect();
        assert!(leftovers.is_empty(), "残留临时文件：{leftovers:?}");
        let _ = std::fs::remove_dir_all(&dir);
    }

