    #[test]
    fn send_message_global_agent_gates_are_selected_and_ordered() {
        let (root, context) = fixture_runtime(
            "send-message global agent gates",
            "fixture-send-message-console-token-abcdefghij",
        );
        let state_path = root.0.join("data/social-v2.json");
        let mode_path = root.0.join("data/mode.json");
        let mut cfg = context.load_config().unwrap();
        cfg["socialV2"]["enabled"] = json!(false);
        let make_request = |agent_token: Option<&str>, path: &str, method: &str| {
            let mut headers = HashMap::new();
            if let Some(token) = agent_token {
                headers.insert("x-agent-token".to_string(), token.to_string());
            }
            Request {
                method: method.to_string(),
                path: path.to_string(),
                query: HashMap::new(),
                headers,
                body: String::new(),
                body_too_large: false,
            }
        };

        // Empty credentials win before malformed state is read.
        std::fs::write(&state_path, b"not-json").unwrap();
        let bad_state = std::fs::read(&state_path).unwrap();
        assert_eq!(
            send_message_global_agent_denial(
                &make_request(Some(""), "/api/socialV2/send-message", "POST"),
                &cfg,
                &context,
            ),
            Some((403, "agent token 不能为空".to_string()))
        );
        assert_eq!(std::fs::read(&state_path).unwrap(), bad_state);
        assert_eq!(
            send_message_global_agent_denial(
                &make_request(Some(""), "/api/socialV2/send-message-extra", "POST"),
                &cfg,
                &context,
            ),
            None,
            "the gate is restricted to the exact route"
        );
        assert_eq!(
            send_message_global_agent_denial(
                &make_request(Some(""), "/api/socialV2/send-message", "GET"),
                &cfg,
                &context,
            ),
            None,
            "the gate is restricted to POST"
        );
        assert_eq!(
            send_message_global_agent_denial(
                &make_request(None, "/api/socialV2/send-message", "POST"),
                &cfg,
                &context,
            ),
            None,
            "console-only calls continue to the existing handler contract"
        );

        std::fs::write(
            &state_path,
            br#"{"paused":true,"conversations":{}}"#,
        )
        .unwrap();
        std::fs::write(&mode_path, br#"{"mode":"chat"}"#).unwrap();
        let request = make_request(Some("session-token"), "/api/socialV2/send-message", "POST");
        assert_eq!(
            send_message_global_agent_denial(&request, &cfg, &context),
            Some((403, "AI 已暂停，当前不允许执行 v2 工具".to_string()))
        );

        std::fs::write(
            &state_path,
            br#"{"paused":false,"conversations":{}}"#,
        )
        .unwrap();
        assert_eq!(
            send_message_global_agent_denial(&request, &cfg, &context),
            Some((403, "二代模式已关闭，当前不允许执行 v2 工具".to_string()))
        );

        cfg["socialV2"]["enabled"] = json!(true);
        assert_eq!(
            send_message_global_agent_denial(&request, &cfg, &context),
            Some((403, "该接口仅 reserved2 模式可用".to_string()))
        );
        std::fs::write(&mode_path, br#"{"mode":"reserved2"}"#).unwrap();
        assert_eq!(send_message_global_agent_denial(&request, &cfg, &context), None);
        drop(root);
    }

