    #[test]
    fn wake_safety_matches_js_buckets() {
        let now = 1_792_580_000_000i64;
        let wc = |triggers: Value, extra: Value| {
            let mut base = json!({ "infinite": true, "triggers": triggers, "confirmedAt": now });
            if let (Some(b), Some(e)) = (base.as_object_mut(), extra.as_object()) {
                for (k, v) in e {
                    b.insert(k.clone(), v.clone());
                }
            }
            base
        };

        // 只配了关键词：JS 把它算 hard（原来 Rust 算成 soft，会误报「可能永眠」）
        let only_kw = wc(json!({ "keywords": ["鲸鱼"] }), json!({}));
        let s = wake_safety(&only_kw, now);
        assert_eq!(s["hard"], true);
        assert_eq!(s["soft"], false);
        assert_eq!(s["guaranteed"], true);

        // 只有概率：soft，但 guaranteed 仍是 true（原来 guaranteed 漏了 soft）
        let only_prob = wc(json!({ "probability": 0.05 }), json!({}));
        let s = wake_safety(&only_prob, now);
        assert_eq!(s["hard"], false);
        assert_eq!(s["soft"], true);
        assert_eq!(s["guaranteed"], true);

        // 什么都没有：三项全 false，且 confirmedAt 是新的 → stale=false
        let none = wc(json!({}), json!({}));
        let s = wake_safety(&none, now);
        assert_eq!(s["guaranteed"], false);
        assert_eq!(s["stale"], false);

        // active 模式本身就是 hard
        let active = wc(json!({}), json!({ "mode": "active" }));
        assert_eq!(wake_safety(&active, now)["hard"], true);

        // 有限睡眠 + 未来时间 → timed
        let future = crate::sticker::iso_at(now + 3_600_000);
        let timed = wc(json!({}), json!({ "infinite": false, "sleepUntil": future }));
        assert_eq!(wake_safety(&timed, now)["timed"], true);

        // 过期 confirmedAt → stale
        let old = wc(json!({ "keywords": ["x"] }), json!({ "confirmedAt": now - 25 * 3600 * 1000 }));
        assert_eq!(wake_safety(&old, now)["stale"], true);
    }

    #[test]
    fn isolated_social_projections_and_unread_seen_writes_stay_selected() {
        let token_a = "fixture-state-read-token-aaaaaaaa";
        let token_b = "fixture-state-read-token-bbbbbbbb";
        let (root_a, context_a) = fixture_runtime("票据 03 projection A", token_a);
        let (root_b, context_b) = fixture_runtime("票据 03 projection B", token_b);
        let key = "private:7001";
        for (root, marker, base_seq) in [
            (&root_a.0, "alpha-projection", 0_i64),
            (&root_b.0, "beta-projection", 10_i64),
        ] {
            let state = json!({
                "conversations": {
                    (key): {
                        "wakeConfig": { "mode": "active", "marker": marker },
                        "unread": [
                            { "seq": base_seq + 1, "text": format!("{marker}-one") },
                            { "seq": base_seq + 2, "text": format!("{marker}-two") },
                            { "seq": base_seq + 3, "text": format!("{marker}-three") }
                        ],
                        "modelSeenSeqs": [base_seq + 3, 999],
                        "lastUnreadSeq": base_seq + 3,
                        "recentMessages": [],
                        "lastAiReplyAt": base_seq + 100
                    }
                }
            });
            std::fs::write(
                root.join("data/social-v2.json"),
                serde_json::to_vec(&state).unwrap(),
            )
            .unwrap();
        }
        let original_a = std::fs::read(root_a.0.join("data/social-v2.json")).unwrap();
        let original_b = std::fs::read(root_b.0.join("data/social-v2.json")).unwrap();

        let state_a = handle_social_state(&context_a, key).unwrap();
        let state_b = handle_social_state(&context_b, key).unwrap();
        assert_eq!(state_a["wakeConfig"]["marker"], "alpha-projection");
        assert_eq!(state_a["lastAiReplyAt"], 100);
        assert_eq!(state_b["wakeConfig"]["marker"], "beta-projection");
        assert_eq!(state_b["lastAiReplyAt"], 110);
        assert!(!state_a.to_string().contains("beta-projection"));
        assert!(!state_b.to_string().contains("alpha-projection"));

        // Console reads paginate from the tail and must not record model-seen state.
        let console_read = handle_unread(&context_a, key, 2, None, false).unwrap();
        assert_eq!(console_read["unreadCount"], 3);
        assert_eq!(console_read["messages"][0]["seq"], 2);
        assert_eq!(console_read["messages"][1]["seq"], 3);
        assert_eq!(
            std::fs::read(root_a.0.join("data/social-v2.json")).unwrap(),
            original_a,
            "console-only unread reads must not persist model-seen state"
        );

        // A model read after seq 1 records only messages actually returned from selected A.
        let agent_read = handle_unread(&context_a, key, 1, Some(1), true).unwrap();
        assert_eq!(agent_read["messages"].as_array().unwrap().len(), 1);
        assert_eq!(agent_read["messages"][0]["seq"], 2);
        let after_a: Value = serde_json::from_slice(
            &std::fs::read(root_a.0.join("data/social-v2.json")).unwrap(),
        )
        .unwrap();
        assert_eq!(std::fs::read(root_a.0.join("data/social-v2.json")).unwrap(), original_a, "an agent read must not write the receipt to the file");
        assert_eq!(agent::receipts_for(&context_a, key, &after_a["conversations"][key]), vec![2], "receipts seeded in the file are not receipts of this process");
        assert_eq!(agent_read["readThroughSeq"], 0, "unseen seq 1 must block the watermark");
        assert_eq!(
            std::fs::read(root_b.0.join("data/social-v2.json")).unwrap(),
            original_b,
            "selected A's model-seen write must not touch B"
        );

        assert_eq!(handle_pending(&context_a), json!({ "pending": [] }));
        assert_eq!(handle_pending(&context_b), json!({ "pending": [] }));
        drop((root_a, root_b));
    }

    fn retry_while_social_gate_busy(
        mut attempt: impl FnMut() -> Result<(), (u16, String)>,
    ) -> Result<(), (u16, String)> {
        for _ in 0..20 {
            match attempt() {
                Err((503, message)) if message == "selected runtime social state is busy" => {}
                other => return other,
            }
        }
        attempt()
    }

    #[test]
    fn isolated_social_seen_writers_serialize_and_preserve_concurrent_fields() {
        use std::sync::{mpsc, Arc, Barrier};
        use std::time::Duration;

        let (root, context) = fixture_runtime(
            "票据 03 social writer gate",
            "fixture-social-writer-gate-token",
        );
        let key = "private:7001";
        let initial = json!({
            "paused": false,
            "conversations": {
                (key): {
                    "unread": [{ "seq": 1 }, { "seq": 2 }],
                    "modelSeenSeqs": [],
                    "lastUnreadSeq": 2
                }
            }
        });
        std::fs::write(
            root.0.join("data/social-v2.json"),
            serde_json::to_vec(&initial).unwrap(),
        )
        .unwrap();

        // Hold an independent OS-lock handle. Every writer below starts from the same old
        // snapshot, then must wait and merge against the final file.
        let held_gate = context
            .open_locked_file(RuntimeArea::Data, "locks/social-v2.lock")
            .unwrap();
        let barrier = Arc::new(Barrier::new(4));
        let (started_tx, started_rx) = mpsc::channel();
        let (done_tx, done_rx) = mpsc::channel();
        let mut workers = Vec::new();

        for seq in [1_i64, 2_i64] {
            let worker_context = context.clone();
            let worker_barrier = Arc::clone(&barrier);
            let started = started_tx.clone();
            let done = done_tx.clone();
            let stale_snapshot = initial.clone();
            workers.push(std::thread::spawn(move || {
                let unread = [json!({ "seq": 1 }), json!({ "seq": 2 })];
                let seen = [json!({ "seq": seq })];
                worker_barrier.wait();
                started.send(()).unwrap();
                // Three writers serialize behind one bounded gate; an exact busy answer
                // is the documented bounded-wait result, so retry it with the same stale input.
                let result = retry_while_social_gate_busy(|| {
                    note_model_seen(
                        &worker_context,
                        &mut stale_snapshot.clone(),
                        key,
                        &unread,
                        &seen,
                    )
                });
                done.send(result).unwrap();
            }));
        }

        let activity_context = context.clone();
        let activity_barrier = Arc::clone(&barrier);
        let activity_started = started_tx.clone();
        let activity_done = done_tx.clone();
        workers.push(std::thread::spawn(move || {
            activity_barrier.wait();
            activity_started.send(()).unwrap();
            let result = retry_while_social_gate_busy(|| {
                handle_activity_post(&activity_context, r#"{"paused":true}"#).map(|_| ())
            });
            activity_done.send(result).unwrap();
        }));
        drop(started_tx);
        drop(done_tx);

        barrier.wait();
        for _ in 0..3 {
            started_rx
                .recv_timeout(Duration::from_secs(1))
                .expect("each writer must reach the gate attempt");
        }
        std::thread::sleep(Duration::from_millis(30));
        let early_result = done_rx.try_recv().ok();
        let finished_while_gate_held = early_result.is_some();
        drop(held_gate);

        for worker in workers {
            worker.join().expect("state writer thread must not panic");
        }
        let mut results: Vec<_> = early_result.into_iter().collect();
        results.extend(std::iter::from_fn(|| done_rx.try_recv().ok()));
        assert_eq!(results.len(), 3, "all state writers must finish after gate release");
        assert!(results.iter().all(Result::is_ok), "all state writes must succeed: {results:?}");
        assert!(
            !finished_while_gate_held,
            "selected social writers must honor the persistent OS gate"
        );

        let final_state: Value = serde_json::from_slice(
            &std::fs::read(root.0.join("data/social-v2.json")).unwrap(),
        )
        .unwrap();
        assert_eq!(final_state["paused"], true, "activity must not be lost to a stale seen snapshot");
        assert!(final_state["conversations"][key].get("modelSeenSeqs").map_or(true, |v| v == &json!([])), "the receipt is never persisted");
        assert_eq!(
            agent::receipts_for(&context, key, &final_state["conversations"][key]),
            vec![1, 2],
            "both concurrent unread reads must retain their seen receipts"
        );
        drop(root);
    }

    #[test]
    fn isolated_send_message_merges_concurrent_selected_social_updates() {
        use std::time::Duration;

        let key = "private:7001";
        let console_token_a = "fixture-send-rmw-console-a-abcdefghij";
        let console_token_b = "fixture-send-rmw-console-b-abcdefghij";
        let agent_token_a = "fixture-send-rmw-agent-a-abcdefghij";
        let agent_token_b = "fixture-send-rmw-agent-b-abcdefghij";
        let onebot_token_a = "fixture-send-rmw-onebot-a";
        let onebot_token_b = "fixture-send-rmw-onebot-b";
        let (root_a, _initial_context_a) = fixture_runtime("票据03发送并发合并 A", console_token_a);
        let (root_b, _initial_context_b) = fixture_runtime("票据03发送并发合并 B", console_token_b);

        let (selected_onebot_a, request_rx, release_tx, fake_onebot) = start_blocking_fake_onebot();
        let legacy_decoy_a = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        legacy_decoy_a.set_nonblocking(true).unwrap();
        let legacy_url_a = format!(
            "http://127.0.0.1:{}",
            legacy_decoy_a.local_addr().unwrap().port()
        );
        let unused_onebot_b = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        unused_onebot_b.set_nonblocking(true).unwrap();
        let selected_onebot_b = format!(
            "http://127.0.0.1:{}",
            unused_onebot_b.local_addr().unwrap().port()
        );

        let initial_a = prepare_send_message_fixture(
            &root_a,
            &selected_onebot_a,
            &legacy_url_a,
            onebot_token_a,
            agent_token_a,
            "root-a",
            1,
            vec![100, 200],
        );
        let _initial_b = prepare_send_message_fixture(
            &root_b,
            &selected_onebot_b,
            &selected_onebot_b,
            onebot_token_b,
            agent_token_b,
            "root-b",
            7,
            vec![700],
        );

        // RuntimeContext caches dependency URLs, so rebuild only after fixture JSON is final.
        let context_a = RuntimeContext::from_root(&root_a.0)
            .expect("selected A runtime must reload fixture dependencies");
        let context_b = RuntimeContext::from_root(&root_b.0)
            .expect("selected B runtime must reload fixture dependencies");
        assert_eq!(context_a.dependency_url("onebot"), Some(selected_onebot_a.as_str()));
        assert_eq!(context_b.dependency_url("onebot"), Some(selected_onebot_b.as_str()));

        let config_a_path = root_a.0.join("config/config.json");
        let dependencies_a_path = root_a.0.join("dependencies.json");
        let mode_a_path = root_a.0.join("data/mode.json");
        let social_a_path = root_a.0.join("data/social-v2.json");
        let config_b_path = root_b.0.join("config/config.json");
        let dependencies_b_path = root_b.0.join("dependencies.json");
        let mode_b_path = root_b.0.join("data/mode.json");
        let social_b_path = root_b.0.join("data/social-v2.json");
        let config_a_before = std::fs::read(&config_a_path).unwrap();
        let dependencies_a_before = std::fs::read(&dependencies_a_path).unwrap();
        let mode_a_before = std::fs::read(&mode_a_path).unwrap();
        let config_b_before = std::fs::read(&config_b_path).unwrap();
        let dependencies_b_before = std::fs::read(&dependencies_b_path).unwrap();
        let mode_b_before = std::fs::read(&mode_b_path).unwrap();
        let social_b_before = std::fs::read(&social_b_path).unwrap();

        let (console_port, console_server) = start_bounded_http_fixture(context_a.clone());
        let send_body = json!({
            "key": key,
            "messages": ["fixture send from selected A"],
            "gapMode": "fixed"
        })
        .to_string();
        let console_token = console_token_a.to_string();
        let agent_token = agent_token_a.to_string();
        let send_worker = std::thread::spawn(move || {
            http_json_with_agent(
                console_port,
                "POST",
                "/api/socialV2/send-message",
                &console_token,
                Some(&agent_token),
                Some(&send_body),
            )
        });

        let observed_request = request_rx.recv_timeout(Duration::from_secs(2)).ok();
        let concurrent_updates = if observed_request.is_some() {
            let activity = handle_activity_post(&context_a, r#"{"paused":true}"#);
            let mut seen_snapshot = initial_a.clone();
            let unread = [json!({ "seq": 1 })];
            let seen = [json!({ "seq": 1 })];
            let model_seen = note_model_seen(&context_a, &mut seen_snapshot, key, &unread, &seen);
            let state_while_response_blocked = std::fs::read(&social_a_path)
                .ok()
                .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok());
            Some((activity, model_seen, state_while_response_blocked))
        } else {
            None
        };

        let acknowledged_after = now_ms() as u64;
        let _ = release_tx.send(());
        let fake_result = fake_onebot
            .join()
            .map_err(|_| "fake OneBot thread panicked".to_string())
            .and_then(|result| result);
        let console_result = console_server
            .join()
            .map_err(|_| "console fixture thread panicked".to_string())
            .and_then(|result| result);
        let send_response = send_worker.join().ok();

        assert!(
            fake_result.is_ok(),
            "fake OneBot exchange failed: {fake_result:?}"
        );
        assert!(
            console_result.is_ok(),
            "console fixture failed: {console_result:?}"
        );
        let request = observed_request
            .expect("send-message must reach the selected fake OneBot before its response");
        assert_eq!(request.path, "/send_private_msg");
        assert_eq!(request.authorization, format!("Bearer {onebot_token_a}"));
        assert_eq!(request.body["user_id"], 7001);
        assert_eq!(
            request.body["message"],
            json!([{ "type": "text", "data": { "text": "fixture send from selected A" } }])
        );

        let (status, response) = send_response.expect("send-message HTTP worker must return");
        assert_eq!(status, 200);
        let mut response = response;
        assert!(
            response.as_object_mut().and_then(|fields| fields.remove("batchId")).is_some_and(|id| id.is_string()),
            "success responses carry the durable batch id"
        );
        assert_eq!(
            response,
            json!({
                "ok": true,
                "key": key,
                "sent": 1,
                "failed": 0,
                "delays": [],
                "quoted": null
            })
        );

        let (activity, model_seen, state_while_blocked) = concurrent_updates
            .expect("selected activity/seen updates must run while OneBot is blocked");
        assert_eq!(activity.unwrap(), json!({ "ok": true, "paused": true }));
        model_seen.expect("selected model-seen transaction must commit while OneBot is blocked");
        let state_while_blocked =
            state_while_blocked.expect("selected state must remain readable while OneBot is blocked");
        assert_eq!(state_while_blocked["paused"], true);
        assert!(state_while_blocked["conversations"][key].get("modelSeenSeqs").is_none() || state_while_blocked["conversations"][key]["modelSeenSeqs"] == json!([1]));
        assert_eq!(agent::receipts_for(&context_a, key, &state_while_blocked["conversations"][key]), vec![1]);

        let final_a: Value = serde_json::from_slice(&std::fs::read(&social_a_path).unwrap()).unwrap();
        let sent_at = final_a["conversations"][key]["sendTimes"]
            .as_array()
            .and_then(|times| times.last())
            .and_then(Value::as_u64)
            .expect("successful send must append its selected send timestamp");
        assert!(sent_at > 200);
        let delivered_at = final_a["conversations"][key]["lastAiReplyAt"].as_u64().unwrap();
        assert!(delivered_at>=sent_at && delivered_at>=acknowledged_after && delivered_at<=now_ms() as u64,
            "reply timestamps must witness delivery after the gateway was released");
        let mut expected_a = initial_a;
        expected_a["paused"] = json!(true);
        expected_a["conversations"][key]["modelSeenSeqs"] = json!([1]);
        expected_a["conversations"][key]["sendTimes"]
            .as_array_mut()
            .unwrap()
            .push(json!(sent_at));
        expected_a["conversations"][key]["lastAiReplyAt"] = json!(delivered_at);
        expected_a["conversations"][key]["lastActionAt"] = json!(delivered_at);
        expected_a["conversations"][key]["wakeConfig"]["noActionCount"] = json!(0);
        // The delivered text is also recorded as the bot's own recent message (JS recordSentMessagesV2).
        let own = final_a["conversations"][key]["recentMessages"].as_array().cloned().unwrap_or_default();
        assert_eq!(own.len(), 1);
        assert_eq!(own[0]["text"], "fixture send from selected A");
        assert_eq!(own[0]["isSelf"], true);
        assert_eq!(own[0]["time"],delivered_at);
        expected_a["conversations"][key]["recentMessages"] = json!(own);
        for field in ["preSleepWaitSatisfiedAt", "preSleepWaitObservedAt", "preSleepWaitAccumMs"] {
            expected_a["conversations"][key][field] = json!(0);
        }
        // Her delivered send starts her engagement window.
        expected_a["conversations"][key]["engagedAt"] = json!(delivered_at);
        // A stored receipt does not survive a state write (receipts are process memory).
        expected_a["conversations"][key].as_object_mut().unwrap().remove("modelSeenSeqs");
        assert_eq!(
            final_a, expected_a,
            "send success must merge its own timestamp/accounting delta into fresh selected state"
        );

        assert_eq!(std::fs::read(&config_a_path).unwrap(), config_a_before);
        assert_eq!(
            std::fs::read(&dependencies_a_path).unwrap(),
            dependencies_a_before
        );
        assert_eq!(std::fs::read(&mode_a_path).unwrap(), mode_a_before);
        assert_eq!(std::fs::read(&social_b_path).unwrap(), social_b_before);
        assert_eq!(std::fs::read(&config_b_path).unwrap(), config_b_before);
        assert_eq!(
            std::fs::read(&dependencies_b_path).unwrap(),
            dependencies_b_before
        );
        assert_eq!(std::fs::read(&mode_b_path).unwrap(), mode_b_before);
        assert_no_pending_tcp_connection(&legacy_decoy_a);
        assert_no_pending_tcp_connection(&unused_onebot_b);
        drop((root_a, root_b));
    }

