        let agent_token = "fixture-review-send-agent-token";
        let (root, _) = fixture_runtime("review-settlement-sharing", "synthetic-review-console-token");
        let (onebot_url, request_rx, release_tx, fake_onebot) = start_blocking_fake_onebot();
