    #[test]
    fn canonical_v2_key_and_agent_lookup_match_js_safe_integer_rules() {
        assert_eq!(canonical_v2_key("group:000123"), Some("group:123".to_string()));
        assert_eq!(
            canonical_v2_key("\u{00a0}private:000123\u{feff}"),
            Some("private:123".to_string()),
            "canonical keys use ECMAScript trim characters"
        );
        assert_eq!(
            canonical_v2_key("\u{0085}private:123"),
            None,
            "U+0085 is Rust whitespace but not ECMAScript String.trim whitespace"
        );
        assert_eq!(
            canonical_v2_key("private:9007199254740991"),
            Some("private:9007199254740991".to_string())
        );
        assert_eq!(canonical_v2_key("private:9007199254740992"), None);

        let state = json!({
            "conversations": {
                "group:123": { "agentToken": "canonical-token" },
                "private:9007199254740992": { "agentToken": "raw-unsafe-token" }
            }
        });
        assert!(agent_token_matches_state(&state, "group:000123", "canonical-token"));
        assert!(agent_token_matches_state(
            &state,
            "private:9007199254740992",
            "raw-unsafe-token"
        ));
        assert!(!agent_token_matches_state(&state, "group:000123", "wrong-token"));
        assert!(!social_v2_projection_session_allowed(
            &json!({ "allowAllWhenEmpty": true }),
            "\u{0085}private:123"
        ));
    }

