    #[test]
    fn note_model_seen_accepts_integral_float_sequences_only_in_process_memory() {
        let (root, context) = fixture_runtime("票据 03 float model-seen", "fixture-float-seen-token");
        let key = "private:7001";
        let unsafe_seq = 9_007_199_254_740_992_i64;
        let mut state = json!({
            "conversations": {
                (key): {
                    "unread": [{ "seq": 1.0 }, { "seq": unsafe_seq }],
                    "modelSeenSeqs": [unsafe_seq],
                    "lastUnreadSeq": 1,
                    "lastReadThroughSeq": 0
                }
            }
        });
        let original_bytes = serde_json::to_vec(&state).unwrap();
        std::fs::write(root.0.join("data/social-v2.json"), &original_bytes).unwrap();
        let unread = [json!({ "seq": 1.0 }), json!({ "seq": unsafe_seq })];
        let seen = [json!({ "seq": 1.0 }), json!({ "seq": unsafe_seq })];

        note_model_seen(&context, &mut state, key, &unread, &seen).unwrap();

        assert_eq!(
            state["conversations"][key]["modelSeenSeqs"],
            json!([1]),
            "safe integral-float seq is recorded; neither disk receipts nor newly offered unsafe seqs authorize reads"
        );
        assert_eq!(agent::receipts_for(&context, key, &state["conversations"][key]), vec![1]);
        assert_eq!(read_through_seq(&state["conversations"][key]), 1);
        let disk = std::fs::read(root.0.join("data/social-v2.json")).unwrap();
        assert_eq!(disk, original_bytes, "recording a process receipt must not rewrite the legacy file");
        drop(root);
    }

