    #[test]
    fn note_model_seen_ignores_disk_receipts_and_retains_live_integral_float_receipts() {
        let (root, context) = fixture_runtime(
            "票据 03 old float model-seen receipt",
            "fixture-old-float-seen-token",
        );
        let key = "private:7001";
        let unsafe_seq = 9_007_199_254_740_992_i64;
        let mut state = json!({
            "conversations": {
                (key): {
                    "unread": [{ "seq": 1 }, { "seq": unsafe_seq }],
                    "modelSeenSeqs": [1.0, unsafe_seq],
                    "lastUnreadSeq": 1,
                    "lastReadThroughSeq": 0
                }
            }
        });
        std::fs::write(
            root.0.join("data/social-v2.json"),
            serde_json::to_vec(&state).unwrap(),
        )
        .unwrap();
        let unread = [json!({ "seq": 1 }), json!({ "seq": unsafe_seq })];

        note_model_seen(&context, &mut state, key, &unread, &[])
            .expect("loading legacy receipts must not authorize reads");

        assert_eq!(
            state["conversations"][key]["modelSeenSeqs"],
            json!([]),
            "neither old integral-float nor unsafe receipts are restored from disk"
        );
        assert_eq!(read_through_seq(&state["conversations"][key]), 0);
        assert_eq!(agent::receipts_for(&context, key, &state["conversations"][key]), Vec::<i64>::new());

        note_model_seen(&context, &mut state, key, &unread, &[json!({ "seq": 1.0 })]).unwrap();
        note_model_seen(&context, &mut state, key, &unread, &[]).unwrap();
        assert_eq!(state["conversations"][key]["modelSeenSeqs"], json!([1]));
        assert_eq!(agent::receipts_for(&context, key, &state["conversations"][key]), vec![1]);
        assert_eq!(
            read_through_seq(&state["conversations"][key]),
            1,
            "a live integral-float receipt is retained across calls and advances the cursor"
        );
        let disk: Value = serde_json::from_slice(
            &std::fs::read(root.0.join("data/social-v2.json")).unwrap(),
        )
        .unwrap();
        assert_eq!(disk["conversations"][key]["modelSeenSeqs"], json!([1.0, unsafe_seq]),
            "receipt reads leave the legacy file untouched, without adding process receipts");
        update_selected_social_state(&context, |fresh| {
            fresh["conversations"][key]["lastReadThroughSeq"] = json!(1);
            Ok(())
        }).unwrap();
        let disk: Value = serde_json::from_slice(
            &std::fs::read(root.0.join("data/social-v2.json")).unwrap(),
        ).unwrap();
        assert!(disk["conversations"][key].get("modelSeenSeqs").is_none(),
            "the next state write strips legacy receipts instead of persisting live ones");
        assert_eq!(disk["conversations"][key]["lastReadThroughSeq"], 1);
        assert_eq!(agent::receipts_for(&context, key, &disk["conversations"][key]), vec![1]);
        drop(root);
    }

