    #[test]
    fn social_projection_agent_policy_matches_frozen_route_tools() {
        let state = json!({
            "conversations": {
                "private:7001": { "agentToken": "selected-agent-token" }
            }
        });
        let cfg = json!({
            "allow": { "private": ["7001"] },
            "socialV2": { "enabled": true, "tools": {} }
        });
        let cases = [
            ("socialState", "qq_social_state"),
            ("getUnread", "qq_get_unread_messages"),
            ("getRecent", "qq_get_recent_messages"),
            ("getMyRecent", "qq_get_my_recent_messages"),
            ("getActiveMembers", "qq_get_active_members"),
        ];
        for (tool_flag, tool_name) in cases {
            assert_eq!(
                social_projection_agent_denial(
                    &state,
                    &cfg,
                    "private:7001",
                    "selected-agent-token",
                    tool_flag,
                    tool_name,
                ),
                None,
                "{tool_flag} should use its frozen tool flag"
            );
            let disabled = json!({
                "allow": { "private": ["7001"] },
                "socialV2": { "enabled": true, "tools": { (tool_flag): false } }
            });
            assert_eq!(
                social_projection_agent_denial(
                    &state,
                    &disabled,
                    "private:7001",
                    "selected-agent-token",
                    tool_flag,
                    tool_name,
                ),
                Some((403, format!("工具未启用：{tool_name}")))
            );
        }
        assert_eq!(
            social_projection_agent_denial(
                &state,
                &cfg,
                "private:7001",
                "nonempty-but-wrong-token",
                "getUnread",
                "qq_get_unread_messages",
            ),
            Some((403, "agent token 无效".to_string()))
        );
        assert_eq!(
            social_projection_agent_denial(
                &state,
                &json!({
                    "allow": { "private": [] },
                    "allowAllWhenEmpty": false,
                    "socialV2": { "enabled": true, "tools": {} }
                }),
                "private:7001",
                "selected-agent-token",
                "getUnread",
                "qq_get_unread_messages",
            ),
            Some((403, "目标不在当前模式允许范围内".to_string()))
        );
    }

    #[test]
    fn social_projection_auth_and_policy_precede_safe_storage_key_validation() {
        let key = "private:9007199254740992";
        let token = "seeded-unsafe-key-agent-token";
        let state = json!({
            "conversations": {
                (key): { "agentToken": token }
            }
        });
        let cfg = json!({
            "allowAllWhenEmpty": true,
            "socialV2": { "enabled": true, "tools": {} }
        });

        assert_eq!(
            social_projection_agent_denial(
                &state,
                &cfg,
                key,
                "wrong-token",
                "socialState",
                "qq_social_state"
            ),
            Some((403, "agent token 无效".to_string())),
            "token validation must precede the later safe-key storage check"
        );
        assert_eq!(
            social_projection_agent_denial(
                &state,
                &cfg,
                key,
                token,
                "socialState",
                "qq_social_state"
            ),
            None,
            "frozen projection policy allows a seeded unsafe numeric key when allow-all is enabled"
        );
        let explicitly_allowed = json!({
            "allow": { "private": ["9007199254740992"] },
            "socialV2": { "enabled": true, "tools": {} }
        });
        assert_eq!(
            social_projection_agent_denial(
                &state,
                &explicitly_allowed,
                key,
                token,
                "socialState",
                "qq_social_state"
            ),
            None,
            "projection allow-list compares the JS numeric session id before storage validation"
        );
        let padded_allow = json!({
            "allow": { "private": ["09007199254740992"] },
            "socialV2": { "enabled": true, "tools": {} }
        });
        assert_eq!(
            social_projection_agent_denial(
                &state,
                &padded_allow,
                key,
                token,
                "socialState",
                "qq_social_state"
            ),
            Some((403, "目标不在当前模式允许范围内".to_string())),
            "allowed IDs compare as String(Number(id)); leading-zero config strings stay distinct"
        );
        let zero_padded_session = "private:07001";
        let alias_state = json!({
            "conversations": {
                "private:7001": { "agentToken": token }
            }
        });
        let canonical_allow = json!({
            "allow": { "private": ["7001"] },
            "socialV2": { "enabled": true, "tools": {} }
        });
        assert_eq!(
            social_projection_agent_denial(
                &alias_state,
                &canonical_allow,
                zero_padded_session,
                token,
                "socialState",
                "qq_social_state"
            ),
            None,
            "session IDs normalize through Number before the string allow-list comparison"
        );
        let zero_padded_config_allow = json!({
            "allow": { "private": ["007001"] },
            "socialV2": { "enabled": true, "tools": {} }
        });
        assert_eq!(
            social_projection_agent_denial(
                &alias_state,
                &zero_padded_config_allow,
                zero_padded_session,
                token,
                "socialState",
                "qq_social_state"
            ),
            Some((403, "目标不在当前模式允许范围内".to_string())),
            "configured IDs are compared as strings; leading zeros are not numerically normalized"
        );
        let denied = json!({
            "deny": { "private": ["9007199254740992"] },
            "allowAllWhenEmpty": true,
            "socialV2": { "enabled": true, "tools": {} }
        });
        assert_eq!(
            social_projection_agent_denial(
                &state,
                &denied,
                key,
                token,
                "socialState",
                "qq_social_state"
            ),
            Some((403, "目标不在当前模式允许范围内".to_string())),
            "deny-list wins even when allow-all is enabled"
        );
        assert_eq!(
            social_state_summary_for_request(&state, key).unwrap_err(),
            (400, format!("无效的会话 key：{key}")),
            "storage key validation follows successful projection authorization"
        );
    }

    #[test]
    fn isolated_projection_agent_authorization_and_seen_writes_stay_selected() {
        let token_a = "fixture-projection-console-a-abcdefghij";
        let token_b = "fixture-projection-console-b-abcdefghij";
        let agent_a = "fixture-selected-agent-a-aaaaaaaaa";
        let agent_b = "fixture-selected-agent-b-aaaaaaaaa";
        let (root_a, context_a) = fixture_runtime("票据 03 projection auth A", token_a);
        let (root_b, context_b) = fixture_runtime("票据 03 projection auth B", token_b);
        let key = "private:7001";

        for (root, agent_token, base_seq) in [
            (&root_a.0, agent_a, 0_i64),
            (&root_b.0, agent_b, 10_i64),
        ] {
            let config_path = root.join("config/config.json");
            let mut config: Value = serde_json::from_slice(&std::fs::read(&config_path).unwrap()).unwrap();
            config["allow"] = json!({ "groups": [], "private": ["7001"] });
            config["socialV2"] = json!({
                "enabled": true,
                "tools": {
                    "socialState": true,
                    "getUnread": true,
                    "getRecent": true,
                    "getMyRecent": true,
                    "getActiveMembers": true
                }
            });
            std::fs::write(&config_path, serde_json::to_vec(&config).unwrap()).unwrap();
            std::fs::write(root.join("data/mode.json"), br#"{"mode":"reserved2"}"#).unwrap();
            let state = json!({
                "conversations": {
                    (key): {
                        "agentToken": agent_token,
                        "unread": [
                            { "seq": base_seq + 1, "text": "one" },
                            { "seq": base_seq + 2, "text": "two" }
                        ],
                        "modelSeenSeqs": [],
                        "lastUnreadSeq": base_seq + 2,
                        "recentMessages": [
                            { "seq": base_seq + 1, "text": "one", "isSelf": false },
                            { "seq": base_seq + 2, "text": "two", "isSelf": false }
                        ]
                    }
                }
            });
            std::fs::write(
                root.join("data/social-v2.json"),
                serde_json::to_vec(&state).unwrap(),
            )
            .unwrap();
        }
        let cfg_a = context_a.load_config().unwrap();
        let original_a = std::fs::read(root_a.0.join("data/social-v2.json")).unwrap();
        let original_b = std::fs::read(root_b.0.join("data/social-v2.json")).unwrap();

        let wrong_token = social_projection_request_state(
            &context_a,
            &cfg_a,
            key,
            Some("arbitrary-nonempty-header"),
            "getRecent",
            "qq_get_recent_messages",
        );
        assert_eq!(wrong_token.unwrap_err(), (403, "agent token 无效".to_string()));
        assert_eq!(std::fs::read(root_a.0.join("data/social-v2.json")).unwrap(), original_a);
        assert_eq!(std::fs::read(root_b.0.join("data/social-v2.json")).unwrap(), original_b);

        let (selected_state, is_agent) = social_projection_request_state(
            &context_a,
            &cfg_a,
            key,
            Some(agent_a),
            "getRecent",
            "qq_get_recent_messages",
        )
        .unwrap();
        assert!(is_agent);
        let response = handle_recent_from_state(&context_a, selected_state, key, 20.0, 0.0, is_agent).unwrap();
        assert_eq!(response["messages"].as_array().unwrap().len(), 2);
        assert_eq!(response["readThroughSeq"], 2);
        let after_a: Value = serde_json::from_slice(
            &std::fs::read(root_a.0.join("data/social-v2.json")).unwrap(),
        )
        .unwrap();
        assert!(after_a["conversations"][key].get("modelSeenSeqs").map_or(true, |v| v == &json!([])), "the receipt is never persisted");
        assert_eq!(agent::receipts_for(&context_a, key, &after_a["conversations"][key]), vec![1, 2]);
        assert_eq!(std::fs::read(root_b.0.join("data/social-v2.json")).unwrap(), original_b);

        let mut disabled_config = cfg_a.clone();
        disabled_config["socialV2"]["tools"]["getUnread"] = json!(false);
        let before_denied_write = std::fs::read(root_a.0.join("data/social-v2.json")).unwrap();
        assert_eq!(
            social_projection_request_state(
                &context_a,
                &disabled_config,
                key,
                Some(agent_a),
                "getUnread",
                "qq_get_unread_messages",
            )
            .unwrap_err(),
            (403, "工具未启用：qq_get_unread_messages".to_string())
        );
        assert_eq!(std::fs::read(root_a.0.join("data/social-v2.json")).unwrap(), before_denied_write);
        drop((root_a, root_b));
    }

    #[test]
    fn social_unread_after_seq_matches_frozen_safe_integer_validation() {
        assert_eq!(parse_after_seq(None), Ok(None));
        assert_eq!(parse_after_seq(Some("0")), Ok(Some(0)));
        assert_eq!(parse_after_seq(Some("0002")), Ok(Some(2)));
        assert_eq!(parse_after_seq(Some("9007199254740991")), Ok(Some(9_007_199_254_740_991)));
        for raw in [
            "",
            "-1",
            "+1",
            "1.0",
            "1e2",
            " 1",
            "1 ",
            "9007199254740992",
            "18446744073709551616",
        ] {
            assert_eq!(
                parse_after_seq(Some(raw)),
                Err((
                    400,
                    "afterSeq 必须是非负安全整数；从最早未读开始请传 0".to_string()
                )),
                "unexpected afterSeq acceptance for {raw:?}"
            );
        }
    }

    #[test]
    fn social_projection_numeric_query_defaults_follow_js_number_or() {
        for raw in [None, Some(""), Some("  "), Some("0"), Some("NaN"), Some("bad")] {
            assert_eq!(js_query_number_or(raw, 30.0), 30.0, "{raw:?}");
        }
        assert_eq!(js_query_number_or(Some("\u{0085}1"), 30.0), 30.0);
        assert_eq!(js_query_number_or(Some("2.75"), 30.0), 2.75);
        assert_eq!(js_query_number_or(Some("-2.75"), 30.0), -2.75);
        assert_eq!(js_query_number_or(Some("inf"), 30.0), 30.0);
        assert_eq!(js_query_number_or(Some("Infinity"), 30.0), f64::INFINITY);
        assert_eq!(js_query_number_or(Some("0x10"), 30.0), 16.0);
        assert_eq!(
            js_query_number_or(Some("0x10000000000000000"), 30.0),
            18_446_744_073_709_551_616.0
        );
        assert_eq!(js_query_number_or(Some("0b10"), 30.0), 2.0);
        assert_eq!(js_query_number_or(Some("0o10"), 30.0), 8.0);
        assert_eq!(
            js_query_number_or(Some("0x10000000000000000"), 30.0).clamp(1.0, 100.0) as i64,
            100
        );
        assert_eq!(
            js_query_number_or(Some("Infinity"), 30.0).clamp(1.0, 100.0) as i64,
            100
        );
        assert_eq!(
            js_query_number_or(Some("-Infinity"), 30.0).clamp(1.0, 100.0) as i64,
            1
        );
        assert_eq!(
            js_query_number_or(Some("-2.75"), 30.0).clamp(0.0, f64::INFINITY) as i64,
            0
        );
        let state = json!({
            "conversations": {
                "group:7002": {
                    "recentMessages": [
                        { "seq": 0 }, { "seq": 1 }, { "seq": 2 }, { "seq": 3 }
                    ]
                }
            }
        });
        let fractional_offset = handle_recent_from_state(
            &RuntimeContext::legacy(),
            state.clone(),
            "group:7002",
            1.0,
            0.5,
            false,
        )
        .unwrap();
        assert_eq!(fractional_offset["messages"], json!([{ "seq": 2 }]));
        let fractional_limit = handle_recent_from_state(
            &RuntimeContext::legacy(),
            state,
            "group:7002",
            1.5,
            0.0,
            false,
        )
        .unwrap();
        assert_eq!(fractional_limit["messages"], json!([{ "seq": 2 }, { "seq": 3 }]));
    }

    #[test]
    fn social_projection_ignores_unsafe_sequence_numbers_for_cursor_and_new_seen() {
        let (root, context) = fixture_runtime(
            "票据 03 unsafe sequence numbers",
            "fixture-unsafe-sequence-console-token-abcdefghij",
        );
        let state = json!({
            "conversations": {
                "group:7002": {
                    "agentToken": "fixture-unsafe-sequence-agent-token",
                    "unread": [
                        { "seq": 1, "text": "safe-one" },
                        { "seq": 9007199254740992_i64, "text": "unsafe" },
                        { "seq": 2, "text": "safe-two" }
                    ],
                    "modelSeenSeqs": [9007199254740992_i64],
                    "lastUnreadSeq": 2,
                    "lastReadThroughSeq": 0
                }
            }
        });
        std::fs::write(
            root.0.join("data/social-v2.json"),
            serde_json::to_vec(&state).unwrap(),
        )
        .unwrap();
        let result = handle_unread_from_state(
            &context,
            state.clone(),
            "group:7002",
            30,
            Some(0),
            true,
        )
        .unwrap();
        assert_eq!(result["unreadCount"], 3);
        assert_eq!(result["messages"], json!([
            { "seq": 1, "text": "safe-one" },
            { "seq": 2, "text": "safe-two" }
        ]));
        assert_eq!(result["readThroughSeq"], 2);
        assert_eq!(
            agent::receipts_for(&context, "group:7002", &state["conversations"]["group:7002"]),
            vec![1, 2],
            "only the safe messages returned to the model create process receipts"
        );
        let persisted: Value = serde_json::from_slice(
            &std::fs::read(root.0.join("data/social-v2.json")).unwrap(),
        )
        .unwrap();
        assert_eq!(
            persisted["conversations"]["group:7002"]["modelSeenSeqs"],
            json!([9007199254740992_i64]),
            "the legacy disk receipt is inert and new safe receipts stay in process memory"
        );
        assert_eq!(persisted, state, "an unread projection does not persist receipts or advance the durable mark");
        drop(root);
    }

    #[test]
    fn isolated_current_mode_rejects_invalid_selected_shapes_without_mutation() {
        let (root_a, context_a) = fixture_runtime(
            "ticket 03 selected mode shape A",
            "fixture-mode-shape-console-a",
        );
        let (root_b, context_b) = fixture_runtime(
            "ticket 03 selected mode shape B",
            "fixture-mode-shape-console-b",
        );
        let mode_a = root_a.0.join("data/mode.json");
        let mode_b = root_b.0.join("data/mode.json");
        std::fs::write(&mode_b, br#"{"mode":"chat"}"#).unwrap();

        assert!(
            !mode_a.exists(),
            "fixture A starts with a missing selected mode file"
        );
        assert_eq!(current_mode_for(&context_a), Ok("reserved2".to_string()));
        assert_eq!(current_mode_for(&context_b), Ok("chat".to_string()));

        std::fs::write(&mode_a, b"{}").unwrap();
        assert_eq!(
            current_mode_for(&context_a),
            Ok("reserved2".to_string()),
            "a missing mode member retains the legacy Rust default"
        );
        let valid_documents: &[(&[u8], &str)] = &[
            (br#"{"mode":"reserved2"}"#, "reserved2"),
            (br#"{"mode":"reserved"}"#, "reserved"),
            (br#"{"mode":"chat"}"#, "chat"),
            (br#"{"mode":"closed-agent"}"#, "closed-agent"),
        ];
        for (document, expected) in valid_documents {
            std::fs::write(&mode_a, *document).unwrap();
            assert_eq!(current_mode_for(&context_a), Ok((*expected).to_string()));
        }

        let config_path_a = root_a.0.join("config/config.json");
        let config_path_b = root_b.0.join("config/config.json");
        let mut config_a: Value =
            serde_json::from_slice(&std::fs::read(&config_path_a).unwrap()).unwrap();
        config_a["socialV2"] = json!({ "enabled": true });
        std::fs::write(&config_path_a, serde_json::to_vec(&config_a).unwrap()).unwrap();
        let cfg_a = context_a.load_config().unwrap();
        let state_path_a = root_a.0.join("data/social-v2.json");
        let state_path_b = root_b.0.join("data/social-v2.json");
        let config_a_before = std::fs::read(&config_path_a).unwrap();
        let config_b_before = std::fs::read(&config_path_b).unwrap();
        let state_a_before = std::fs::read(&state_path_a).unwrap();
        let state_b_before = std::fs::read(&state_path_b).unwrap();
        let mode_b_before = std::fs::read(&mode_b).unwrap();
        let request = Request {
            method: "GET".to_string(),
            path: "/api/socialV2/state".to_string(),
            query: std::collections::HashMap::new(),
            headers: [(
                "x-agent-token".to_string(),
                "synthetic-agent-token".to_string(),
            )]
            .into_iter()
            .collect(),
            body: String::new(),
            body_too_large: false,
        };
        let invalid_documents: &[(&[u8], &str)] = &[
            (b"null", "top-level null"),
            (b"[]", "top-level array"),
            (b"7", "top-level number"),
            (b"true", "top-level boolean"),
            (br#""reserved2""#, "top-level string"),
            (br#"{"mode":null}"#, "null mode"),
            (br#"{"mode":7}"#, "numeric mode"),
            (br#"{"mode":true}"#, "boolean mode"),
            (br#"{"mode":[]}"#, "array mode"),
            (br#"{"mode":{}}"#, "object mode"),
            (b"{", "malformed JSON"),
        ];

        for (document, label) in invalid_documents {
            std::fs::write(&mode_a, *document).unwrap();
            let error = (500, "runtime mode is invalid".to_string());
            assert_eq!(
                current_mode_for(&context_a),
                Err(error.clone()),
                "{label} must fail closed"
            );
            assert_eq!(
                social_agent_policy_denial(&request, &cfg_a, &context_a),
                Some(error),
                "{label} must not be treated as reserved2 by the agent gate"
            );
            assert_eq!(
                std::fs::read(&mode_a).unwrap(),
                *document,
                "{label} parser must not rewrite the selected mode file"
            );
            assert_eq!(std::fs::read(&config_path_a).unwrap(), config_a_before);
            assert_eq!(std::fs::read(&state_path_a).unwrap(), state_a_before);
            assert_eq!(std::fs::read(&mode_b).unwrap(), mode_b_before);
            assert_eq!(std::fs::read(&config_path_b).unwrap(), config_b_before);
            assert_eq!(std::fs::read(&state_path_b).unwrap(), state_b_before);
        }

        drop((root_a, root_b));
    }
    #[test]
    fn pending_admin_gate_is_exact_and_keeps_console_auth_priority() {
        let cfg = cfg();
        let context = RuntimeContext::legacy();
        let console_token = cfg["consoleToken"].as_str().unwrap().to_string();
        let mut request = Request {
            method: "GET".to_string(),
            path: "/api/pending".to_string(),
            query: [("key".to_string(), "group:9999999".to_string())]
                .into_iter()
                .collect(),
            headers: [("x-console-token".to_string(), console_token)]
                .into_iter()
                .collect(),
            body: String::new(),
            body_too_large: false,
        };
        assert!(pending_admin_agent_gate_route(&request));

        request.headers.insert("x-agent-token".to_string(), String::new());
        let (empty_status, _, empty_body) = route_with_context(&request, &cfg, &context);
        assert_eq!(empty_status, 403);
        assert_eq!(
            serde_json::from_str::<Value>(&empty_body).unwrap()["error"],
            "agent token 不能为空"
        );

        request.headers.insert(
            "x-agent-token".to_string(),
            "synthetic-agent".to_string(),
        );
        let (agent_status, _, agent_body) = route_with_context(&request, &cfg, &context);
        assert_eq!(agent_status, 403);
        assert_eq!(
            serde_json::from_str::<Value>(&agent_body).unwrap()["error"],
            "该接口仅控制台可用"
        );

        request.headers.insert(
            "x-console-token".to_string(),
            "wrong-synthetic-console-token".to_string(),
        );
        let (wrong_console_status, _, wrong_console_body) =
            route_with_context(&request, &cfg, &context);
        assert_eq!(
            wrong_console_status,
            401,
            "console authentication must precede pending policy even with a denied query key"
        );
        assert_eq!(
            serde_json::from_str::<Value>(&wrong_console_body).unwrap()["error"],
            "未授权：请提供控制台访问令牌"
        );

        request.headers.remove("x-console-token");
        let (unauthorized_status, _, unauthorized_body) =
            route_with_context(&request, &cfg, &context);
        assert_eq!(
            unauthorized_status,
            401,
            "missing console auth must precede the agent-only gate"
        );
        assert_eq!(
            serde_json::from_str::<Value>(&unauthorized_body).unwrap()["error"],
            "未授权：请提供控制台访问令牌"
        );

        for (method, path) in [
            ("POST", "/api/pending"),
            ("GET", "/api/pending/extra"),
            ("GET", "/api/socialV2/pending"),
        ] {
            request.method = method.to_string();
            request.path = path.to_string();
            assert_eq!(
                pending_agent_denial(&request),
                None,
                "unexpected gate for {method} {path}"
            );
            assert!(!pending_admin_agent_gate_route(&request));
        }
    }

    #[test]
    fn activity_agent_policy_is_admin_only_for_activity_path_across_methods() {
        let (root, context) = fixture_runtime(
            "票据 04 activity agent policy",
            "fixture-activity-console-token-abcdefghij",
        );
        let state_path = root.0.join("data/social-v2.json");
        let mode_path = root.0.join("data/mode.json");
        let mut cfg = context.load_config().unwrap();
        cfg["socialV2"] = json!({"enabled": true});
        let console_token = cfg["consoleToken"].as_str().unwrap().to_string();
        let mut request = Request {
            method: "POST".to_string(),
            path: "/api/socialV2/activity".to_string(),
            query: std::collections::HashMap::new(),
            headers: [
                ("x-console-token".to_string(), console_token),
                ("x-agent-token".to_string(), "synthetic-agent".to_string()),
            ]
            .into_iter()
            .collect(),
            body: r#"{"paused":true}"#.to_string(),
            body_too_large: false,
        };
        assert!(social_agent_policy_route(&request));

        let unpaused = br#"{"paused":false,"conversations":{}}"#;
        std::fs::write(&state_path, unpaused).unwrap();
        std::fs::write(&mode_path, br#"{"mode":"reserved2"}"#).unwrap();
        assert_eq!(
            social_agent_policy_denial(&request, &cfg, &context),
            Some((403, "该接口仅控制台可用".to_string()))
        );
        assert_eq!(std::fs::read(&state_path).unwrap(), unpaused);

        request.headers.insert("x-agent-token".to_string(), String::new());
        assert_eq!(
            social_agent_policy_denial(&request, &cfg, &context),
            Some((403, "agent token 不能为空".to_string()))
        );
        assert_eq!(std::fs::read(&state_path).unwrap(), unpaused);
        request.headers.insert(
            "x-agent-token".to_string(),
            "synthetic-agent".to_string(),
        );

        let paused = br#"{"paused":true,"conversations":{}}"#;
        std::fs::write(&state_path, paused).unwrap();
        assert_eq!(
            social_agent_policy_denial(&request, &cfg, &context),
            Some((403, "AI 已暂停，当前不允许执行 v2 工具".to_string()))
        );
        assert_eq!(std::fs::read(&state_path).unwrap(), paused);

        std::fs::write(&state_path, unpaused).unwrap();
        cfg["socialV2"]["enabled"] = json!(false);
        assert_eq!(
            social_agent_policy_denial(&request, &cfg, &context),
            Some((403, "二代模式已关闭，当前不允许执行 v2 工具".to_string()))
        );
        assert_eq!(std::fs::read(&state_path).unwrap(), unpaused);

        cfg["socialV2"]["enabled"] = json!(true);
        std::fs::write(&mode_path, br#"{"mode":"chat"}"#).unwrap();
        assert_eq!(
            social_agent_policy_denial(&request, &cfg, &context),
            Some((403, "该接口仅 reserved2 模式可用".to_string()))
        );
        assert_eq!(std::fs::read(&state_path).unwrap(), unpaused);

        std::fs::write(&mode_path, br#"{"mode":"reserved2"}"#).unwrap();
        for method in ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"] {
            request.method = method.to_string();
            assert!(social_agent_policy_route(&request));
            assert_eq!(
                social_agent_policy_denial(&request, &cfg, &context),
                Some((403, "该接口仅控制台可用".to_string())),
                "agent activity request must remain admin-only for {method}"
            );
            assert_eq!(std::fs::read(&state_path).unwrap(), unpaused);
        }

        request.method = "POST".to_string();
        request.path.push('/');
        assert!(!social_agent_policy_route(&request));
        assert_eq!(social_agent_policy_denial(&request, &cfg, &context), None);
        assert_eq!(std::fs::read(&state_path).unwrap(), unpaused);
        drop(root);
    }

    #[test]
    fn v1_sticker_admin_policy_is_stateless_exact_prefix_across_methods() {
        let (root_a, context_a) = fixture_runtime(
            "ticket 03 v1 sticker policy A",
            "fixture-v1-sticker-console-a",
        );
        let (root_b, context_b) = fixture_runtime(
            "ticket 03 v1 sticker policy B",
            "fixture-v1-sticker-console-b",
        );
        let state_a = root_a.0.join("data/social-v2.json");
        let state_b = root_b.0.join("data/social-v2.json");
        let mode_a = root_a.0.join("data/mode.json");
        let mode_b = root_b.0.join("data/mode.json");
        let config_a = root_a.0.join("config/config.json");
        let config_b = root_b.0.join("config/config.json");

        std::fs::write(&state_a, b"{corrupt selected social state").unwrap();
        std::fs::write(&mode_a, b"[]").unwrap();
        std::fs::write(&state_b, br#"{"paused":true,"conversations":{}}"#).unwrap();
        std::fs::write(&mode_b, br#"{"mode":"chat"}"#).unwrap();
        let mut cfg_a = context_a.load_config().unwrap();
        cfg_a["socialV2"] = json!({"enabled": false});
        std::fs::write(&config_a, serde_json::to_vec_pretty(&cfg_a).unwrap()).unwrap();
        let mut cfg_b = context_b.load_config().unwrap();
        cfg_b["socialV2"] = json!({"enabled": true});
        std::fs::write(&config_b, serde_json::to_vec_pretty(&cfg_b).unwrap()).unwrap();
        cfg_a = context_a.load_config().unwrap();
        cfg_b = context_b.load_config().unwrap();

        let exercise = |context: &RuntimeContext, cfg: &Value, label: &str| {
            let methods = ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"];
            let paths = [
                "/api/stickers",
                "/api/stickers/",
                "/api/stickers/sync",
                "/api/stickers/note",
                "/api/stickers/remark",
                "/api/stickers/unknown/child",
            ];
            for method in methods {
                for path in paths {
                    let mut request = req(method, path, None);
                    request.headers.insert(
                        "x-agent-token".to_string(),
                        "synthetic-agent".to_string(),
                    );
                    assert!(
                        social_agent_policy_route(&request),
                        "V1 sticker prefix must classify every method: {label} {method} {path}"
                    );
                    assert_eq!(
                        social_agent_policy_denial(&request, cfg, context),
                        Some((403, "该接口仅控制台可用".to_string())),
                        "V1 sticker denial must precede V2 state/config/mode gates: {label} {method} {path}"
                    );
                    request.headers.insert("x-agent-token".to_string(), String::new());
                    assert_eq!(
                        social_agent_policy_denial(&request, cfg, context),
                        Some((403, "agent token 不能为空".to_string())),
                        "empty agent credential keeps its first-priority error: {label} {method} {path}"
                    );
                }
            }
            for path in ["/api/stickers2", "/api/stickers2/child", "/api/stickers-preview"] {
                let request = Request {
                    method: "GET".to_string(),
                    path: path.to_string(),
                    query: std::collections::HashMap::new(),
                    headers: [("x-agent-token".to_string(), "synthetic-agent".to_string())]
                        .into_iter()
                        .collect(),
                    body: String::new(),
                    body_too_large: false,
                };
                assert!(
                    !social_agent_policy_route(&request),
                    "V1 sticker prefix must not swallow adjacent names: {label} {path}"
                );
                assert_eq!(social_agent_policy_denial(&request, cfg, context), None);
            }
        };

        let snapshots = || {
            (
                std::fs::read(&state_a).unwrap(),
                std::fs::read(&state_b).unwrap(),
                std::fs::read(&mode_a).unwrap(),
                std::fs::read(&mode_b).unwrap(),
                std::fs::read(&config_a).unwrap(),
                std::fs::read(&config_b).unwrap(),
            )
        };
        let before_corrupt_paused = snapshots();
        exercise(&context_a, &cfg_a, "A-corrupt-state-disabled-config");
        exercise(&context_b, &cfg_b, "B-paused-state-chat-mode");
        assert_eq!(snapshots(), before_corrupt_paused, "agent denials must not rewrite either selected root");

        // Independently exercise valid-but-disabled and valid non-reserved2 state, which JS V1 never gates.
        std::fs::write(&state_a, br#"{"paused":false,"conversations":{}}"#).unwrap();
        std::fs::write(&mode_a, br#"{"mode":"reserved2"}"#).unwrap();
        std::fs::write(&state_b, br#"{"paused":false,"conversations":{}}"#).unwrap();
        std::fs::write(&mode_b, br#"{"mode":"chat"}"#).unwrap();
        let before_valid_modes = snapshots();
        exercise(&context_a, &cfg_a, "A-unpaused-disabled-config");
        exercise(&context_b, &cfg_b, "B-unpaused-chat-mode");
        assert_eq!(snapshots(), before_valid_modes, "V1 policy checks must remain read-only across both roots");

        drop((root_a, root_b));
    }

