    #[test]
    fn confirmed_collect_is_not_an_error_when_its_settle_step_fails() {
        let (url, server) = start_fake_onebot(2, false);
        let (root, context, decoy) = t20_selected("t20 collect settle", &url, json!({
            "recentMessages": [t20_source_message()], "stickerCollectTimes": []
        }));
        STICKER_SETTLE_FAULT_HOOK.with(|hook| *hook.borrow_mut() = Some(Box::new(|_| Err((503, "gate busy".to_string())))));
        let result = t20_collect(&context, &context.load_config().unwrap(), |_, _| Ok(b"image".to_vec()));
        STICKER_SETTLE_FAULT_HOOK.with(|hook| *hook.borrow_mut() = None);
        server.join().unwrap();
        let value = result.expect("the favorite was added; a failed settle must not turn it into an error");
        assert_eq!(value["ok"], true);
        // The identified reservation stays: it is the confirmed operation's quota liability.
        assert_eq!(t20_conversation(&root)["stickerCollectPending"].as_array().unwrap().len(), 1);
        assert_no_pending_tcp_connection(&decoy);
    }

    #[test]
    fn confirmed_send_settles_inside_the_social_update_transaction() {
        let (url, server) = start_fake_onebot_with_sticker_rows(2, false, vec![t20_sticker_row()]);
        let (root, context, decoy) = t20_selected("t20 send fold", &url, json!({"recentMessages": [], "sendTimes": []}));
        // A standalone settle would fail here; the confirmed send must not depend on one.
        STICKER_SETTLE_FAULT_HOOK.with(|hook| *hook.borrow_mut() = Some(Box::new(|_| Err((503, "gate busy".to_string())))));
        let result = t20_send(&context, &context.load_config().unwrap(), "fixture-sticker", |_, _| Ok(b"image".to_vec()));
        STICKER_SETTLE_FAULT_HOOK.with(|hook| *hook.borrow_mut() = None);
        server.join().unwrap();
        assert!(result.is_ok(), "{result:?}");
        let conv = t20_conversation(&root);
        assert!(conv.get("stickerSendPending").is_none(), "{conv}");
        assert_eq!(conv["sendTimes"].as_array().unwrap().len(), 1);
        assert_eq!(conv["stickerSendProtected"].as_array().unwrap().len(), 1);
        assert_eq!(conv["recentMessages"].as_array().unwrap().len(), 1, "history and quota land in one write");
        assert_no_pending_tcp_connection(&decoy);
    }

    #[test]
    fn settlement_without_its_pending_entry_still_records_a_retained_slot() {
        let key = "private:1";
        let mut state = json!({"conversations": {(key): {"sendTimes": [5]}}});
        apply_sticker_settlement(&mut state, key, "sendTimes", "stickerSendPending", "gone", 77, true).unwrap();
        assert_eq!(state["conversations"][key]["sendTimes"], json!([5, 77]));
        assert_eq!(state["conversations"][key]["stickerSendProtected"], json!([{"id":"gone", "time":77}]));
        let mut state = json!({"conversations": {(key): {"sendTimes": [5]}}});
        apply_sticker_settlement(&mut state, key, "sendTimes", "stickerSendPending", "gone", 77, false).unwrap();
        assert_eq!(state["conversations"][key]["sendTimes"], json!([5]), "a release of a missing entry changes nothing");
    }

    #[test]
    fn failed_release_does_not_keep_a_proven_unsubmitted_collect_counted() {
        let (url, server) = start_fake_onebot(0, false);
        let (root, context, decoy) = t20_selected("t20 collect release", &url, json!({
            "recentMessages": [t20_source_message()], "stickerCollectTimes": []
        }));
        let mut cfg = context.load_config().unwrap();
        cfg["socialV2"]["sticker"]["collect"]["maxPerMinute"] = json!(1);
        STICKER_SETTLE_FAULT_HOOK.with(|hook| *hook.borrow_mut() = Some(Box::new(|retain| {
            if retain { Ok(()) } else { Err((503, "gate busy".to_string())) }
        })));
        let first = t20_collect(&context, &cfg, |_, _| Err("cdn down".to_string())).unwrap_err();
        assert_eq!(first.0, 500, "the real cause is reported, not the failed release: {first:?}");
        assert!(first.1.starts_with("收藏表情失败：无法安全获取该图片字节"), "{first:?}");
        assert_eq!(t20_conversation(&root)["stickerCollectPending"].as_array().unwrap().len(), 1, "release failed");
        let second = t20_collect(&context, &cfg, |_, _| Err("cdn down".to_string())).unwrap_err();
        STICKER_SETTLE_FAULT_HOOK.with(|hook| *hook.borrow_mut() = None);
        assert_eq!(second.0, 500, "the abandoned reservation must not count against the next attempt: {second:?}");
        server.join().unwrap();
        assert_no_pending_tcp_connection(&decoy);
    }

